nilla = clientDataFiltro.data_planilla_motor.id\n    clientDataFiltro.obsRevisarPlanilla = obs\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n        \"Properties\": {\n            \"Title\": `Rechazar Planilla`,\n            \"Message\": `¿Estás seguro de que deseas rechazar la planilla No.${clientDataFiltro.data_planilla_motor.numero} de Aceite Motor?`,\n            \"OKCaption\": \"Aceptar\",\n            \"OnOK\": \"/appconsumos_qa_mb/Actions/oData/Update_Planilla_Aceite_Rechazar.action\",\n            \"CancelCaption\": \"Cancelar\"\n        }\n    })\n}","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Rechazar_Planilla_Aceite_Reductor(context) {\n    let clientDataFiltro = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Aceite_Reductor').getClientData();\n\n    let obs = context.evaluateTargetPath('#Page:Revisar_Planilla_Aceite_Reductor/#Control:FormCellNote0/#Value');\n    clientDataFiltro.QueryRevisarPlanilla = clientDataFiltro.data_planilla_reductor.id\n    clientDataFiltro.obsRevisarPlanilla = obs\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n        \"Properties\": {\n            \"Title\": `Rechazar Planilla`,\n            \"Message\": `¿Estás seguro de que deseas rechazar la planilla No.${clientDataFiltro.data_planilla_reductor.numero} de Aceite Reductor?`,\n            \"OKCaption\": \"Aceptar\",\n            \"OnOK\": \"/appconsumos_qa_mb/Actions/oData/Update_Planilla_Aceite_Rechazar_Reductor.action\",\n            \"CancelCaption\": \"Cancelar\"\n        }\n    })\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Rechazar_Planilla_Aceite_Servotransmisor(context) {\n    let clientDataFiltro = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Aceite_Servotransmisor').getClientData();\n\n    let obs = context.evaluateTargetPath('#Page:Revisar_Planilla_Aceite_Servotransmisor/#Control:FormCellNote0/#Value');\n    clientDataFiltro.QueryRevisarPlanilla = clientDataFiltro.data_planilla_servotrans.id\n    clientDataFiltro.obsRevisarPlanilla = obs\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n        \"Properties\": {\n            \"Title\": `Rechazar Planilla`,\n            \"Message\": `¿Estás seguro de que deseas rechazar la planilla No.${clientDataFiltro.data_planilla_servotrans.numero} de Aceite Servotransmisor?`,\n            \"OKCaption\": \"Aceptar\",\n            \"OnOK\": \"/appconsumos_qa_mb/Actions/oData/Update_Planilla_Aceite_Rechazar_Servotransmisor.action\",\n            \"CancelCaption\": \"Cancelar\"\n        }\n    })\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Redraw_Detalle_Planillas(context) {\n    const pageProxy = context.getPageProxy();\n    pageProxy.redraw()\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nimport guid from '../guid'\n\nexport default function Registrar_Items_Aceite_Diferencial(context) {\n    try {\n        // Obtener valores de los controles\n        let equipo = context.evaluateTargetPath('#Page:Registrar_Aceite_Diferencial/#Control:equipo_diferencial/#Value');\n        let tipo = context.evaluateTargetPath('#Page:Registrar_Aceite_Diferencial/#Control:tipo_diferencial/#Value');\n        let kmh = context.evaluateTargetPath('#Page:Registrar_Aceite_Diferencial/#Control:kmh_diferencial/#Value');\n        let operario_diferencial = context.evaluateTargetPath('#Page:Registrar_Aceite_Diferencial/#Control:operario_diferencial/#Value');\n        let cont_inicial = context.evaluateTargetPath('#Page:Registrar_Aceite_Diferencial/#Control:cont_inicial_diferencial/#Value');\n        let cont_final = context.evaluateTargetPath('#Page:Registrar_Aceite_Diferencial/#Control:con_final_diferencial/#Value');\n        let observaciones = context.evaluateTargetPath('#Page:Registrar_Aceite_Diferencial/#Control:observaciones_diferencial/#Value');\n        let orden = context.evaluateTargetPath('#Page:Registrar_Aceite_Diferencial/#Control:orden_diferencial/#Value');\n        \n        let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n        let id_planilla = clientData.data_planilla_diferencial.id;\n\n        // Obtener controles del formulario\n        const pageProxy = context.getPageProxy();\n        const form_add = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\");\n        const btn_agregar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\");\n\n        // Conversión de datos\n        let contadorIniNum = parseFloat(cont_inicial) || 0;\n        let contadorFinNum = parseFloat(cont_final) || 0;\n        let kilometrajeNum = parseFloat(kmh) || 0;\n        let operario_diferencialString = String(operario_diferencial) || \"\";\n        let equipoData = null;\n        let tipoData = null;\n        let observacionesData = null;\n        let observacionesTxtData = null;\n        let ordenData = null;\n        let reservaData = null;\n\n        // Extraer datos de equipo\n        if (equipo && Array.isArray(equipo) && equipo.length > 0 && equipo[0] && equipo[0].BindingObject) {\n            equipoData = equipo[0].BindingObject.equipo;\n        }\n\n        // Extraer datos de tipo\n        if (tipo && Array.isArray(tipo) && tipo.length > 0 && tipo[0]) {\n            tipoData = tipo[0].DisplayValue;\n        }\n\n        // Extraer datos de observaciones\n        if (observaciones && Array.isArray(observaciones) && observaciones.length > 0 && observaciones[0]) {\n            observacionesData = observaciones[0].ReturnValue;\n            observacionesTxtData = observaciones[0].DisplayValue;\n        }\n\n        // Validación de campos obligatorios básicos\n        if (!equipoData || !tipoData || !kilometrajeNum || !contadorFinNum || !observacionesData) {\n            let camposFaltantes = [];\n            if (!equipoData) camposFaltantes.push(\"Equipo\");\n            if (!tipoData) camposFaltantes.push(\"Tipo\");\n            if (!kilometrajeNum) camposFaltantes.push(\"Kilometraje\");\n            if (!contadorFinNum) camposFaltantes.push(\"Contador Final\");\n            if (!observacionesData) camposFaltantes.push(\"Observaciones\");\n\n            return context.executeAction({\n                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                Properties: {\n                    Title: \"Error de validación\",\n                    Message: `Faltan campos obligatorios: ${camposFaltantes.join(\", \")}`,\n                    CloseCaption: \"Cerrar\"\n                }\n            });\n        }\n\n        // Validación específica para tipo \"Cambio\"\n        if (tipoData === \"Cambio\") {\n            if (!orden || !Array.isArray(orden) || orden.length === 0 || !orden[0] || !orden[0].BindingObject) {\n                return context.executeAction({\n                    Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    Properties: {\n                        Title: \"Error de validación\",\n                        Message: \"Para tipo 'Cambio' es obligatorio seleccionar una Orden\",\n                        CloseCaption: \"Cerrar\"\n                    }\n                });\n            }\n\n            // Extraer datos de orden y reserva solo si el tipo es \"Cambio\"\n            ordenData = orden[0].BindingObject.orden;\n            reservaData = orden[0].BindingObject.reserva;\n        }\n\n        // Validación de números negativos\n        if (kilometrajeNum < 0 || contadorFinNum < 0) {\n            return context.executeAction({\n                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                Properties: {\n                    Title: \"Valor Incorrecto\",\n                    Message: \"No se permiten números negativos en los campos de kilometraje ni contadores.\",\n                    CloseCaption: \"Cerrar\"\n                }\n            });\n        }\n\n        // Validar contador inicial\n        if (contadorIniNum <= 0) {\n            return context.executeAction({\n                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                Properties: {\n                    Title: \"Aceite No disponible\",\n                    Message: \"El contador inicial es cero. No es posible registrar más consumos de aceite.\",\n                    CloseCaption: \"Cerrar\"\n                }\n            });\n        }\n\n        // Validar contadores\n        if (contadorFinNum >= contadorIniNum) {\n            return context.executeAction({\n                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                Properties: {\n                    Title: \"Error de validación\",\n                    Message: \"El contador inicial debe ser mayor que el contador final\",\n                    CloseCaption: \"Cerrar\"\n                }\n            });\n        }\n\n        // Calcular consumo\n        let consumo = parseFloat(((contadorIniNum - contadorFinNum) / 4).toFixed(2));\n        kilometrajeNum = parseFloat(kilometrajeNum.toFixed(2));\n        const filtro = `$filter=planilla_id eq ${id_planilla}`;\n\n        // Validar operario\n        return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'Empleados', [], `$filter=ficha eq '${operario_diferencial}'`)\n            .then((results) => {\n                if (!results || results.length === 0) {\n                    return context.executeAction({\n                        Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                        Properties: {\n                            Title: \"Ficha no Encontrada\",\n                            Message: \"Número de ficha no encontrada. Debes ingresar un número de ficha válido para continuar\",\n                            CloseCaption: \"Cerrar\"\n                        }\n                    });\n                }\n\n                const nombre_op = results.getItem(0).nombre;\n\n                // Buscar posición\n                return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ItemPlanillasAceites', [], filtro)\n                    .then((items) => {\n                        let nueva_pos = 1;\n                        if (items && items.length > 0) {\n                            const posiciones = items.map(item => parseInt(item.pos)).filter(p => !isNaN(p));\n                            nueva_pos = Math.max(...posiciones) + 1;\n                        }\n\n                        const nuevoItem = {\n                            id: guid(context),\n                            pos: nueva_pos,\n                            planilla_id: id_planilla,\n                            equipo_equipo: equipoData,\n                            tipo: tipoData,\n                            orden_orden: ordenData, // null si no es tipo \"Cambio\"\n                            reserva: reservaData, // null si no es tipo \"Cambio\"\n                            kilometraje: kilometrajeNum,\n                            consumo: consumo,\n                            op_ficha: operario_diferencialString,\n                            op_nombre: nombre_op,\n                            contador_ini: contadorIniNum,\n                            contador_fin: contadorFinNum,\n                            observacion: observacionesData,\n                            obs_text: observacionesTxtData\n                        };\n\n                        // Crear item\n                        return context.executeAction({\n                            Name: \"/appconsumos_qa_mb/Actions/oData/Create_Items_Planillas_Aceites.action\",\n                            Properties: {\n                                Properties: nuevoItem\n                            }\n                        }).then(() => {\n                            // Construir mensaje de éxito dinámico\n                            let mensajeExito = `Item creado exitosamente:\\n` +\n                                `Equipo: ${equipoData}\\n` +\n                                `Tipo: ${tipoData}\\n`;\n                            \n                            if (tipoData === \"Cambio\") {\n                                mensajeExito += `Orden: ${ordenData}\\n` +\n                                               `Reserva: ${reservaData}\\n`;\n                            }\n                            \n                            mensajeExito += `Kilometraje: ${kilometrajeNum}\\n` +\n                                           `Consumo: ${consumo}\\n` +\n                                           `Contador inicial: ${contadorIniNum}\\n` +\n                                           `Contador final: ${contadorFinNum}\\n` +\n                                           `Observación: ${observacionesData}`;\n\n                            // Mostrar mensaje de éxito\n                            return context.executeAction({\n                                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                                Properties: {\n                                    Title: \"Éxito\",\n                                    Message: mensajeExito,\n                                    CloseCaption: \"Cerrar\"\n                                }\n                            }).then(() => {\n                                // Ocultar formulario y mostrar botón de agregar\n                                form_add.setVisible(false);\n                                btn_agregar.setVisible(true);\n                            });\n                        });\n                    });\n            })\n            .catch((error) => {\n                return context.executeAction({\n                    Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    Properties: {\n                        Title: \"Error\",\n                        Message: `Error al crear el item: ${error.message || 'Error desconocido'}`,\n                        CloseCaption: \"Cerrar\"\n                    }\n                });\n            });\n\n    } catch (error) {\n        return context.executeAction({\n            Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            Properties: {\n                Title: \"Error\",\n                Message: `Error inesperado: ${error.message || 'Error desconocido'}`,\n                CloseCaption: \"Cerrar\"\n            }\n        });\n    }\n}","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\n\nimport guid from '../guid'\nexport default function Registrar_Items_Aceite_Hidraulico(context) {\n    try {\n        // Obtener valores de los controles\n        let equipo = context.evaluateTargetPath('#Page:Registrar_Aceite_Hidraulico/#Control:equipo_hidraulico/#Value');\n        let tipo = context.evaluateTargetPath('#Page:Registrar_Aceite_Hidraulico/#Control:tipo_hidraulico/#Value');\n        let kmh = context.evaluateTargetPath('#Page:Registrar_Aceite_Hidraulico/#Control:kmh_hidraulico/#Value');\n        let operario_hidraulico = context.evaluateTargetPath('#Page:Registrar_Aceite_Hidraulico/#Control:operario_hidraulico/#Value');\n        let cont_inicial = context.evaluateTargetPath('#Page:Registrar_Aceite_Hidraulico/#Control:cont_inicial_hidraulico/#Value');\n        let cont_final = context.evaluateTargetPath('#Page:Registrar_Aceite_Hidraulico/#Control:con_final_hidraulico/#Value');\n        let observaciones = context.evaluateTargetPath('#Page:Registrar_Aceite_Hidraulico/#Control:observaciones_hidraulico/#Value');\n        let orden = context.evaluateTargetPath('#Page:Registrar_Aceite_Hidraulico/#Control:orden_hidraulico/#Value');\n\n        let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n        let id_planilla = clientData.data_planilla_hidraulico.id;\n\n        // Obtener controles del formulario\n        const pageProxy = context.getPageProxy();\n        const form_add = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\");\n        const btn_agregar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\");\n\n        // Conversión de datos\n        let contadorIniNum = parseFloat(cont_inicial) || 0;\n        let contadorFinNum = parseFloat(cont_final) || 0;\n        let kilometrajeNum = parseFloat(kmh) || 0;\n        let operario_hidraulicoString = String(operario_hidraulico) || \"\";\n        let equipoData = null;\n        let tipoData = null;\n        let observacionesData = null;\n        let observacionesTxtData = null;\n        let ordenData = null;\n        let reservaData = null;\n\n        // Extraer datos de equipo\n        if (equipo && Array.isArray(equipo) && equipo.length > 0 && equipo[0] && equipo[0].BindingObject) {\n            equipoData = equipo[0].BindingObject.equipo;\n        }\n\n        // Extraer datos de tipo\n        if (tipo && Array.isArray(tipo) && tipo.length > 0 && tipo[0]) {\n            tipoData = tipo[0].DisplayValue;\n        }\n\n        // Extraer datos de observaciones\n        if (observaciones && Array.isArray(observaciones) && observaciones.length > 0 && observaciones[0]) {\n            observacionesData = observaciones[0].ReturnValue;\n            observacionesTxtData = observaciones[0].DisplayValue;\n        }\n\n        // Validación de campos obligatorios básicos\n        if (!equipoData || !tipoData || !kilometrajeNum || !contadorFinNum || !observacionesData) {\n            let camposFaltantes = [];\n            if (!equipoData) camposFaltantes.push(\"Equipo\");\n            if (!tipoData) camposFaltantes.push(\"Tipo\");\n            if (!kilometrajeNum) camposFaltantes.push(\"Kilometraje\");\n            if (!contadorFinNum) camposFaltantes.push(\"Contador Final\");\n            if (!observacionesData) camposFaltantes.push(\"Observaciones\");\n\n            return context.executeAction({\n                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                Properties: {\n                    Title: \"Error de validación\",\n                    Message: `Faltan campos obligatorios: ${camposFaltantes.join(\", \")}`,\n                    CloseCaption: \"Cerrar\"\n                }\n            });\n        }\n\n        // Validación específica para tipo \"Cambio\"\n        if (tipoData === \"Cambio\") {\n            if (!orden || !Array.isArray(orden) || orden.length === 0 || !orden[0] || !orden[0].BindingObject) {\n                return context.executeAction({\n                    Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    Properties: {\n                        Title: \"Error de validación\",\n                        Message: \"Para tipo 'Cambio' es obligatorio seleccionar una Orden\",\n                        CloseCaption: \"Cerrar\"\n                    }\n                });\n            }\n\n            // Extraer datos de orden y reserva solo si el tipo es \"Cambio\"\n            ordenData = orden[0].BindingObject.orden;\n            reservaData = orden[0].BindingObject.reserva;\n        }\n\n        // Validación de números negativos\n        if (kilometrajeNum < 0 || contadorFinNum < 0) {\n            return context.executeAction({\n                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                Properties: {\n                    Title: \"Valor Incorrecto\",\n                    Message: \"No se permiten números negativos en los campos de kilometraje ni contadores.\",\n                    CloseCaption: \"Cerrar\"\n                }\n            });\n        }\n\n        // Validar contador inicial\n        if (contadorIniNum <= 0) {\n            return context.executeAction({\n                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                Properties: {\n                    Title: \"Aceite No disponible\",\n                    Message: \"El contador inicial es cero. No es posible registrar más consumos de aceite.\",\n                    CloseCaption: \"Cerrar\"\n                }\n            });\n        }\n\n        // Validar contadores\n        if (contadorFinNum >= contadorIniNum) {\n            return context.executeAction({\n                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                Properties: {\n                    Title: \"Error de validación\",\n                    Message: \"El contador inicial debe ser mayor que el contador final\",\n                    CloseCaption: \"Cerrar\"\n                }\n            });\n        }\n\n        // Calcular consumo\n        let consumo = parseFloat(((contadorIniNum - contadorFinNum) / 4).toFixed(2));\n        kilometrajeNum = parseFloat(kilometrajeNum.toFixed(2));\n        const filtro = `$filter=planilla_id eq ${id_planilla}`;\n\n        // Validar operario\n        return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'Empleados', [], `$filter=ficha eq '${operario_hidraulico}'`)\n            .then((results) => {\n                if (!results || results.length === 0) {\n                    return context.executeAction({\n                        Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                        Properties: {\n                            Title: \"Ficha no Encontrada\",\n                            Message: \"Número de ficha no encontrada. Debes ingresar un número de ficha válido para continuar\",\n                            CloseCaption: \"Cerrar\"\n                        }\n                    });\n                }\n\n                const nombre_op = results.getItem(0).nombre;\n\n                // Buscar posición\n                return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ItemPlanillasAceites', [], filtro)\n                    .then((items) => {\n                        let nueva_pos = 1;\n                        if (items && items.length > 0) {\n                            const posiciones = items.map(item => parseInt(item.pos)).filter(p => !isNaN(p));\n                            nueva_pos = Math.max(...posiciones) + 1;\n                        }\n\n                        const nuevoItem = {\n                            id: guid(context),\n                            pos: nueva_pos,\n                            planilla_id: id_planilla,\n                            equipo_equipo: equipoData,\n                            tipo: tipoData,\n                            orden_orden: ordenData, // null si no es tipo \"Cambio\"\n                            reserva: reservaData, // null si no es tipo \"Cambio\"\n                            kilometraje: kilometrajeNum,\n                            consumo: consumo,\n                            op_ficha: operario_hidraulicoString,\n                            op_nombre: nombre_op,\n                            contador_ini: contadorIniNum,\n                            contador_fin: contadorFinNum,\n                            observacion: observacionesData,\n                            obs_text: observacionesTxtData\n                        };\n\n                        // Crear item\n                        return context.executeAction({\n                            Name: \"/appconsumos_qa_mb/Actions/oData/Create_Items_Planillas_Aceites.action\",\n                            Properties: {\n                                Properties: nuevoItem\n                            }\n                        }).then(() => {\n                            // Construir mensaje de éxito dinámico\n                            let mensajeExito = `Item creado exitosamente:\\n` +\n                                `Equipo: ${equipoData}\\n` +\n                                `Tipo: ${tipoData}\\n`;\n\n                            if (tipoData === \"Cambio\") {\n                                mensajeExito += `Orden: ${ordenData}\\n` +\n                                    `Reserva: ${reservaData}\\n`;\n                            }\n\n                            mensajeExito += `Kilometraje: ${kilometrajeNum}\\n` +\n                                `Consumo: ${consumo}\\n` +\n                                `Contador inicial: ${contadorIniNum}\\n` +\n                                `Contador final: ${contadorFinNum}\\n` +\n                                `Observación: ${observacionesData}`;\n\n                            // Mostrar mensaje de éxito\n                            return context.executeAction({\n                                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                                Properties: {\n                                    Title: \"Éxito\",\n                                    Message: mensajeExito,\n                                    CloseCaption: \"Cerrar\"\n                                }\n                            }).then(() => {\n                                // Ocultar formulario y mostrar botón de agregar\n                                form_add.setVisible(false);\n                                btn_agregar.setVisible(true);\n                            });\n                        });\n                    });\n            })\n            .catch((error) => {\n                return context.executeAction({\n                    Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    Properties: {\n                        Title: \"Error\",\n                        Message: `Error al crear el item: ${error.message || 'Error desconocido'}`,\n                        CloseCaption: \"Cerrar\"\n                    }\n                });\n            });\n\n    } catch (error) {\n        return context.executeAction({\n            Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            Properties: {\n                Title: \"Error\",\n                Message: `Error inesperado: ${error.message || 'Error desconocido'}`,\n                CloseCaption: \"Cerrar\"\n            }\n        });\n    }\n}\n","/**\n * Función para registrar items de aceite de motor en la planilla\n * @param {IClientAPI} context - Contexto de la aplicación MDK\n */\nimport guid from '../guid'\n\nexport default function Registrar_Items_Aceite_Motor(context) {\n    try {\n        // Obtener valores de los controles\n        let equipo = context.evaluateTargetPath('#Page:Registrar_Aceite_Motor/#Control:equipo_motor/#Value');\n        let tipo = context.evaluateTargetPath('#Page:Registrar_Aceite_Motor/#Control:tipo_motor/#Value');\n        let kmh = context.evaluateTargetPath('#Page:Registrar_Aceite_Motor/#Control:kmh_motor/#Value');\n        let operario_motor = context.evaluateTargetPath('#Page:Registrar_Aceite_Motor/#Control:operario_motor/#Value');\n        let cont_inicial = context.evaluateTargetPath('#Page:Registrar_Aceite_Motor/#Control:cont_inicial_motor/#Value');\n        let cont_final = context.evaluateTargetPath('#Page:Registrar_Aceite_Motor/#Control:con_final_motor/#Value');\n        let observaciones = context.evaluateTargetPath('#Page:Registrar_Aceite_Motor/#Control:observaciones_motor/#Value');\n        let orden = context.evaluateTargetPath('#Page:Registrar_Aceite_Motor/#Control:orden_motor/#Value');\n\n        let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n        let id_planilla = clientData.data_planilla_motor.id;\n\n        // Obtener controles del formulario\n        const pageProxy = context.getPageProxy();\n        const form_add = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\");\n        const btn_agregar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\");\n\n        // Conversión de datos\n        let contadorIniNum = parseFloat(cont_inicial) || 0;\n        let contadorFinNum = parseFloat(cont_final) || 0;\n        let kilometrajeNum = parseFloat(kmh) || 0;\n        let operario_motorString = String(operario_motor) || \"\";\n        let equipoData = null;\n        let tipoData = null;\n        let observacionesData = null;\n        let observacionesTxtData = null;\n        let ordenData = null;\n        let reservaData = null;\n\n        // Extraer datos de equipo\n        if (equipo && Array.isArray(equipo) && equipo.length > 0 && equipo[0] && equipo[0].BindingObject) {\n            equipoData = equipo[0].BindingObject.equipo;\n        }\n\n        // Extraer datos de tipo\n        if (tipo && Array.isArray(tipo) && tipo.length > 0 && tipo[0]) {\n            tipoData = tipo[0].DisplayValue;\n        }\n\n        // Extraer datos de observaciones\n        if (observaciones && Array.isArray(observaciones) && observaciones.length > 0 && observaciones[0]) {\n            observacionesData = observaciones[0].ReturnValue;\n            observacionesTxtData = observaciones[0].DisplayValue;\n        }\n\n        // Validación de campos obligatorios básicos\n        if (!equipoData || !tipoData || !kilometrajeNum || !contadorFinNum || !observacionesData) {\n            let camposFaltantes = [];\n            if (!equipoData) camposFaltantes.push(\"Equipo\");\n            if (!tipoData) camposFaltantes.push(\"Tipo\");\n            if (!kilometrajeNum) camposFaltantes.push(\"Kilometraje\");\n            if (!contadorFinNum) camposFaltantes.push(\"Contador Final\");\n            if (!observacionesData) camposFaltantes.push(\"Observaciones\");\n\n            return context.executeAction({\n                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                Properties: {\n                    Title: \"Error de validación\",\n                    Message: `Faltan campos obligatorios: ${camposFaltantes.join(\", \")}`,\n                    CloseCaption: \"Cerrar\"\n                }\n            });\n        }\n\n        // Validación específica para tipo \"Cambio\"\n        if (tipoData === \"Cambio\") {\n            if (!orden || !Array.isArray(orden) || orden.length === 0 || !orden[0] || !orden[0].BindingObject) {\n                return context.executeAction({\n                    Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    Properties: {\n                        Title: \"Error de validación\",\n                        Message: \"Para tipo 'Cambio' es obligatorio seleccionar una Orden\",\n                        CloseCaption: \"Cerrar\"\n                    }\n                });\n            }\n\n            // Extraer datos de orden y reserva solo si el tipo es \"Cambio\"\n            ordenData = orden[0].BindingObject.orden;\n            reservaData = orden[0].BindingObject.reserva;\n        }\n\n        // Validación de números negativos\n        if (kilometrajeNum < 0 || contadorFinNum < 0) {\n            return context.executeAction({\n                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                Properties: {\n                    Title: \"Valor Incorrecto\",\n                    Message: \"No se permiten números negativos en los campos de kilometraje ni contadores.\",\n                    CloseCaption: \"Cerrar\"\n                }\n            });\n        }\n\n        // Validar contador inicial\n        if (contadorIniNum <= 0) {\n            return context.executeAction({\n                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                Properties: {\n                    Title: \"Aceite No disponible\",\n                    Message: \"El contador inicial es cero. No es posible registrar más consumos de aceite.\",\n                    CloseCaption: \"Cerrar\"\n                }\n            });\n        }\n\n        // Validar contadores\n        if (contadorFinNum >= contadorIniNum) {\n            return context.executeAction({\n                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                Properties: {\n                    Title: \"Error de validación\",\n                    Message: \"El contador inicial debe ser mayor que el contador final\",\n                    CloseCaption: \"Cerrar\"\n                }\n            });\n        }\n\n        // Calcular consumo\n        let consumo = parseFloat(((contadorIniNum - contadorFinNum) / 4).toFixed(2));\n        kilometrajeNum = parseFloat(kilometrajeNum.toFixed(2));\n        const filtro = `$filter=planilla_id eq ${id_planilla}`;\n\n        // Validar operario\n        return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'Empleados', [], `$filter=ficha eq '${operario_motor}'`)\n            .then((results) => {\n                if (!results || results.length === 0) {\n                    return context.executeAction({\n                        Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                        Properties: {\n                            Title: \"Ficha no Encontrada\",\n                            Message: \"Número de ficha no encontrada. Debes ingresar un número de ficha válido para continuar\",\n                            CloseCaption: \"Cerrar\"\n                        }\n                    });\n                }\n\n                const nombre_op = results.getItem(0).nombre;\n\n                // Buscar posición\n                return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ItemPlanillasAceites', [], filtro)\n                    .then((items) => {\n                        let nueva_pos = 1;\n                        if (items && items.length > 0) {\n                            const posiciones = items.map(item => parseInt(item.pos)).filter(p => !isNaN(p));\n                            nueva_pos = Math.max(...posiciones) + 1;\n                        }\n\n                        const nuevoItem = {\n                            id: guid(context),\n                            pos: nueva_pos,\n                            planilla_id: id_planilla,\n                            equipo_equipo: equipoData,\n                            tipo: tipoData,\n                            orden_orden: ordenData, // null si no es tipo \"Cambio\"\n                            reserva: reservaData, // null si no es tipo \"Cambio\"\n                            kilometraje: kilometrajeNum,\n                            consumo: consumo,\n                            op_ficha: operario_motorString,\n                            op_nombre: nombre_op,\n                            contador_ini: contadorIniNum,\n                            contador_fin: contadorFinNum,\n                            observacion: observacionesData,\n                            obs_text: observacionesTxtData\n                        };\n\n                        // Crear item\n                        return context.executeAction({\n                            Name: \"/appconsumos_qa_mb/Actions/oData/Create_Items_Planillas_Aceites.action\",\n                            Properties: {\n                                Properties: nuevoItem\n                            }\n                        }).then(() => {\n                            // Construir mensaje de éxito dinámico\n                            let mensajeExito = `Item creado exitosamente:\\n` +\n                                `Equipo: ${equipoData}\\n` +\n                                `Tipo: ${tipoData}\\n`;\n\n                            if (tipoData === \"Cambio\") {\n                                mensajeExito += `Orden: ${ordenData}\\n` +\n                                    