                CloseCaption: \"Cerrar\"\n            }\n        });\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nimport guid from '../guid'\nexport default function Registrar_Items_Aceite_Reductor(context) {\n    try {\n        // Obtener valores de los controles\n        let equipo = context.evaluateTargetPath('#Page:Registrar_Aceite_Reductores/#Control:equipo_reductor/#Value');\n        let tipo = context.evaluateTargetPath('#Page:Registrar_Aceite_Reductores/#Control:tipo_reductor/#Value');\n        let kmh = context.evaluateTargetPath('#Page:Registrar_Aceite_Reductores/#Control:kmh_reductor/#Value');\n        let operario_reductor = context.evaluateTargetPath('#Page:Registrar_Aceite_Reductores/#Control:operario_reductor/#Value');\n        let cont_inicial = context.evaluateTargetPath('#Page:Registrar_Aceite_Reductores/#Control:cont_inicial_reductor/#Value');\n        let cont_final = context.evaluateTargetPath('#Page:Registrar_Aceite_Reductores/#Control:con_final_reductor/#Value');\n        let observaciones = context.evaluateTargetPath('#Page:Registrar_Aceite_Reductores/#Control:observaciones_reductor/#Value');\n        let orden = context.evaluateTargetPath('#Page:Registrar_Aceite_Reductores/#Control:orden_reductor/#Value');\n\n        let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n        let id_planilla = clientData.data_planilla_reductor.id;\n\n        // Obtener controles del formulario\n        const pageProxy = context.getPageProxy();\n        const form_add = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\");\n        const btn_agregar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\");\n\n        // Conversión de datos\n        let contadorIniNum = parseFloat(cont_inicial) || 0;\n        let contadorFinNum = parseFloat(cont_final) || 0;\n        let kilometrajeNum = parseFloat(kmh) || 0;\n        let operario_red