))\n    //setTargetSpecifier(,true)\n    \n    orden_obj.setValue(\"\")\n    if(registro_consumo_value.length < 1){\n        orden_obj.setEditable(false)\n        \n        orden_obj.redraw()\n        return;\n    }else{\n        //let equipo = registro_consumo_value[0].BindingObject.equipo_equipo\n        //let target = orden_obj.getTargetSpecifier()\n        //let res = target.setQueryOptions(`$filter=equipo eq '${equipo}'`)\n    \n        //orden_obj.setTargetSpecifier(res,true)\n        orden_obj.setEditable(true)\n        orden_obj.redraw()\n        return;\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function onChange_RevisarPlanillaConsumo_Servotransmisor(context) {\n    const pageProxy = context.getPageProxy();\n    var form_cell = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\")\n    var registro_consumo = form_cell.getControl(\"registro_consumo\")\n    var orden_obj = form_cell.getControl(\"orden_obj\")\n    let registro_consumo_value = context.evaluateTargetPath('#Page:Revisar_Planilla_Aceite_Servotransmisor/#Control:registro_consumo/#Value');\n\n    //alert(JSON.stringify(orden_obj.getTargetSpecifier()))\n   \n    //alert(JSON.stringify(res))\n        //alert(JSON.stringify(orden_obj.getTargetSpecifier()))\n        \n    //alert(target.getType())\n    //setTargetSpecifier(,true)\n    \n    orden_obj.setValue(\"\")\n    if(registro_consumo_value.length < 1){\n        orden_obj.setEditable(false)\n        \n        orden_obj.redraw()\n        return;\n    }else{\n        //let equipo = registro_consumo_value[0].BindingObject.equipo_equipo\n        //let target = orden_obj.getTargetSpecifier()\n        //let res = target.setQueryOptions(`$filter=equipo eq '${equipo}'`)\n    \n        //orden_obj.setTargetSpecifier(res,true)\n        orden_obj.setEditable(true)\n        orden_obj.redraw()\n        return;\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function onChange_Tipo_Aceite_Diferencial(context) {\n    const pageProxy = context.getPageProxy();\n    var form_cell = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\")\n    var tipo_consumo = form_cell.getControl(\"tipo_diferencial\")\n    let orden_diferencial = form_cell.getControl(\"orden_diferencial\")\n    let tipo_consumo_value = context.evaluateTargetPath('#Page:Registrar_Aceite_Diferencial/#Control:tipo_diferencial/#Value');\n   \n\n    let equipo = context.evaluateTargetPath('#Page:Registrar_Aceite_Diferencial/#Control:equipo_diferencial/#Value');\n\n    \n    if (tipo_consumo_value.length > 0 && tipo_consumo_value[0]?.ReturnValue === \"Cambio\"){\n        //set visible al lp de la orden\n        orden_diferencial.setVisible(true);\n        //obtener el filtro para la orden\n        let equipo_id = equipo[0].BindingObject.equipo\n        let target = orden_diferencial.getTargetSpecifier()\n        let res = target.setQueryOptions(`$filter=equipo eq '${equipo_id}'`)\n    \n        orden_diferencial.setTargetSpecifier(res,true)\n        //orden_obj.setEditable(true)\n        orden_diferencial.redraw()\n        return;\n    }else{\n        orden_diferencial.setVisible(false);\n    }\n\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function onChange_Tipo_Aceite_Hidraulico(context) {\n    const pageProxy = context.getPageProxy();\n    var form_cell = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\")\n    //var tipo_consumo = form_cell.getControl(\"tipo_hidraulico\")\n    let orden_hidraulico = form_cell.getControl(\"orden_hidraulico\")\n    let tipo_consumo_value = context.evaluateTargetPath('#Page:Registrar_Aceite_Hidraulico/#Control:tipo_hidraulico/#Value');\n   \n    \n    let equipo = context.evaluateTargetPath('#Page:Registrar_Aceite_Hidraulico/#Control:equipo_hidraulico/#Value');\n   \n    if ( tipo_consumo_value.length > 0 && tipo_consumo_value[0]?.ReturnValue === \"Cambio\"){\n        //set visible al lp de la orden\n        //let tipo = tipo_consumo_value[0].ReturnValue\n        orden_hidraulico.setVisible(true);\n        //obtener el filtro para la orden\n        let equipo_id = equipo[0].BindingObject.equipo\n        let target = orden_hidraulico.getTargetSpecifier()\n        let res = target.setQueryOptions(`$filter=equipo eq '${equipo_id}'`)\n    \n        orden_hidraulico.setTargetSpecifier(res,true)\n        //orden_obj.setEditable(true)\n        orden_hidraulico.redraw()\n        return;\n    }else{\n        orden_hidraulico.setVisible(false);\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function onChange_Tipo_Aceite_Motor(context) {\n    const pageProxy = context.getPageProxy();\n    var form_cell = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\")\n    //var tipo_consumo = form_cell.getControl(\"tipo_motor\")\n    let orden_motor = form_cell.getControl(\"orden_motor\")\n    let tipo_consumo_value = context.evaluateTargetPath('#Page:Registrar_Aceite_Motor/#Control:tipo_motor/#Value');\n   \n    \n    let equipo = context.evaluateTargetPath('#Page:Registrar_Aceite_Motor/#Control:equipo_motor/#Value');\n   \n    if ( tipo_consumo_value.length > 0 && tipo_consumo_value[0]?.ReturnValue === \"Cambio\"){\n        //set visible al lp de la orden\n        //let tipo = tipo_consumo_value[0].ReturnValue\n        orden_motor.setVisible(true);\n        //obtener el filtro para la orden\n        let equipo_id = equipo[0].BindingObject.equipo\n        let target = orden_motor.getTargetSpecifier()\n        let res = target.setQueryOptions(`$filter=equipo eq '${equipo_id}'`)\n    \n        orden_motor.setTargetSpecifier(res,true)\n        //orden_obj.setEditable(true)\n        orden_motor.redraw()\n        return;\n    }else{\n        orden_motor.setVisible(false);\n    }\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function onChange_Tipo_Aceite_Reductor(context) {\n    const pageProxy = context.getPageProxy();\n    var form_cell = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\")\n    var tipo_consumo = form_cell.getControl(\"tipo_reductor\")\n    let orden_reductor = form_cell.getControl(\"orden_reductor\")\n    let tipo_consumo_value = context.evaluateTargetPath('#Page:Registrar_Aceite_Reductores/#Control:tipo_reductor/#Value');\n   \n\n    let equipo = context.evaluateTargetPath('#Page:Registrar_Aceite_Reductores/#Control:equipo_reductor/#Value');\n\n\n    if (tipo_consumo_value.length > 0 && tipo_consumo_value[0]?.ReturnValue === \"Cambio\"){\n        //set visible al lp de la orden\n        orden_reductor.setVisible(true);\n        //obtener el filtro para la orden\n        let equipo_id = equipo[0].BindingObject.equipo\n        let target = orden_reductor.getTargetSpecifier()\n        let res = target.setQueryOptions(`$filter=equipo eq '${equipo_id}'`)\n    \n        orden_reductor.setTargetSpecifier(res,true)\n        //orden_obj.setEditable(true)\n        orden_reductor.redraw()\n        return;\n    }else{\n        orden_reductor.setVisible(false);\n    }\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function onChange_Tipo_Aceite_Servotransmisor(context) {\n    const pageProxy = context.getPageProxy();\n    var form_cell = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\")\n    var tipo_consumo = form_cell.getControl(\"tipo_servotrans\")\n    let orden_servotrans = form_cell.getControl(\"orden_servotrans\")\n    let tipo_consumo_value = context.evaluateTargetPath('#Page:Registrar_Aceite_Servotransmisor/#Control:tipo_servotrans/#Value');\n   \n\n    let equipo = context.evaluateTargetPath('#Page:Registrar_Aceite_Servotransmisor/#Control:equipo_servotrans/#Value');\n\n    \n    if (tipo_consumo_value.length > 0 && tipo_consumo_value[0]?.ReturnValue === \"Cambio\"){\n        //set visible al lp de la orden\n        orden_servotrans.setVisible(true);\n        //obtener el filtro para la orden\n        let equipo_id = equipo[0].BindingObject.equipo\n        let target = orden_servotrans.getTargetSpecifier()\n        let res = target.setQueryOptions(`$filter=equipo eq '${equipo_id}'`)\n    \n        orden_servotrans.setTargetSpecifier(res,true)\n        //orden_obj.setEditable(true)\n        orden_servotrans.redraw()\n        return;\n    }else{\n        orden_servotrans.setVisible(false);\n    }\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function setEnabled_Tipo_Aceite(context) {\n    let equipo = context.evaluateTargetPath('#Page:Registrar_Aceite_Diferencial/#Control:equipo_diferencial/#Value');\n    const pageProxy = context.getPageProxy();\n    var lp_tipo = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\").getControl(\"tipo_diferencial\")\n    //IsEditable\n\n    if (equipo.length > 0) {\n        lp_tipo.setEditable(true)\n        \n    }else{\n        lp_tipo.setEditable(false)\n    }\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function setEnabled_Tipo_Aceite_Hidraulico(context) {\n    let equipo = context.evaluateTargetPath('#Page:Registrar_Aceite_Hidraulico/#Control:equipo_hidraulico/#Value');\n    const pageProxy = context.getPageProxy();\n    var lp_tipo = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\").getControl(\"tipo_hidraulico\")\n    //IsEditable\n\n    if (equipo.length > 0) {\n        lp_tipo.setEditable(true)\n        \n    }else{\n        lp_tipo.setEditable(false)\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function setEnabled_Tipo_Aceite_Motor(context) {\n    let equipo = context.evaluateTargetPath('#Page:Registrar_Aceite_Motor/#Control:equipo_motor/#Value');\n    const pageProxy = context.getPageProxy();\n    var lp_tipo = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\").getControl(\"tipo_motor\")\n    //IsEditable\n\n    if (equipo.length > 0) {\n        lp_tipo.setEditable(true)\n        \n    }else{\n        lp_tipo.setEditable(false)\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function setEnabled_Tipo_Aceite_Reductor(context) {\n    let equipo = context.evaluateTargetPath('#Page:Registrar_Aceite_Reductores/#Control:equipo_reductor/#Value');\n    const pageProxy = context.getPageProxy();\n    var lp_tipo = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\").getControl(\"tipo_reductor\")\n    //IsEditable\n\n    if (equipo.length > 0) {\n        lp_tipo.setEditable(true)\n        \n    }else{\n        lp_tipo.setEditable(false)\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function setEnabled_Tipo_Aceite_Servotransmisor(context) {\n    let equipo = context.evaluateTargetPath('#Page:Registrar_Aceite_Servotransmisor/#Control:equipo_servotrans/#Value');\n    const pageProxy = context.getPageProxy();\n    var lp_tipo = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\").getControl(\"tipo_servotrans\")\n    //IsEditable\n\n    if (equipo.length > 0) {\n        lp_tipo.setEditable(true)\n        \n    }else{\n        lp_tipo.setEditable(false)\n    }\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function setVisible_Aceite_IC(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData.info_user;\n\n    if (info.sociedad ==='AI01'){\n        return true;\n\n    }else if(info.sociedad ==='AI08'){\n        return false;\n    }else{\n        alert(\"no hay sociedad\")\n    }\n\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function setVisible_Botones_Planillas(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let estado = clientData.data_planilla_motor.estado\n\n    return estado === 'Pendiente'\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function setVisible_Botones_Planillas_Diferencial(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let estado = clientData.data_planilla_diferencial.estado\n\n    return estado === 'Pendiente'\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function setVisible_Botones_Planillas_Hidraulico(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let estado = clientData.data_planilla_hidraulico.estado\n\n    return estado === 'Pendiente'\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function setVisible_Botones_Planillas_Servotransmisor(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let estado = clientData.data_planilla_servotrans.estado\n\n    return estado === 'Pendiente'\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function setVisible_RevisarAceiteDiferencial(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let clientDataFiltro = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    //clientDataFiltro.data_planilla_diferencial.estado\n    let info = clientData.info_user;\n\n    return clientDataFiltro.data_planilla_diferencial.estado === 'Enviado' && info.rol === 'Auxiliar' &&  clientDataFiltro.data_planilla_diferencial.total > 0;\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function setVisible_RevisarAceiteHidraulico(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let clientDataFiltro = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    //clientDataFiltro.data_planilla_hidraulico.estado\n    let info = clientData.info_user;\n\n    return clientDataFiltro.data_planilla_hidraulico.estado === 'Enviado' && info.rol === 'Auxiliar' &&  clientDataFiltro.data_planilla_hidraulico.total > 0;\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function setVisible_RevisarAceiteMotor(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let clientDataFiltro = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    //clientDataFiltro.data_planilla_motor.estado\n    let info = clientData.info_user;\n\n    return clientDataFiltro.data_planilla_motor.estado === 'Enviado' && info.rol === 'Auxiliar' &&  clientDataFiltro.data_planilla_motor.total > 0;\n    /*let binding = context.binding\n\n    alert(clientDataFiltro.data_planilla_motor.estado)\n    return true*/\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function setVisible_RevisarAceiteReductor(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let clientDataFiltro = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    //clientDataFiltro.data_planilla_reductor.estado\n    let info = clientData.info_user;\n\n    return clientDataFiltro.data_planilla_reductor.estado === 'Enviado' && info.rol === 'Auxiliar' &&  clientDataFiltro.data_planilla_reductor.total > 0;\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function setVisible_RevisarAceiteServotransmisor(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let clientDataFiltro = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    //clientDataFiltro.data_planilla_servotrans.estado\n    let info = clientData.info_user;\n\n    return clientDataFiltro.data_planilla_servotrans.estado === 'Enviado' && info.rol === 'Auxiliar' &&  clientDataFiltro.data_planilla_servotrans.total > 0;\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function setVisible_formConsumosCambio(context) {\n    \n    let cant = context.evaluateTargetPath(\"#Page:Detalle_Aceite_Motor/#ClientData/#Property:cantCambio\");\n    //let cant = context.evaluateTargetPath(\"#Page:Registrar_Aceite_Motor/#ClientData/#Property:cantCambio\");\n    if(cant > 0){\n        return true\n    }\n\n    return false\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function setVisible_formConsumosCambio_Diferencial(context) {\n    let cant = context.evaluateTargetPath(\"#Page:Detalle_Aceite_Diferencial/#ClientData/#Property:cantCambio\");\n    if(cant > 0){\n        return true\n    }\n\n    return false\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function setVisible_formConsumosCambio_Hidraulico(context) {\n    let cant = context.evaluateTargetPath(\"#Page:Detalle_Aceite_Hidraulico/#ClientData/#Property:cantCambio\");\n    if(cant > 0){\n        return true\n    }\n\n    return false\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function setVisible_formConsumosCambio_Reductor(context) {\n    let cant = context.evaluateTargetPath(\"#Page:Detalle_Aceite_Reductor/#ClientData/#Property:cantCambio\");\n    if(cant > 0){\n        return true\n    }\n\n    return false\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function setVisible_formConsumosCambio_Servotransmisor(context) {\n    let cant = context.evaluateTargetPath(\"#Page:Detalle_Aceite_Servotransmisor/#ClientData/#Property:cantCambio\");\n    if(cant > 0){\n        return true\n    }\n\n    return false\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function set_Contador_Inicial_Diferencial(context) {\n    const pageProxy = context.getPageProxy();\n    var form_add = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\")\n    var cont_inicial_diferencial = form_add.getControl(\"cont_inicial_diferencial\")\n    var btn_agregar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\")\n    //obtener los controlasdores del formulario\n    let equipo = form_add.getControl(\"equipo_diferencial\")\n    let tipo = form_add.getControl(\"tipo_diferencial\")\n    let kmh = form_add.getControl(\"kmh_diferencial\")\n    let operario_diferencial = form_add.getControl(\"operario_diferencial\")\n    let cont_final = form_add.getControl(\"con_final_diferencial\")\n    let observaciones = form_add.getControl(\"observaciones_diferencial\")\n    let orden_dif = form_add.getControl(\"orden_diferencial\")\n\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let id_planilla = clientData.data_planilla_diferencial.id;\n    let cantidad_ini;\n\n    const filtro = `$filter=planilla_id eq ${id_planilla}`;\n\n    //Leer los datos de items planilla\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ItemPlanillasAceites', [], filtro).then(async (results) => {\n        //si hay items en la planilla\n        if (results && results.length > 0) {\n            //alert(\"ya hay items en la planilla\");\n\n            // Trabajar directamente con el array results\n            // Encontrar el item con la posición más alta\n            let ultimoItem = null;\n            let maxPos = -1;\n\n            results.forEach(item => {\n                const pos = parseInt(item.pos);\n                if (!isNaN(pos) && pos > maxPos) {\n                    maxPos = pos;\n                    ultimoItem = item;\n                }\n            });\n\n            // Validar que tenga el campo 'contador_fin'\n            if (ultimoItem && ultimoItem.contador_fin !== undefined && ultimoItem.contador_fin !== null) {\n                cantidad_ini = ultimoItem.contador_fin;\n            } else {\n                cantidad_ini = clientData.data_planilla_diferencial.contador_ini;\n            }\n\n        } else {\n\n            //alert(id_planilla);\n            cantidad_ini = clientData.data_planilla_diferencial.contador_ini;\n        }\n\n        form_add.setVisible(true);\n\n        var cant_inicial_planilla = cantidad_ini;\n        //alert(cant_inicial_planilla)\n        cont_inicial_diferencial.setValue(cant_inicial_planilla);\n        //----\n        equipo.setValue(\"\");\n        tipo.setValue(\"\");\n        observaciones.setValue(\"\");\n        kmh.setValue(\"\");\n        operario_diferencial.setValue(\"\");\n        cont_final.setValue(\"\");\n        orden_dif.setValue(\"\");\n        //----\n        orden_dif.setVisible(false);\n        btn_agregar.setVisible(false)\n        \n\n    })\n        .catch((error) => {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Error\",\n                    \"Message\": `Error al consultar datos: ${error.message}`,\n                    \"OKCaption\": \"Cerrar\"\n                }\n            });\n        });\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function set_Contador_Inicial_Hidraulico(context) {\n    const pageProxy = context.getPageProxy();\n    var form_add = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\")\n    var cont_inicial_hidraulico = form_add.getControl(\"cont_inicial_hidraulico\")\n    var btn_agregar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\")\n    //obtener los controlasdores del formulario\n    let equipo = form_add.getControl(\"equipo_hidraulico\")\n    let tipo = form_add.getControl(\"tipo_hidraulico\")\n    let kmh = form_add.getControl(\"kmh_hidraulico\")\n    let operario_hidraulico = form_add.getControl(\"operario_hidraulico\")\n    let cont_final = form_add.getControl(\"con_final_hidraulico\")\n    let observaciones = form_add.getControl(\"observaciones_hidraulico\")\n    let orden_hid = form_add.getControl(\"orden_hidraulico\")\n\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let id_planilla = clientData.data_planilla_hidraulico.id;\n    let cantidad_ini;\n\n    const filtro = `$filter=planilla_id eq ${id_planilla}`;\n\n    //Leer los datos de items planilla\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ItemPlanillasAceites', [], filtro).then(async (results) => {\n        //si hay items en la planilla\n        if (results && results.length > 0) {\n            //alert(\"ya hay items en la planilla\");\n\n            // Trabajar directamente con el array results\n            // Encontrar el item con la posición más alta\n            let ultimoItem = null;\n            let maxPos = -1;\n\n            results.forEach(item => {\n                const pos = parseInt(item.pos);\n                if (!isNaN(pos) && pos > maxPos) {\n                    maxPos = pos;\n                    ultimoItem = item;\n                }\n            });\n\n            // Validar que tenga el campo 'contador_fin'\n            if (ultimoItem && ultimoItem.contador_fin !== undefined && ultimoItem.contador_fin !== null) {\n                cantidad_ini = ultimoItem.contador_fin;\n            } else {\n                cantidad_ini = clientData.data_planilla_hidraulico.contador_ini;\n            }\n\n        } else {\n\n            //alert(id_planilla);\n            cantidad_ini = clientData.data_planilla_hidraulico.contador_ini;\n        }\n\n        form_add.setVisible(true);\n\n        var cant_inicial_planilla = cantidad_ini;\n        //alert(cant_inicial_planilla)\n        cont_inicial_hidraulico.setValue(cant_inicial_planilla);\n        //----\n        equipo.setValue(\"\");\n        tipo.setValue(\"\");\n        observaciones.setValue(\"\");\n        kmh.setValue(\"\");\n        operario_hidraulico.setValue(\"\");\n        cont_final.setValue(\"\");\n        orden_hid.setValue(\"\");\n        //----\n        orden_hid.setVisible(false)\n\n        btn_agregar.setVisible(false)\n        \n\n    })\n        .catch((error) => {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Error\",\n                    \"Message\": `Error al consultar datos: ${error.message}`,\n                    \"OKCaption\": \"Cerrar\"\n                }\n            });\n        });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function set_Contador_Inicial_Motor(context) {\n    const pageProxy = context.getPageProxy();\n    var form_add = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\")\n    var cont_inicial_motor = form_add.getControl(\"cont_inicial_motor\")\n    var btn_agregar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\")\n    //obtener los controlasdores del formulario\n    let equipo = form_add.getControl(\"equipo_motor\")\n    let tipo = form_add.getControl(\"tipo_motor\")\n    let kmh = form_add.getControl(\"kmh_motor\")\n    let operario_motor = form_add.getControl(\"operario_motor\")\n    let cont_final = form_add.getControl(\"con_final_motor\")\n    let observaciones = form_add.getControl(\"observaciones_motor\")\n    let orden_motor = form_add.getControl(\"orden_motor\")\n\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let id_planilla = clientData.data_planilla_motor.id;\n    let cantidad_ini;\n\n    const filtro = `$filter=planilla_id eq ${id_planilla}`;\n\n    //Leer los datos de items planilla\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ItemPlanillasAceites', [], filtro).then(async (results) => {\n        //si hay items en la planilla\n        if (results && results.length > 0) {\n            //alert(\"ya hay items en la planilla\");\n\n            // Trabajar directamente con el array results\n            // Encontrar el item con la posición más alta\n            let ultimoItem = null;\n            let maxPos = -1;\n\n            results.forEach(item => {\n                const pos = parseInt(item.pos);\n                if (!isNaN(pos) && pos > maxPos) {\n                    maxPos = pos;\n                    ultimoItem = item;\n                }\n            });\n\n            // Validar que tenga el campo 'contador_fin'\n            if (ultimoItem && ultimoItem.contador_fin !== undefined && ultimoItem.contador_fin !== null) {\n                cantidad_ini = ultimoItem.contador_fin;\n            } else {\n                cantidad_ini = clientData.data_planilla_motor.contador_ini;\n            }\n\n        } else {\n\n            //alert(id_planilla);\n            cantidad_ini = clientData.data_planilla_motor.contador_ini;\n        }\n\n        form_add.setVisible(true);\n\n        var cant_inicial_planilla = cantidad_ini;\n        //alert(cant_inicial_planilla)\n        cont_inicial_motor.setValue(cant_inicial_planilla);\n        //----\n        equipo.setValue(\"\");\n        tipo.setValue(\"\");\n        observaciones.setValue(\"\");\n        kmh.setValue(\"\");\n        operario_motor.setValue(\"\");\n        cont_final.setValue(\"\");\n        //----\n        orden_motor.setValue(\"\");\n        orden_motor.setVisible(false)\n\n        btn_agregar.setVisible(false)\n    \n    })\n        .catch((error) => {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Error\",\n                    \"Message\": `Error al consultar datos: ${error.message}`,\n                    \"OKCaption\": \"Cerrar\"\n                }\n            });\n        });\n}","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function set_Contador_Inicial_Reductor(context) {\n    const pageProxy = context.getPageProxy();\n    var form_add = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\")\n    var cont_inicial_reductor = form_add.getControl(\"cont_inicial_reductor\")\n    var btn_agregar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\")\n    //obtener los controlasdores del formulario\n    let equipo = form_add.getControl(\"equipo_reductor\")\n    let tipo = form_add.getControl(\"tipo_reductor\")\n    let kmh = form_add.getControl(\"kmh_reductor\")\n    let operario_reductor = form_add.getControl(\"operario_reductor\")\n    let cont_final = form_add.getControl(\"con_final_reductor\")\n    let observaciones = form_add.getControl(\"observaciones_reductor\")\n    let orden_reductor = form_add.getControl(\"orden_reductor\")\n\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let id_planilla = clientData.data_planilla_reductor.id;\n    let cantidad_ini;\n\n    const filtro = `$filter=planilla_id eq ${id_planilla}`;\n\n    //Leer los datos de items planilla\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ItemPlanillasAceites', [], filtro).then(async (results) => {\n        //si hay items en la planilla\n        if (results && results.length > 0) {\n            //alert(\"ya hay items en la planilla\");\n\n            // Trabajar directamente con el array results\n            // Encontrar el item con la posición más alta\n            let ultimoItem = null;\n            let maxPos = -1;\n\n            results.forEach(item => {\n                const pos = parseInt(item.pos);\n                if (!isNaN(pos) && pos > maxPos) {\n                    maxPos = pos;\n                    ultimoItem = item;\n                }\n            });\n\n            // Validar que tenga el campo 'contador_fin'\n            if (ultimoItem && ultimoItem.contador_fin !== undefined && ultimoItem.contador_fin !== null) {\n                cantidad_ini = ultimoItem.contador_fin;\n            } else {\n                cantidad_ini = clientData.data_planilla_reductor.contador_ini;\n            }\n\n        } else {\n\n            //alert(id_planilla);\n            cantidad_ini = clientData.data_planilla_reductor.contador_ini;\n        }\n\n        form_add.setVisible(true);\n\n        var cant_inicial_planilla = cantidad_ini;\n        //alert(cant_inicial_planilla)\n        cont_inicial_reductor.setValue(cant_inicial_planilla);\n        //----\n        equipo.setValue(\"\");\n        tipo.setValue(\"\");\n        observaciones.setValue(\"\");\n        kmh.setValue(\"\");\n        operario_reductor.setValue(\"\");\n        cont_final.setValue(\"\");\n        orden_reductor.setValue(\"\");\n        //----\n        orden_reductor.setVisible(false)\n        btn_agregar.setVisible(false)\n        \n\n    })\n        .catch((error) => {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Error\",\n                    \"Message\": `Error al consultar datos: ${error.message}`,\n                    \"OKCaption\": \"Cerrar\"\n                }\n            });\n        });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function set_Contador_Inicial_Servotransmisor(context) {\n    const pageProxy = context.getPageProxy();\n    var form_add = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\")\n    var cont_inicial_servotrans = form_add.getControl(\"cont_inicial_servotrans\")\n    var btn_agregar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\")\n    //obtener los controlasdores del formulario\n    let equipo = form_add.getControl(\"equipo_servotrans\")\n    let tipo = form_add.getControl(\"tipo_servotrans\")\n    let kmh = form_add.getControl(\"kmh_servotrans\")\n    let operario_servotrans = form_add.getControl(\"operario_servotrans\")\n    let cont_final = form_add.getControl(\"con_final_servotrans\")\n    let observaciones = form_add.getControl(\"observaciones_servotrans\")\n    let orden_dif = form_add.getControl(\"orden_servotrans\")\n\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let id_planilla = clientData.data_planilla_servotrans.id;\n    let cantidad_ini;\n\n    const filtro = `$filter=planilla_id eq ${id_planilla}`;\n\n    //Leer los datos de items planilla\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ItemPlanillasAceites', [], filtro).then(async (results) => {\n        //si hay items en la planilla\n        if (results && results.length > 0) {\n            //alert(\"ya hay items en la planilla\");\n\n            // Trabajar directamente con el array results\n            // Encontrar el item con la posición más alta\n            let ultimoItem = null;\n            let maxPos = -1;\n\n            results.forEach(item => {\n                const pos = parseInt(item.pos);\n                if (!isNaN(pos) && pos > maxPos) {\n                    maxPos = pos;\n                    ultimoItem = item;\n                }\n            });\n\n            // Validar que tenga el campo 'contador_fin'\n            if (ultimoItem && ultimoItem.contador_fin !== undefined && ultimoItem.contador_fin !== null) {\n                cantidad_ini = ultimoItem.contador_fin;\n            } else {\n                cantidad_ini = clientData.data_planilla_servotrans.contador_ini;\n            }\n\n        } else {\n\n            //alert(id_planilla);\n            cantidad_ini = clientData.data_planilla_servotrans.contador_ini;\n        }\n\n        form_add.setVisible(true);\n\n        var cant_inicial_planilla = cantidad_ini;\n        //alert(cant_inicial_planilla)\n        cont_inicial_servotrans.setValue(cant_inicial_planilla);\n        //----\n        equipo.setValue(\"\");\n        tipo.setValue(\"\");\n        observaciones.setValue(\"\");\n        kmh.setValue(\"\");\n        operario_servotrans.setValue(\"\");\n        cont_final.setValue(\"\");\n        orden_dif.setValue(\"\");\n        //----\n        orden_dif.setVisible(false);\n        btn_agregar.setVisible(false)\n\n\n    })\n        .catch((error) => {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Error\",\n                    \"Message\": `Error al consultar datos: ${error.message}`,\n                    \"OKCaption\": \"Cerrar\"\n                }\n            });\n        });\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Bool_Estado_Usuarios(context) {\n    try {\n        var object = context.binding\n        var estado = object.estado\n        \n        if(estado == \"Activo\"){\n            return true\n        }\n        if(estado == \"Inactivo\"){\n            return false\n        }\n    } catch (error) {\n        console.error(\"Ocurrió un error al obtener el valor:\", error);\n        alert(\"No se pudo obtener el valor: \" + error.message);\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Color_Estado_Usuarios(context) {\n    try {\n        var object = context.binding\n        var estado = object.estado\n        \n        if(estado == \"Activo\"){\n            return \"Green\"\n        }\n        if(estado == \"Inactivo\"){\n            return \"Red\"\n        }\n    } catch (error) {\n        console.error(\"Ocurrió un error al obtener el valor:\", error);\n        alert(\"No se pudo obtener el valor: \" + error.message);\n    }\n}\n","/**\n * Describe this function...\n * @param {context} clientAPI\n */\nexport default function Create_Almacenes(context) {\n\n    let lista_almacenes = context.evaluateTargetPath('#Page:Agregar_Almacenes/#Control:FormCellListPicker_Almacenes/#Value');\n    let tipo_almacen = context.evaluateTargetPath('#Page:Agregar_Almacenes/#Control:FormCellListPicker_Tipo/#Value');\n    let repetidos = \"\";\n    let errores = [];\n    let exitosos = [];\n\n    if (lista_almacenes.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes seleccionar al menos un almacén de la lista para continuar.`\n            }\n        });\n    }\n\n    if (!tipo_almacen || tipo_almacen < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes seleccionar un tipo de almacen.`\n            }\n        });\n    }\n\n    let tipoalmacen_value = tipo_almacen[0].ReturnValue;\n\n    let promises = lista_almacenes.map((almacen, i) => {\n        let nuevo_almacen = almacen.BindingObject;\n\n        return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'AlmacenesApp', [], `$filter=almacen eq '${nuevo_almacen.almacen}'`)\n            .then(result => {\n                if (result.length === 0) {\n                    return context.executeAction({\n                        \"Name\": \"/appconsumos_qa_mb/Actions/oData/Create_AlmacenesApp.action\",\n                        \"Properties\": {\n                            \"Properties\": {\n                                \"sociedad\": nuevo_almacen.sociedad,\n                                \"almacen\": nuevo_almacen.almacen,\n                               \"centro\": nuevo_almacen.centro,\n                                \"almacen_desc\": nuevo_almacen.almacen_desc,\n                                \"tipo\": tipoalmacen_value,\n                            }\n                        }\n                    }).then(() => {\n                        exitosos.push(`${nuevo_almacen.almacen} (${nuevo_almacen.almacen_desc})`);\n                    }).catch(() => {\n                        errores.push(`${nuevo_almacen.almacen} (${nuevo_almacen.almacen_desc})`);\n                    });\n                }\n                repetidos += `${nuevo_almacen.almacen} (${nuevo_almacen.almacen_desc}), `;\n                return Promise.resolve();\n            }).catch(() => {\n                errores.push(`${nuevo_almacen.almacen} (${nuevo_almacen.almacen_desc})`);\n            });\n    });\n\n    Promise.allSettled(promises).then(() => {\n\n        // Primero mostramos repetidos (si existen)\n        let repetidosPromise = Promise.resolve();\n        if (repetidos.length > 0) {\n            repetidosPromise = context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Repetidos\",\n                    \"Message\": `Se encontraron almacenes ya creados: ${repetidos}`\n                }\n            });\n        }\n\n        // Después de mostrar repetidos mostramos los otros mensajes\n        repetidosPromise.then(() => {\n            let mensajePromise;\n\n            if (errores.length > 0 && exitosos.length === 0) {\n                // Si todo falló\n                mensajePromise = context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Error\",\n                        \"Message\": `Falló la creación de los almacenes.`\n                    }\n                });\n            } else if (errores.length > 0 && exitosos.length > 0) {\n                // Algunos fallaron, otros no\n                mensajePromise = context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Alerta parcial\",\n                        \"Message\": `Algunos almacenes fueron creados exitosamente.\\n\\nAlmacenes con error:\\n${errores.join('\\n')}`\n                    }\n                });\n            } else {\n                // Todo fue exitoso\n                mensajePromise = context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Creación exitosa\",\n                        \"Message\": `Los Almacenes fueron creados exitosamente`\n                    }\n                });\n            }\n\n            // Finalmente, después de mostrar el mensaje final, cerramos la ventana\n            mensajePromise.then(() => {\n                context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/CloseModalPage_Complete.action\",\n                    \"NavigateBackToPage\": \"/appconsumos_qa_mb/Pages/Administracion/Lista_Almacenes.page\"\n                });\n            });\n        });\n    });\n\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default async function Create_Usuarios(context) {\n    let lista_empleados = context.evaluateTargetPath('#Page:Agregar_Usuarios/#Control:ListaEmpleados/#Value');\n    let rol = context.evaluateTargetPath('#Page:Agregar_Usuarios/#Control:rol/#Value');\n    let isadmin = context.evaluateTargetPath('#Page:Agregar_Usuarios/#Control:isadmin/#Value');\n    let repetidos = \"\";\n    let errores = [];\n    let exitosos = [];\n\n    if (lista_empleados.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes seleccionar al menos un empleado de la lista para continuar`\n            }\n        });\n    }\n\n    if (!rol || rol.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes seleccionar un rol para los usuarios`\n            }\n        });\n    }\n\n    let rol_value = rol[0].ReturnValue;\n    \n    let promises = lista_empleados.map((empleado, i) => {\n        let nuevo_empleado = empleado.BindingObject;\n\n        return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'EmpleadosApp', [], `$filter=ficha eq '${nuevo_empleado.ficha}'`)\n            .then(result => {\n                if (result.length === 0) {\n                    return context.executeAction({\n                        \"Name\": \"/appconsumos_qa_mb/Actions/oData/Create_EmpleadosApp.action\",\n                        \"Properties\": {\n                            \"Properties\": {\n                                \"ficha\": nuevo_empleado.ficha,\n                                \"nombre\": nuevo_empleado.nombre,\n                                \"correo\": nuevo_empleado.correo,\n                                \"rol\": rol_value,\n                                \"isAdmin\":isadmin,\n                                \"cargo\": nuevo_empleado.cargo,\n                                \"sociedad\": nuevo_empleado.sociedad,\n                                \"sapUsr\": nuevo_empleado.sapUsr\n                            }\n                        }\n                    }).then(() => {\n                        exitosos.push(`${nuevo_empleado.nombre} (${nuevo_empleado.ficha})`);\n                    }).catch(() => {\n                        errores.push(`${nuevo_empleado.nombre} (${nuevo_empleado.ficha})`);\n                    });\n                }\n                repetidos += `${nuevo_empleado.nombre} (${nuevo_empleado.ficha}), `;\n                return Promise.resolve();\n            }).catch(() => {\n                errores.push(`${nuevo_empleado.nombre} (${nuevo_empleado.ficha})`);\n            });\n    });\n\n    Promise.allSettled(promises).then(() => {\n\n        // Primero mostramos repetidos (si existen)\n        let repetidosPromise = Promise.resolve();\n        if (repetidos.length > 0) {\n            repetidosPromise = context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Repetidos\",\n                    \"Message\": `Se encontraron usuarios ya creados: ${repetidos}`\n                }\n            });\n        }\n\n        // Después de mostrar repetidos mostramos los otros mensajes\n        repetidosPromise.then(() => {\n            let mensajePromise;\n\n            if (errores.length > 0 && exitosos.length === 0) {\n                // Si todo falló\n                mensajePromise = context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Error\",\n                        \"Message\": `Falló la creación de los usuarios.`\n                    }\n                });\n            } else if (errores.length > 0 && exitosos.length > 0) {\n                // Algunos fallaron, otros no\n                mensajePromise = context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Alerta parcial\",\n                        \"Message\": `Algunos usuarios fueron creados exitosamente.\\n\\nUsuarios con error:\\n${errores.join('\\n')}`\n                    }\n                });\n            } else {\n                // Todo fue exitoso\n                mensajePromise = context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Creación exitosa\",\n                        \"Message\": `Se finalizó el proceso de creación exitosamente`\n                    }\n                });\n            }\n\n            // Finalmente, después de mostrar el mensaje final, cerramos la ventana\n            mensajePromise.then(() => {\n                context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/CloseModalPage_Complete.action\",\n                    \"NavigateBackToPage\": \"/appconsumos_qa_mb/Pages/Administracion/Lista_Usuarios.page\"\n                });\n            });\n        });\n    });\n\n\n    //[0].ReturnValue\n    //(lista_empleados[0].BindingObject)\n    //alert(JSON.stringify(context.evaluateTargetPath(\"#Page:Agregar_Usuarios/#Control:ListaEmpleados/#Value/#Index:1/BindingObject/cargo\")))\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function NavTo_Administracion(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData.info_user\n\n    if(!clientData.info_user){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n            \"Properties\": {\n                \"Message\": `Sincronizando datos, por favor espera un momento...`,\n                \"Duration\": 1\n            }\n        });\n    }\n\n    if (info.isAdmin && info.estado == 'Activo') {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n            \"Properties\": {\n                \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Administracion/Inicio_Admin.page\"\n            }\n        });\n    }\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n        \"Properties\": {\n            \"Title\": \"Alerta\",\n            \"Message\": `No tienes permisos para ingresar a este módulo`\n        }\n    });\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Switch_Estado(context) {\n    const pageProxy = context.getPageProxy();\n    var sw_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell1\").getControl(\"estado_edit\")\n    var estado_temp = context.getValue()\n\n    if(estado_temp){\n        sw_component.setHelperText('Activo')\n    }else{\n        sw_component.setHelperText('Inactivo')\n    }\n\n    //alert(sw_component.getType())\n    //alert(JSON.stringify(object))\n    //alert(JSON.stringify(context.binding))\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function get_Estado(context) {\n    const pageProxy = context.getPageProxy();\n    var sw_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell1\").getControl(\"estado_edit\")\n    var estado_temp = sw_component.getValue()\n\n    if(estado_temp){\n        return 'Activo'\n    }else{\n        return 'Inactivo'\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function get_Rol_Admin_List(context) {\n    try {\n        var object = context.binding\n        var rol = object.rol\n        var isadmin = object.isAdmin\n        \n        return isadmin ? rol + \" - Admin\" : rol;\n\n        \n    } catch (error) {\n        console.error(\"Ocurrió un error al obtener el valor:\", error);\n        alert(\"No se pudo obtener el valor: \" + error.message);\n    }\n}\n","\nvar clientAPI;\n\n/**\n * Describe this function...\\n@param {IClientAPI} clientAPI\n */\nexport default function Agregar_Planilla_Aceites_Incauca(clientAPI) {\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function AppUpdateFailure(clientAPI) {\n    let result = clientAPI.actionResults.AppUpdate.error.toString();\n    var message;\n    console.log(result);\n    if (result.startsWith('Error: Uncaught app extraction failure:')) {\n        result = 'Error: Uncaught app extraction failure:';\n    }\n    if (result.startsWith('Error: LCMS GET Version Response Error Response Status: 404 | Body: 404 Not Found: Requested route')) {\n        result = 'Application instance is not up or running';\n    }\n    if (result.startsWith('Error: LCMS GET Version Response Error Response Status: 404 | Body')) {\n        result = 'Service instance not found.';\n    }\n\n    switch (result) {\n        case 'Service instance not found.':\n            message = 'Mobile App Update feature is not assigned or not running for your application. Please add the Mobile App Update feature, deploy your application, and try again.';\n            break;\n        case 'Error: LCMS GET Version Response Error Response Status: 404 | Body: Failed to find a matched endpoint':\n            message = 'Mobile App Update feature is not assigned to your application. Please add the Mobile App Update feature, deploy your application, and try again.';\n            break;\n        case 'Error: LCMS GET Version Response failed: Error: Optional(OAuth2Error.tokenRejected: The newly acquired or refreshed token got rejected.)':\n            message = 'The Mobile App Update feature is not assigned to your application or there is no Application metadata deployed. Please check your application in Mobile Services and try again.';\n            break;\n        case 'Error: Uncaught app extraction failure:':\n            message = 'Error extracting metadata. Please redeploy and try again.';\n            break;\n        case 'Application instance is not up or running':\n            message = 'Communication failure. Verify that the BindMobileApplicationRoutesToME Application route is running in your BTP space cockpit.';\n            break;\n        default:\n            message = result;\n            break;\n    }\n    return clientAPI.getPageProxy().executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/Application/AppUpdateFailureMessage.action\",\n        \"Properties\": {\n            \"Duration\": 0,\n            \"Message\": message\n        }\n    });\n}","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nfunction sleep(ms) {\n    return (new Promise(function(resolve, reject) {\n        setTimeout(function() {\n            resolve();\n        }, ms);\n    }));\n}\nexport default function AppUpdateSuccess(clientAPI) {\n    var message;\n    // Force a small pause to let the progress banner show in case there is no new version available\n    return sleep(500).then(function() {\n        let result = clientAPI.actionResults.AppUpdate.data;\n        console.log(result);\n\n        let versionNum = result.split(': ')[1];\n        if (result.startsWith('Current version is already up to date')) {\n            return clientAPI.getPageProxy().executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/Application/AppUpdateSuccessMessage.action\",\n                \"Properties\": {\n                    \"Message\": `Ya estás usando la última versión: ${versionNum}`,\n                    \"NumberOfLines\": 2\n                }\n            });\n        } else if (result === 'AppUpdate feature is not enabled or no new revision found.') {\n            message = 'No se encontraron metadatos de la aplicación. Implemente su aplicación y vuelva a intentarlo.';\n            return clientAPI.getPageProxy().executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/Application/AppUpdateSuccessMessage.action\",\n                \"Properties\": {\n                    \"Duration\": 5,\n                    \"Message\": message,\n                    \"NumberOfLines\": 2\n                }\n            });\n        }\n    });\n}","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function ClientIsMultiUserMode(clientAPI) {\n    return clientAPI.isAppInMultiUserMode();\n}","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function GetClientSupportVersions(clientAPI) {\n    let versionInfo = clientAPI.getVersionInfo();\n    let versionStr = '';\n    Object.keys(versionInfo).forEach(function(key, index) {\n        // key: the name of the object key\n        // index: the ordinal position of the key within the object\n        //console.log(`Key: ${key}   Index: ${index}`);\n        if (key != 'Application Version') {\n            versionStr += `${key}: ${versionInfo[key]}\\n`;\n        }\n    });\n    return versionStr;\n}","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function GetClientVersion(clientAPI) {\n    let versionInfo = clientAPI.getVersionInfo();\n    if (versionInfo.hasOwnProperty('Application Version')) {\n        return versionInfo['Application Version'];\n    }\n}","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function OnWillUpdate(clientAPI) {\n\n    return clientAPI.executeAction('/appconsumos_qa_mb/Actions/Application/OnWillUpdate.action').then((result) => {\n        if (result.data) {\n            let _app_consumos_qa = clientAPI.executeAction('/appconsumos_qa_mb/Actions/app_consumos_qa/Service/CloseOffline.action');\n            let _app_consumos_qa_v2 = clientAPI.executeAction('/appconsumos_qa_mb/Actions/backend_REST/Service/CloseOffline.action');\n            let ZBODEGA_AGO_SRV = clientAPI.executeAction('/appconsumos_qa_mb/Actions/ZBODEGA_AGO_SRV/Service/CloseOffline.action');\n            return Promise.all([_app_consumos_qa, ZBODEGA_AGO_SRV, _app_consumos_qa_v2]).then(() => {\n                Promise.resolve();\n            }).catch((err) => {\n                Promise.reject('Error al cerrar Odatas sin conexión ' + err.message);\n            });\n        } else {\n            return Promise.reject('User Deferred');\n        }\n    });\n\n\n}\n\n\n\n\n\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function ResetAppSettingsAndLogout(clientAPI) {\n    let logger = clientAPI.getLogger();\n    let platform = clientAPI.nativescript.platformModule;\n    let appSettings = clientAPI.nativescript.appSettingsModule;\n    var appId;\n    if (platform && (platform.isIOS || platform.isAndroid)) {\n        appId = clientAPI.evaluateTargetPath('#Application/#AppData/MobileServiceAppId');\n    } else {\n        appId = 'WindowsClient';\n    }\n    try {\n        // Remove any other app specific settings\n        appSettings.getAllKeys().forEach(key => {\n            if (key.substring(0, appId.length) === appId) {\n                appSettings.remove(key);\n            }\n        });\n    } catch (err) {\n        logger.log(`ERROR: AppSettings cleanup failure - ${err}`, 'ERROR');\n    } finally {\n        // Logout \n        return clientAPI.getPageProxy().executeAction('/appconsumos_qa_mb/Actions/Application/Reset.action');\n    }\n}","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Agregar_Material_Revision_Campo(context) {\n    const pageProxy = context.getPageProxy();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitudes_Campo').getClientData();\n    //clientData.lista_mat_solicitud_ing\n    let operacion = context.evaluateTargetPath('#Page:Revision_Solicitud_Campo/#Control:operacion_item/#Value')\n\n    let material = context.evaluateTargetPath('#Page:Revision_Solicitud_Campo/#Control:materiales_solicitud/#Value');\n    let cant = context.evaluateTargetPath('#Page:Revision_Solicitud_Campo/#Control:cantidad_revision/#Value');\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\");\n\n    let data = material[0].BindingObject\n    let solicitada = data.cantidad_tomada\n\n    if (!cant || cant < 0) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Material no Agregado\",\n                \"Message\": `Debes ingresar una cantidad válida para continuar`\n            }\n        });\n    }\n\n    if(cant > solicitada){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Material no Agregado\",\n                \"Message\": `La cantidad a aprobar (${cant}) es mayor a la  cantidad solicitada (${solicitada})`\n            }\n        });\n    }\n\n    if (operacion.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Operación no seleccionada\",\n                \"Message\": \"Debes seleccionar una operación. Este campo es obligatorio.\",\n                \"OKCaption\": \"Aceptar\"\n            }\n        })\n    }\n\n    const duplicado = clientData.lista_mat_solicitud_campo.filter(m => m.material.material === data.material.material && m.almacen_almacen === data.almacen_almacen).length > 0\n\n    if (duplicado) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Material no Agregado\",\n                \"Message\": `El material ya fue ingresado anteriormente`\n            }\n        });\n    }\n\n    data.cant = cant\n    data.aprobado = 'Aprobado'\n    data.operacion = operacion[0].ReturnValue\n    clientData.lista_mat_solicitud_campo.push(data);\n\n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Material Aprobado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    });\n    \n    \n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Agregar_Materiales_Solicitud(context) {\n    const pageProxy = context.getPageProxy();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Orden_Campo').getClientData();\n\n    let material = context.evaluateTargetPath('#Page:Agregar_Solicitud_Campo/#Control:material/#Value');\n    let cant = context.evaluateTargetPath('#Page:Agregar_Solicitud_Campo/#Control:cantidad/#Value');\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n\n    if (material.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes seleccionar un material para continuar`\n            }\n        });\n    }\n    \n    let data = material[0].BindingObject\n    let stock = data.stock_disponible\n\n    //TODO DESCOMENTAR CUANDO HAYA INVENTARIO\n    if(stock == 0){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `No hay stock disponible para este material`\n            }\n        });\n    }\n\n    if (!cant || cant < 0) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes ingresar una cantidad válida para continuar`\n            }\n        });\n    }\n\n    //TODO DESCOMENTAR CUANDO HAYA INVENTARIO\n    if(cant > stock){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes ingresar una cantidad menor para continuar. La cantidad disponible es de ${stock} und`\n            }\n        });\n    }\n    \n    const duplicado = clientData.lista_materiales.filter(m => m.material === data.material && m.almacen.almacen === data.almacen.almacen).length > 0\n    \n    if (duplicado) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `El material ya fue ingresado anteriormente`\n            }\n        });\n    }\n\n    data.cant = cant\n    clientData.lista_materiales.push(data)\n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Nuevo material agregado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default async function Aprobar_Solicitud_Revision_Componentes_Campo(context) {\n    const pageProxy = context.getPageProxy();\n    var materiales = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell1\")\n    let materialesRechazados = [];\n    let materialesAprobados = [];\n    let exitosos = [];\n    let errores = [];\n    let id_solicitud = context.binding.id;\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitudes_Campo').getClientData();\n    let filtro = `$expand=material,almacen&$filter=solicitud_id eq ${id_solicitud}`;\n    let operacion = context.evaluateTargetPath('#Page:Revision_Solicitud_Campo/#Control:operacion/#Value') \n\n\n    if (materiales.getVisible()) {\n        //cuando los materiales fueron aprobados por item\n\n        let listaDeAgregados = clientData.lista_mat_solicitud_campo;\n\n        listaDeAgregados.forEach(item => {\n            const materialData = {\n                descripcion: item.material.desc,\n                material: item.material_material,\n                almacen_centro: item.almacen.centro,\n                almacen_sociedad: item.almacen.sociedad,\n                almacen_almacen: item.almacen_almacen,\n                id_componente: item.id,\n                readLink: item[\"@odata.readLink\"]\n            };\n\n            if (item.aprobado === 'Aprobado') {\n                materialData.cantidad_aprobada = item.cant;\n                materialData.operacion = item.operacion\n                materialesAprobados.push(materialData);\n            } else {\n               \n                //rechazado\n                materialData.cantidad_aprobada = 0;\n                materialesRechazados.push(materialData);\n            }\n        });\n\n    } else {\n        //cuando se aprueban todos los materiales por defecto\n        await context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ComponentesSolicitud', [], filtro).then(async (results) => {\n            if (results && results.length > 0) {\n                for (let i = 0; i < results.length; i++) {\n                    let item = results.getItem(i);\n                    materialesAprobados.push({\n                        descripcion: item.material.material_desc,\n                        material: item.material_material,\n                        almacen_centro: item.almacen.centro,\n                        almacen_sociedad: item.almacen.sociedad,\n                        almacen_almacen: item.almacen.almacen,\n                        id_componente: item.id,\n                        operacion: operacion[0].ReturnValue,\n                        cantidad_aprobada: item.cantidad_tomada,\n                        readLink: item[\"@odata.readLink\"]\n                    });\n                }\n            } else {\n                return context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Error\",\n                        \"Message\": \"Error al tratar de traer los componentes de la solicitud (Aprobar componentes)\"\n                    }\n                })\n            }\n        }).catch((error) => {\n            alert(`Error ${error.message}`);\n        });\n\n\n    }\n\n    let promisesAprobados = materialesAprobados.map(material => {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/oData/Update_ComponentesSolicitudApp.action\",\n            \"Properties\": {\n                \"Target\": {\n                    \"ReadLink\": material.readLink\n                },\n                \"Properties\": {\n                    \"id\": material.id_componente,\n                    \"cantidad_aprobada\": material.cantidad_aprobada,\n                    \"aprobado\": true,\n                    \"op_number\": material.operacion\n                }\n            }\n        }).then(() => {\n            exitosos.push(`${material.material} - ${material.descripcion}`);\n        }).catch((error) => {\n            alert(`Error actualizando material ${material.material}:`, error);\n            errores.push(`${material.material} - ${material.descripcion}`);\n        });\n    });\n\n    let promisesRechazados = materialesRechazados.map(material => {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/oData/Update_ComponentesSolicitudApp.action\",\n            \"Properties\": {\n                \"Target\": {\n                    \"ReadLink\": material.readLink\n                },\n                \"Properties\": {\n                    \"id\": material.id_componente,\n                    \"cantidad_aprobada\": 0,\n                    \"aprobado\": false,\n                    \"confirmacion_tec\": false,\n                    \"op_number\": null                 \n                }\n            }\n        }).then(() => {\n            exitosos.push(`${material.material} - ${material.descripcion}`);\n        }).catch((error) => {\n            alert(`Error actualizando material ${material.material}:`, error);\n            errores.push(`${material.material} - ${material.descripcion}`);\n        });\n    });\n\n    // Procesar los resultados\n    return Promise.allSettled([...promisesAprobados, ...promisesRechazados]).then(() => {\n        let mensaje = '';\n\n        if (errores.length === 0) {\n            mensaje = 'Solicitud gestionada correctamente. Todos los materiales de la solicitud fueron gestionados exitosamente.';\n        } else if (exitosos.length === 0) {\n            mensaje = `Solicitud no gestionada. Falló la gestión de todos los materiales:\\n${errores.join('\\n')}`;\n        } else {\n            mensaje = `Solicitud no gestionada parcialmente. Algunos materiales fueron gestionados con éxito.\\n\\nErrores:\\n${errores.join('\\n')}`;\n        }\n\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Resultado\",\n                \"Message\": mensaje\n            }\n        }).then(() => {\n        \n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/CloseModalPage_Complete.action\",\n                \"NavigateBackToPage\": \"/appconsumos_qa_mb/Pages/Campo/Detalle_Solicitudes_Campo.page\"\n            })\n        });\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Borrar_Material_Lista(context) {\n    var data = context.binding\n    const pageProxy = context.getPageProxy();\n\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Orden_Campo').getClientData();\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n\n\n    const index = clientData.lista_materiales.findIndex(item => item.material === data.material && item.almacen.almacen === data.almacen.almacen);\n\n\n    if (index !== -1) {\n        clientData.lista_materiales.splice(index, 1); // Elimina el elemento en esa posición\n\n    }\n\n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Material '${data.material_desc}' del ${data.almacen.almacen_desc} eliminado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    })\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Borrar_Materiales_Revision_Campo(context) {\n    var data = context.binding\n    const pageProxy = context.getPageProxy();\n\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitudes_Campo').getClientData();\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n\n\n    const index = clientData.lista_mat_solicitud_campo.findIndex(item => item.material.material === data.material.material && item.almacen_almacen === data.almacen_almacen);\n\n\n    if (index !== -1) {\n        clientData.lista_mat_solicitud_campo.splice(index, 1); // Elimina el elemento en esa posición\n\n    }\n\n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Material '${data.material.material_desc}' del ${data.almacen_almacen} eliminado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    })\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Color_Estado_Sol_Campo(context) {\n    try {\n        var object = context.binding\n        var estado = object.estado\n        \n        if(estado == \"Enviado\"){\n            return \"Grey\"\n        }\n        if(estado == \"Aprobado\"){\n            return \"Mango\"\n        }\n        if(estado == \"Rechazado\"){\n            return \"Red\"\n        }\n        if(estado == \"Autorizado\"){\n            return \"Green\"\n        }\n        if(estado == \"Tramitado\"){\n            return \"Teal\"\n        }\n    } catch (error) {\n        console.error(\"Ocurrió un error al obtener el valor:\", error);\n        alert(\"No se pudo obtener el valor: \" + error.message);\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function ConfirmarSolicitudCampo(context) {\n\n    const pageProxy = context.getPageProxy();\n    var materiales = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell1\")\n    let operacion = context.evaluateTargetPath('#Page:Revision_Solicitud_Campo/#Control:operacion/#Value') \n\n    let id_solicitud = context.binding.id;\n    //let filtro = `$expand=almacen&$filter=solicitud_id eq ${id_solicitud}`;\n    let filtro = `$filter=solicitud_id eq ${id_solicitud}`;\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitudes_Campo').getClientData();\n    let listaDeAgregados = clientData.lista_mat_solicitud_campo;\n\n\n    if (materiales.getVisible()) {\n        //validar que si se hayan agregado todos los materiales a la solicitud\n        return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ComponentesSolicitud', [], filtro).then(async (results) => {\n            if (results && results.length > 0) {\n                let totalComponentes = results.length;\n\n                if (listaDeAgregados.length == totalComponentes) {\n                    // Validaciones sobre el campo 'aprobado'\n                    let todosRechazados = listaDeAgregados.every(m => m.aprobado === 'Rechazado');\n                    let alMenosUnoAprobado = listaDeAgregados.some(m => m.aprobado === 'Aprobado');\n\n                    if (todosRechazados) {\n                        return context.executeAction({\n                            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                            \"Properties\": {\n                                \"Title\": \"Solicitud No Aprobada\",\n                                \"Message\": \"No se puede aprobar la solicitud porque todos los materiales fueron rechazados.\"\n                            }\n                        });\n                    }\n                    if (alMenosUnoAprobado) {\n                        return context.executeAction({\n                            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                            \"Properties\": {\n                                \"Title\": \"Confirmación\",\n                                \"Message\": \"¿Estás seguro de que deseas confirmar la solicitud aprobada por ítems?\",\n                                \"OKCaption\": \"Aceptar\",\n                                \"OnOK\": \"/appconsumos_qa_mb/Actions/oData/Update_SolicitudesApp_Aprobar_Campo.action\",\n                                \"CancelCaption\": \"Cancelar\"\n                            }\n                        })\n                    }\n\n                } else if (listaDeAgregados.length < totalComponentes) {\n                    return context.executeAction({\n                        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                        \"Properties\": {\n                            \"Title\": \"Solicitud No Confirmada\",\n                            \"Message\": \"No puedes confirmar la solicitud hasta que se hayan agregado todos los materiales.\"\n                        }\n                    })\n                }\n\n\n            } else {\n                return context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Error\",\n                        \"Message\": \"Error al tratar de traer los componentes de la solicitud\"\n                    }\n                })\n            }\n\n\n        }).catch((error) => {\n            alert(`Error ${error.message}`);\n        });\n\n    } else {\n\n        if (operacion.length < 1) {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Operación no seleccionada\",\n                    \"Message\": \"Debes seleccionar una operación antes de confirmar. Este campo es obligatorio.\",\n                    \"OKCaption\": \"Aceptar\"\n                }\n            })\n        }\n\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Confirmar Solicitud\",\n                \"Message\": \"¿Estás seguro de que deseas confirmar la solicitud con las cantidades originales solicitadas y la operación seleccionada?\",\n                \"OKCaption\": \"Aceptar\",\n                \"OnOK\": \"/appconsumos_qa_mb/Actions/oData/Update_SolicitudesApp_Aprobar_Campo.action\",\n                \"CancelCaption\": \"Cancelar\"\n            }\n        })\n\n    }\n}\n","import guid from '../guid'\n\n/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Create_Componentes_Solicitud(context) {\n    let actionResult = context.getActionResult(\"Create_Solicitud_Campo\")\n    let data = JSON.parse(actionResult.data)\n    let idSolicitud = data.id\n\n \n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Orden_Campo').getClientData();\n    let lista_materiales = clientData.lista_materiales;\n \n    // Obtener datos del almacén desde ClientData\n    let dataAlmacen = context.evaluateTargetPath('#Page:Filtro_Campo/#Control:almacen_campo/#Value')[0].BindingObject \n \n    let exitosos = [];\n    let errores = [];\n \n    // Create de la solicitud\n    let promises = lista_materiales.map(material => {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/oData/Create_ComponentesSolicitudApp.action\",\n            \"Properties\": {\n                \"Properties\": {\n                    \"id\": guid(context),\n                    \"material_material\": material.material,\n                    \"material_almacen\": material.almacen.almacen,\n                    \"material_centro\": material.almacen.centro,\n                    \"material_sociedad\": material.almacen.sociedad,\n                    \"almacen_sociedad\": material.almacen.sociedad,\n                    \"almacen_almacen\": material.almacen.almacen,\n                    \"almacen_centro\": material.almacen.centro,\n                    \"solicitud_id\": idSolicitud,\n                    \"cantidad_tomada\": material.cant\n                }\n            }\n        }).then(() => {\n            exitosos.push(`${material.almacen.almacen_desc} - ${material.material_desc}`);\n        }).catch(() => {\n            errores.push(`${material.almacen.almacen_desc} - ${material.material_desc}`);\n        });\n    });\n \n    // Procesar los resultados\n    return Promise.allSettled(promises).then(() => {\n        let mensaje = '';\n \n        if (errores.length === 0) {\n            mensaje = 'Solicitud creada. Todos los materiales fueron agregados exitosamente a la solicitud.';\n        } else if (exitosos.length === 0) {\n            mensaje = `Solicitud creada. Falló la creación de todos los materiales:\\n${errores.join('\\n')}`;\n        } else {\n            mensaje = `Solicitud creada. Algunos materiales fueron agregados con éxito.\\n\\nErrores:\\n${errores.join('\\n')}`;\n        }\n \n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Resultado\",\n                \"Message\": mensaje\n            }\n        }).then(() => {\n            // Finalmente cerrar el modal\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/CloseModalPage_Complete.action\",\n                \"NavigateBackToPage\": \"/appconsumos_qa_mb/Pages/Campo/Detalle_Orden_Campo.page\"\n            });\n        });\n    });\n\n\n}\n","import Rule_openDocumentoAnd from '../Rule_openDocumentoAnd.js';\nimport Rule_openDocumentoIOS from '../Rule_openDocumentoIOS.js';\n/**\n * Describe this function...\n * @param {IClientAPI} context\n */\n\nexport default async function FirmarSolicitud_Campo(context) {\n\n    //manejar bien los errores del backend y la autenticación\n    //no se envia correo electronico\n    //1. Enviar los componentes a la orden - hay que validar si ya hay creados materiales con las cantidades solicitadas usar esos campos y no hay que crearlos \n    //   - se debe guardar en los componentes de la solicitud las posiciones en la reserva de los materiales creados o escogidos\n    //2. liquidar los componentes de la orden - se debe guardar el numero de documento de material en cada componente y se debe mostrar en el detalle de los items de la solicitud\n    //3. actualizar los componentes como entregados en la bd y el estado de la solicitud \n    //4. se debe obtener el pdf de la orden y mostrarlo con la firma del autorizador ingresada y guardar el pdf a la base de datos para luego poder consultarlo desde el historico\n\n\n\n    function sendEmail(pdf) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/Call_Sendmail.action\",\n            \"Properties\": {\n                \"OnFailure\": \"\",\n                \"OnSuccess\": \"\",\n                \"Target\": {\n                    \"Service\": \"/appconsumos_qa_mb/Services/backend_REST.service\",\n                    \"Path\": \"/sendmail\",\n                    \"RequestProperties\": {\n                        \"Method\": \"POST\",\n                        \"Body\": {\n                            \"sender\": \"natalia.lopez@structum-co.com\",\n                            \"to\": \"nlopez8066@outlook.com\",\n                            \"subject\": \"Prueba\",\n                            \"body\": `Cuerpo prueba`,\n                            \"nombre\": \"pdfprueba.pdf\",\n                            \"adj\":`${pdf}`\n                        },\n\n                    }\n                }\n            }\n        }).then((result) => {\n            if (result && result.data) {\n                alert(JSON.stringify(result))\n            }\n\n        }).catch((error) => {\n            alert(error)\n        });\n    }\n\n    const base64Pdf = ``\n    \n    //const pageProxy = context.getPageProxy();\n    const platform = context.nativescript.platformModule;\n    const signatureObject = context.evaluateTargetPath(\"#Page:Autorizar_Solicitud_Campo/#Control:FormCellInlineSignatureCapture0/#Value\");\n    let signatureContent;\n\n    if (platform.isAndroid) {\n        signatureContent = android.util.Base64.encodeToString(signatureObject.content, android.util.Base64.DEFAULT);\n    } else if (platform.isIOS) {\n        signatureContent = signatureObject.content.base64Encoding();\n    }\n\n    alert(\"entro firmar\")\n\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/Call_FirmarPDF.action\",\n        \"Properties\": {\n            \"OnFailure\": \"\",\n            \"OnSuccess\": \"\",\n            \"Target\": {\n                \"Service\": \"/appconsumos_qa_mb/Services/backend_REST.service\",\n                \"Path\": \"/firmarPDF\",\n                \"RequestProperties\": {\n                    \"Method\": \"POST\",\n                    \"Body\": {\n                        \"pdf\": `${base64Pdf}`,\n                        \"image\": `${signatureContent}`\n                    },\n\n                }\n            }\n        }\n    }).then((result) => {\n        if (result && result.data) {\n\n            //alert(result.data.value)//el pdf en base64\n            context.b64Data = result.data.value\n            sendEmail(result.data.value)\n            if (platform.isAndroid) {\n                return Rule_openDocumentoAnd(context)\n            } else if (platform.isIOS) {\n                return Rule_openDocumentoIOS(context)\n            }\n\n\n            /*context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/openDocument.action\",\n                \"Properties\":{\n                    \"Path\": result.data.value,\n                    \"MimeType\": \"application/pdf\",\n                    \"OnSuccess\":\"\"\n                }\n            });*/\n            //let mensaje = result.data.Message;\n\n        }\n\n\n\n    }).catch((error) => {\n        alert(error)\n    });\n\n    /*let servicePath = \"/appconsumos_qa_mb/Services/app_consumos_qa.service\";\n    let functionDef = {\n        \"Name\": \"firmarPDF\",\n        \"Parameters\": {\n            \"pdf\": `${base64Pdf}`,\n            \"image\":`${signatureContent}`\n        }\n    };\n    let headers = null;\n    return context.callFunction(servicePath, functionDef, headers).then((result) => {\n        // Si el servicio devuelve un string plano\n        alert(result)\n        alert(JSON.stringify(result))\n        if (result && typeof result === \"string\") {\n            alert(`Resultado: ${result}`);\n        } else if (result && result.value) {\n            alert(`Resultado: ${result.value}`);\n        } else {\n            alert(\"La acción no devolvió resultado esperado.\");\n        }\n    }).catch((error) => {\n        alert(`Error al ejecutar firmaPDF: ${error}`);\n    });*/\n\n\n    /*alert(\"entro\")\n    let result;\n    try {\n        result = await context.invokeFunction(\"firmarPDF\", { pdf: `${base64Pdf}`, image: `${signatureContent}` });\n        if (result.data) {\n            // Handle the result (e.g., display it in a message)\n            alert(\"res exitosa\")\n        }\n    } catch (error) {\n        alert(\"Error al firmar el PDF:\");\n        alert(error)\n    }*/\n\n\n    /*let servicePath = \"/appconsumos_qa_mb/Services/app_consumos_qa.service\";\n    let functionDef = {\n        \"Name\": \"firmarPDF\",\n        \"Parameters\": {\n            \"pdf\": `${base64Pdf}`,\n            \"image\":`${signatureContent}`\n        }\n    };\n    let headers = null;\n    return context.callFunction(servicePath, functionDef, headers).then((result) => {\n        //Because this Function Import return an Edm.Int64 type data, the result in result will simply be an integer value.\n        alert(\"res exitosa\")\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Rules/Campo/Response_firmarPDF.js\",\n        });\n    }).catch((error) => {\n        alert(error)\n    });*/\n\n\n    /*return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/oData/Call_firmarPDF.action\",\n        \"Properties\": {\n            \"OnFailure\": {\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Message\": \"Error - {#ActionResults:Call_firmarPDF/error}\"\n                }\n            },\n            \"OnSuccess\": \"/appconsumos_qa_mb/Rules/Campo/Response_firmarPDF.js\",\n            \"Target\": {\n                \"Service\": \"/appconsumos_qa_mb/Services/backend_REST.service\",\n                \"Path\": `/firmarPDF(pdf='${base64Pdf}',image='${signatureContent}')`,\n                \"RequestProperties\": {\n                    \"Method\": \"GET\",\n                    \"FetchCSRF\": true\n                }\n            }\n        }\n    })*/\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function NavTo_Agregar_Solicitud_Campo(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Orden_Campo').getClientData();\n    clientData.lista_materiales = []\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n        \"Properties\": {\n            \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Campo/Agregar_Solicitud_Campo.page\",\n            \"ModalPage\": true,\n            \"ModalPageFullscreen\": true\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function NavTo_Campo(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData.info_user\n\n    if(!clientData.info_user){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n            \"Properties\": {\n                \"Message\": `Sincronizando datos, por favor espera un momento...`,\n                \"Duration\": 1\n            }\n        });\n    }\n\n    if (info.estado == 'Activo') {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n            \"Properties\": {\n                \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Campo/Filtro_Campo.page\"\n            }\n        });\n    }\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n        \"Properties\": {\n            \"Title\": \"Alerta\",\n            \"Message\": `No tienes permisos para ingresar a este módulo`\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function NavTo_List_Campo(context) {\n    let centro = context.evaluateTargetPath('#Page:Filtro_Campo/#Control:almacen_campo/#Value')[0].BindingObject.centro\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Campo').getClientData();\n    clientData.centro = centro\n    clientData.lista_campo = []\n    \n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n        \"Properties\": {\n            \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Campo/Lista_Ordenes_Campo.page\"\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function NavTo_List_Historico_Sol_Campo(context) {\n    let data = context.evaluateTargetPath('#Page:Filtro_Campo/#Control:almacen_campo/#Value')[0].BindingObject\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Campo').getClientData();\n    clientData.centroH = data.centro\n    clientData.almacenH = data.almacen\n    clientData.sociedadH = data.sociedad\n    clientData.lista_sol_historico_campo = []\n    \n    let filtro = `$expand=almacen,operario,aprobador,autorizador,equipo,orden&$filter=almacen_sociedad eq '${data.sociedad}' and almacen_almacen eq '${data.almacen}' and almacen_centro eq '${data.centro}' and tipo eq 'CAMPO' &$orderby=fecha_creacion desc`\n    clientData.filtroHistoricoCampo = filtro;\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n        \"Properties\": {\n            \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Campo/Lista_Historico_Campo.page\"\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function NavTo_List_Sol_Campo(context) {\n    let data = context.evaluateTargetPath('#Page:Filtro_Campo/#Control:almacen_campo/#Value')[0].BindingObject\n    let clientDataUser = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    \n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Campo').getClientData();\n    clientData.centro = data.centro\n    clientData.almacen = data.almacen\n    clientData.sociedad = data.sociedad\n    clientData.lista_sol_campo = []\n\n    let filtro = `$filter=alm_sociedad eq '${data.sociedad}' and alm_almacen eq '${data.almacen}' and alm_centro eq '${data.centro}' and tipo eq 'CAMPO' &$orderby=fecha_creacion desc`\n\n    let isTecnico = clientDataUser.info_user.rol === 'Técnico'\n    if(isTecnico){\n        let correo = clientDataUser.info_user.correo\n        //filtro += ` and correo_creacion eq ${correo}`\n        filtro = `$filter=alm_sociedad eq '${data.sociedad}' and alm_almacen eq '${data.almacen}' and alm_centro eq '${data.centro}' and tipo eq 'CAMPO' and correo_creacion eq '${correo}' &$orderby=fecha_creacion desc`\n    }\n\n    //+\"&$orderby=fecha_creacion desc\"\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'VerSolicitudesAbiertas', [], filtro).then(async (results) => {\n        if (results && results.length > 0) {\n            clientData.lista_sol_campo = results\n           \n        }else{\n            clientData.lista_campo = []\n        }\n\n        context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n            \"Properties\": {\n                \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Campo/Lista_Solicitudes_Campo.page\"\n            }\n        });\n    }).catch((error) => {\n        \n        alert(`Error ${error.message}`)\n    });\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function NavTo_RevisionSolicitudCampo(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitudes_Campo').getClientData();\n    clientData.lista_mat_solicitud_campo = []\n    clientData.id_de_solicitud = context.binding.id;\n    \n \n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n        \"Properties\": {\n            \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Campo/Revision_Solicitud_Campo.page\",\n            \"ModalPage\": true,\n            \"ModalPageFullscreen\": true\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function ProcesarSolicitud_Campo_SAP(context) {\n    //1. Enviar los componentes a la orden - hay que validar si ya hay creados materiales con las cantidades solicitadas usar esos campos y no hay que crearlos \n    //   - se debe guardar en los componentes de la solicitud las posiciones en la reserva de los materiales creados o escogidos\n    //2. liquidar los componentes de la orden - se debe guardar el numero de documento de material en cada componente y se debe mostrar en el detalle de los items de la solicitud\n    let clientData_user = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info_user = clientData_user.info_user;\n    let info_solicitud = context.binding;\n    let orden = info_solicitud.orden;\n    let id_solicitud = info_solicitud.id;\n    let reserva = info_solicitud.reserva;\n    let centro = info_solicitud.alm_centro;\n    let alm_desc = info_solicitud.alm_desc;\n    let pass = context.evaluateTargetPath(\"#Page:Autorizar_Solicitud_Campo/#Control:pass/#Value\");\n\n    let exitosos = [];\n    let errores = [];\n    let liquidar = [];\n    let update = [];\n    let filtro = `$expand=material,almacen&$filter=solicitud_id eq ${id_solicitud}`;\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ComponentesSolicitud', [], filtro).then((results) => {\n        if (!results || results.length === 0) {\n            alert(\"No se encontraron componentes para la solicitud\");\n            return;\n        }\n\n        // Crear las promesas para cada componente\n        const promesasAddMat = results.map((e) => {\n            //alert(e.material_material.replace(/^0+/, ''))\n            const data = {\n                ReservNo: reserva.replace(/^0+/, ''),\n                Material: e.material_material.replace(/^0+/, ''),\n                Plant: centro,\n                Activity: e.op_number,\n                GrRcpt: alm_desc,\n                RequirementQuantity: `${e.cantidad_aprobada}`,\n                //RequirementQuantityUnit: e.material.und,\n                RequirementQuantityUnit: \"PZA\"\n            };\n\n            //Consultar si el material ya existe en alguna posicion de la reserva y tiene disponibilidad para tomar las cantidades de ahí\n            let filtro2 = `$filter=reserva eq '${reserva}' and orden eq '${orden}' and material eq '${e.material_material}' and operacion eq '${e.op_number}'`;\n            return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'DetalleReserva', [], filtro2).then((results) => {\n                if (results && results.length > 0) {\n                    let disponibles = results.filter(obj => {\n                        return (obj.cant_solicitada - obj.cant_tomada) >= e.cantidad_aprobada;\n                    });\n\n                    liquidar.push({\n                        Material: e.material_material.replace(/^0+/, ''),\n                        MOVE_TYPE: \"261\",\n                        Plant: e.almacen.centro,\n                        StgeLoc: e.almacen.almacen,\n                        EntryQnt: `${e.cantidad_aprobada}`,\n                        EntryUom: \"PZA\",\n                        RES_ITEM: disponibles.getItem(0).posicion,\n                        RESERV_NO: reserva\n                    })\n                    update.push({\n                        idComponente: e.id,\n                        posicion: disponibles.getItem(0).posicion,\n                        doc_material: null\n                    })\n                } else {\n                    //alert(\"No hay materiales en la orden con esas especificaciones se va a crear los componentes en la reserva\");\n                    return context.executeAction({\n                        \"Name\": \"/appconsumos_qa_mb/Actions/Call_AddMaterialesRes.action\",\n                        \"Properties\": {\n                            \"OnFailure\": \"\",\n                            \"OnSuccess\": \"\",\n                            \"Target\": {\n                                \"Service\": \"/appconsumos_qa_mb/Services/backend_REST.service\",\n                                \"Path\": \"/AddMaterialRes\",\n                                \"RequestProperties\": {\n                                    \"Method\": \"POST\",\n                                    \"Body\": {\n                                        \"username\": info_user.sapUsr,\n                                        \"password\": \"Abaper072025\",\n                                        \"data\": data\n                                    }\n                                }\n                            }\n                        }\n                    }).then((res) => {\n\n                        let resjson = res.data\n                        let success = resjson.success\n                        let item = resjson.item\n                        if (success) {\n                            exitosos.push(`${e.material.material_desc}`);\n                            liquidar.push({\n                                Material: e.material_material.replace(/^0+/, ''),\n                                MOVE_TYPE: \"261\",\n                                Plant: e.almacen.centro,\n                                StgeLoc: e.almacen.almacen,\n                                EntryQnt: `${e.cantidad_aprobada}`,\n                                EntryUom: \"PZA\",\n                                RES_ITEM: item,\n                                RESERV_NO: reserva\n                            })\n                            update.push({\n                                idComponente: e.id,\n                                posicion: item,\n                                doc_material: null\n                            })\n                        } else {\n                            errores.push(`${e.material.material_desc}: ${resjson.message}`);\n                        }\n\n\n                    }).catch((error) => {\n                        alert(error)\n                        errores.push(`${e.material.material_desc}: ${error?.message || error}`);\n                    });\n\n                }\n\n            }).catch((error) => {\n                alert(`Error ${error.message}`);\n            });\n\n\n\n        });\n\n        // Ejecutar todas las promesas\n        return Promise.allSettled(promesasAddMat).then(() => {\n            let mensaje = \"\";\n\n            if (errores.length === 0) {\n                mensaje = 'Solicitud gestionada correctamente. Los materiales fueron añadidos a la reserva.';\n            } else if (exitosos.length === 0) {\n                mensaje = `Solicitud no gestionada. Fallaron todos los materiales:\\n\\n${errores.join('\\n')}`;\n            } else {\n                mensaje = `Solicitud parcialmente gestionada.\\n\\nErrores:\\n${errores.join('\\n')}`;\n            }\n\n            //alert(JSON.stringify(liquidar))\n            //alert(JSON.stringify(update))\n\n            // Segunda fase: liquidar\n            let exitososLiq = [];\n            let erroresLiq = [];\n            const promesasLiquidar = liquidar.map((item) => {\n                alert(JSON.stringify(item))\n                return context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/Call_LiquidarMaterialRes.action\",\n                    \"Properties\": {\n                        \"OnFailure\": \"\",\n                        \"OnSuccess\": \"\",\n                        \"Target\": {\n                            \"Service\": \"/appconsumos_qa_mb/Services/backend_REST.service\",\n                            \"Path\": \"/LiquidarMaterialRes\",\n                            \"RequestProperties\": {\n                                \"Method\": \"POST\",\n                                \"Body\": {\n                                    \"username\": info_user.sapUsr,\n                                    \"password\": \"Abaper072025\",\n                                    \"data\": item\n                                }\n                            }\n                        }\n                    }\n                }).then((res) => {\n\n                    alert(JSON.stringify(res))\n                    let resjson = res.data\n                    let success = resjson.success\n                    let doc_material = resjson.doc_material\n                    if (success) {\n                        exitososLiq.push(`${item.Material}`);\n                        /*update.push({\n                            idComponente: e.id,\n                            posicion: item,\n                            doc_material: null\n                        })*/\n                        update.forEach(u => {\n                            if (u.posicion === item.RES_ITEM) {\n                                u.doc_material = doc_material;\n                            }\n                        });\n                    } else {\n                        erroresLiq.push(`${item.Material}: ${resjson.message}`);\n                    }\n                }).catch((err) => {\n                    erroresLiq.push(`Error al liquidar material ${item.Material}: ${err.message || err}`);\n                });\n            });\n\n            return Promise.allSettled(promesasLiquidar).then(() => {\n                let mensajeFinal = '';\n                if (erroresLiq.length > 0) {\n                    mensajeFinal = `Liquidación completada con errores:\\n${erroresLiq.join('\\n')}`;\n                } else {\n                    mensajeFinal = 'Todos los materiales fueron liquidados correctamente en SAP.';\n                }\n\n                alert(JSON.stringify(update))\n                return context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Resultado de la operación\",\n                        \"Message\": mensaje\n                    }\n                }).then(() => {\n                    return context.executeAction({\n                        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                        \"Properties\": {\n\n                            \"Title\": \"Resultado de la liquidación\",\n                            \"Message\": mensajeFinal\n                        }\n                    }).then(() => {\n\n                    });\n                });\n            });\n        });\n\n\n\n\n    }).catch((error) => {\n        alert(`Error general: ${error.message || JSON.stringify(error)}`);\n    });\n\n\n\n}","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Query_Detalle_Componentes_Campo(context) {\n    let id_solicitud = context.binding.id\n\n     let filtro = `$expand=material,material/und,almacen&$filter=solicitud_id eq ${id_solicitud}`\n\n    return filtro\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function RechazarSolicitudCampo(context) {\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n        \"Properties\": {\n            \"Title\": \"Confirmación\",\n            \"Message\": \"¿Estás seguro de que deseas rechazar la solicitud completa? Todos los materiales serán rechazados.\",\n            \"OKCaption\": \"Aceptar\",\n            \"OnOK\": \"/appconsumos_qa_mb/Actions/oData/Update_SolicitudesApp_Rechazar_Campo.action\",\n            \"CancelCaption\": \"Cancelar\"\n        }\n    })\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Rechazar_Material_Revision_Campo(context) {\n\n    const pageProxy = context.getPageProxy();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitudes_Campo').getClientData();\n    //clientData.lista_mat_solicitud_ing\n\n    let material = context.evaluateTargetPath('#Page:Revision_Solicitud_Campo/#Control:materiales_solicitud/#Value');\n\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\");\n\n    let data = material[0].BindingObject\n\n    if (material.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes seleccionar un material para continuar`\n            }\n        });\n    }\n\n    const duplicado = clientData.lista_mat_solicitud_campo.filter(m => m.material.material === data.material.material && m.almacen_almacen === data.almacen_almacen).length > 0\n\n    if (duplicado) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `El material ya fue agregado anteriormente`\n            }\n        });\n    }\n\n    data.cant = 0\n    data.aprobado = 'Rechazado'\n    clientData.lista_mat_solicitud_campo.push(data);\n\n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Material Rechazado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    });\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Rechazar_Solicitud_Revision_Componentes_Campo(context) {\n    let id_solicitud = context.binding.id;\n    let filtro = `$expand=almacen&$filter=solicitud_id eq ${id_solicitud}`;\n    let materialesRechazados = [];\n    let exitosos = [];\n    let errores = [];\n\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ComponentesSolicitud', [], filtro).then(async (results) => {\n        if (results && results.length > 0) {\n            for (let i = 0; i < results.length; i++) {\n                let item = results.getItem(i);\n                materialesRechazados.push({\n                    descripcion: item.material_material,\n                    material: item.material_material,\n                    almacen_centro: item.almacen.centro,\n                    almacen_sociedad: item.almacen.sociedad,\n                    almacen_almacen: item.almacen.almacen,\n                    id_componente: item.id,\n                    readLink: item[\"@odata.readLink\"]\n                });\n            }\n        } else {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Error\",\n                    \"Message\": \"Error al tratar de traer los componentes de la solicitud (Rechazar componentes)\"\n                }\n            })\n        }\n\n        let promises = materialesRechazados.map(material => {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/oData/Update_ComponentesSolicitudApp.action\",\n                \"Properties\": {\n                    \"Target\": {\n                        \"ReadLink\": material.readLink\n                    },\n                    \"Properties\": {\n                        \"id\": material.id_componente,\n                        \"cantidad_aprobada\": 0,\n                        \"aprobado\": false,\n                        \"confirmacion_tec\": false\n                    }\n                }\n            }).then(() => {\n                exitosos.push(`${material.material} - ${material.descripcion}`);\n            }).catch((error) => {\n                alert(`Error updating material ${material.material}:`, error);\n                errores.push(`${material.material} - ${material.descripcion}`);\n            });\n        });\n\n        // Procesar los resultados\n        return Promise.allSettled(promises).then(() => {\n            let mensaje = '';\n\n            if (errores.length === 0) {\n                mensaje = 'Solicitud Rechazada correctamente. Todos los materiales de la solicitud fueron rechazados exitosamente.';\n            } else if (exitosos.length === 0) {\n                mensaje = `Solicitud rechazada. Falló el rechazo de todos los materiales:\\n${errores.join('\\n')}`;\n            } else {\n                mensaje = `Solicitud rechazada parcialmente. Algunos materiales fueron rechazados con éxito.\\n\\nErrores:\\n${errores.join('\\n')}`;\n            }\n\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Resultado\",\n                    \"Message\": mensaje\n                }\n            }).then(() => {\n                return context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/CloseModalPage_Complete.action\",\n                    \"NavigateBackToPage\": \"/appconsumos_qa_mb/Pages/Campo/Detalle_Solicitudes_Campo.page\"\n                });\n            });\n        });\n\n    }).catch((error) => {\n        alert(`Error ${error.message}`);\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Response_firmarPDF(context) {\n    let actionResult = context.getActionResult(\"Call_FirmarPDF2\")\n    alert(\"1\")\n    //let data = JSON.parse(actionResult.data)\n    //alert(JSON.stringify(data))\n    //alert(\"2\")\n    //alert(JSON.stringify(context.data))\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Select_almacen(context) {\n    let almacen = context.evaluateTargetPath('#Page:Filtro_Campo/#Control:almacen_campo/#Value');\n    const pageProxy = context.getPageProxy();\n    var btn_orden = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\").getControl(\"FormCellButton0\")\n    var btn_solicitud = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\").getControl(\"FormCellButton1\")\n    var btn_historico = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\").getControl(\"FormCellButton2\")\n\n    if (almacen.length > 0) {\n        btn_orden.setEnabled(true)\n        btn_solicitud.setEnabled(true)\n        btn_historico.setEnabled(true)\n    }else{\n        btn_orden.setEnabled(false)\n        btn_solicitud.setEnabled(false)\n        btn_historico.setEnabled(false)\n    }\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI}  context\n */\nexport default function SyncRevisarCampo(context) {\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/ClosePage.action\",\n        \"Properties\": {\n            \"NavigateBackToPage\": \"Lista_Solicitudes_Campo\"\n        }\n    }).then(() => {\n        return context.executeAction(\"/appconsumos_qa_mb/Actions/app_consumos_qa/Service/OnlySyncStartedMessage.action\")\n\n    });\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Target_Lista_Campo(context) {\n\n    let target = context.evaluateTargetPath(\"#Page:Filtro_Campo/#ClientData/#Property:lista_campo\");\n    let searchString = context.searchString;\n\n    if (searchString) {\n        let lowerSearch = searchString.toLowerCase();\n\n        let searchResult = target.filter(prod => {\n            return (prod.orden || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.orden_desc || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.centro_plan || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.grupo_plan || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.equipo || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.equipo_desc || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.reserva || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.sociedad || \"\").toLowerCase().includes(lowerSearch);\n        });\n\n        target = searchResult;\n    }\n\n    return target;\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Target_Lista_Historico_Campo(context) {\n    let target = context.evaluateTargetPath(\"#Page:Filtro_Campo/#ClientData/#Property:filtroHistoricoCampo\");\n    let search = context.searchString;\n    let queryBuilder = context.dataQueryBuilder();\n    \n \n    if (!search) {\n        return target;\n    } else {\n        search = search.toLowerCase();\n \n        // Crea condiciones para distintos campos\n        let filtrosSearch = [\n            `substringof(tolower('${search}'), tolower(orden_orden))`,\n            `substringof(tolower('${search}'), tolower(orden/orden_desc))`,\n            `substringof(tolower('${search}'), tolower(equipo_equipo))`,\n            `substringof(tolower('${search}'), tolower(almacen_almacen))`,\n            `substringof(tolower('${search}'), tolower(fecha_creacion))`,\n            `substringof(tolower('${search}'), tolower(reserva))`,\n            `substringof(tolower('${search}'), tolower(almacen_sociedad))`,\n            `substringof(tolower('${search}'), tolower(estado))`,\n            `substringof(tolower('${search}'), tolower(equipo/equipo_desc))`\n        ];\n \n        // Extrae el filtro original del target\n        let match = target.match(/\\$filter=(.*?)(&|$)/);\n        let filtroBase = match ? match[1] : \"\";\n \n        // Combina filtros\n        let filtroCombinado = filtroBase ? `(${filtroBase}) and (${filtrosSearch.join(' or ')})` : filtrosSearch.join(' or ');\n \n        // Aplica el filtro combinado\n        queryBuilder.filter(filtroCombinado);\n \n        // Preserva $expand y $orderby del target\n        let expandMatch = target.match(/\\$expand=([^&]*)/);\n        if (expandMatch) queryBuilder.expand(expandMatch[1]);\n \n        let orderMatch = target.match(/\\$orderby=([^&]*)/);\n        if (orderMatch) queryBuilder.orderBy(orderMatch[1]);\n \n        return queryBuilder;\n    }\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Target_Lista_Materiales(context) {\n\n    let target = context.evaluateTargetPath(\"#Page:Detalle_Orden_Campo/#ClientData/#Property:lista_materiales\");\n    let searchString = context.searchString;\n\n    if (searchString) {\n        let lowerSearch = searchString.toLowerCase();\n\n        let searchResult = target.filter(prod => {\n            return (prod.material || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.material_desc || \"\").toLowerCase().includes(lowerSearch);\n        });\n\n        target = searchResult;\n    }\n\n    return target;\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Target_Lista_Solicitudes_Campo(context) {\n    let target = context.evaluateTargetPath(\"#Page:Filtro_Campo/#ClientData/#Property:lista_sol_campo\");\n    let searchString = context.searchString;\n\n    if (searchString) {\n        let lowerSearch = searchString.toLowerCase();\n\n        let searchResult = target.filter(prod => {\n            return prod.orden.toLowerCase().includes(lowerSearch) ||\n                prod.or_desc.toLowerCase().includes(lowerSearch) ||\n                prod.or_centro_plan.toLowerCase().includes(lowerSearch) ||\n                prod.or_grupo_plan.toLowerCase().includes(lowerSearch) ||\n                prod.equipo_solicitud.toLowerCase().includes(lowerSearch) ||\n                prod.eq_desc_solicitud.toLowerCase().includes(lowerSearch) ||\n                prod.reserva.toLowerCase().includes(lowerSearch) ||\n                prod.alm_sociedad.toLowerCase().includes(lowerSearch) ||\n                prod.estado.toLowerCase().includes(lowerSearch);\n        });\n\n        target = searchResult;\n    }\n\n    return target;\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Target_Materiales_Revision_Campo(context) {\n    let target = context.evaluateTargetPath(\"#Page:Detalle_Solicitudes_Campo/#ClientData/#Property:lista_mat_solicitud_campo\");\n    let searchString = context.searchString;\n\n    if (searchString) {\n        let lowerSearch = searchString.toLowerCase();\n\n        let searchResult = target.filter(prod => {\n            return (prod.material_material || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.material.material_desc || \"\").toLowerCase().includes(lowerSearch);\n        });\n\n        target = searchResult;\n    }\n\n    return target;\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function ValidarAutorizar_Campo(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Autorizar_Solicitud_Campo').getClientData();\n    const signatureObject = context.evaluateTargetPath(\"#Page:Autorizar_Solicitud_Campo/#Control:FormCellInlineSignatureCapture0/#Value\");\n    const pass = context.evaluateTargetPath(\"#Page:Autorizar_Solicitud_Campo/#Control:pass/#Value\");\n    clientData.b64Data = \"\"\n\n    if (!pass || pass == '') {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Contraseña Requerida\",\n                \"Message\": \"Falta ingresar la contraseña. Verifícala y vuelve a intentarlo.\"\n            }\n        });\n    }\n\n    if (!signatureObject) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Pendiente por firmar\",\n                \"Message\": \"La firma es obligatoria para continuar. Asegúrate de presionar “Save/Guardar” para registrar correctamente tu firma.\"\n            }\n        });\n    }\n\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n        \"Properties\": {\n            \"Message\": \"¿Estás seguro de que deseas autorizar la solicitud? Al autorizarla, los componentes se enviarán a la reserva y se realizará la liquidación en SAP.\",\n            \"Title\": \"Autorizar Solicitud\",\n            \"OKCaption\": \"Aceptar\",\n            \"OnOK\": \"/appconsumos_qa_mb/Rules/Campo/ProcesarSolicitud_Campo_SAP.js\",\n            \"CancelCaption\": \"Cancelar\"\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Validate_Req_Create_Solicitud_Campo(context) {\n    let clientDataDetalle = context.evaluateTargetPathForAPI('#Page:Detalle_Orden_Campo').getClientData();\n    clientDataDetalle.lista_materiales\n    let ficha = context.evaluateTargetPath('#Page:Agregar_Solicitud_Campo/#Control:ficha/#Value');\n    if(ficha){\n        return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'EmpleadosApp', [], `$filter=ficha eq '${ficha}'`).then(async (results) => {\n            if (results && results.length > 0) {\n                \n                if(clientDataDetalle.lista_materiales && clientDataDetalle.lista_materiales.length > 0 ){\n                    return context.executeAction({\n                        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                        \"Properties\": {\n                            \"Title\": \"Confirmación\",\n                            \"Message\": `¿Estás seguro que quieres crear la solicitud?`,\n                            \"OKCaption\": \"Aceptar\",\n                            \"OnOK\": \"/appconsumos_qa_mb/Actions/oData/Create_Solicitud_Campo.action\",\n\t                        \"CancelCaption\": \"Cancelar\"\n                        }\n                    });\n                    //return context.executeAction(\"/appconsumos_qa_mb/Actions/oData/Create_Solicitud_Campo.action\");\n                }\n\n                return context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Alerta\",\n                        \"Message\": `Debes ingresar al menos un material a la solicitud para continuar`\n                    }\n                });\n            }\n\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Alerta\",\n                    \"Message\": `Número de ficha no encontrada. Debes ingresar un número de ficha válido para continuar`\n                }\n            });\n\n        }).catch((error) => {\n            \n            alert(`Error al encontrar la ficha ${error.message}`)\n        });\n\n    }\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n        \"Properties\": {\n            \"Title\": \"Alerta\",\n            \"Message\": `Debes ingresar el número de ficha para continuar`\n        }\n    });\n    \n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function get_Date(context) {\n    var object = context.binding\n    var fecha = object.fecha_creacion\n    let fechaFormateada = `Fe. Creación: $(D,${fecha.slice(0,4)}-${fecha.slice(4,6)}-${fecha.slice(6,8)})`;\n    return fechaFormateada\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function get_Date_ref(context) {\n    var object = context.binding\n    var fecha = object.fecha_referencia\n    let fechaFormateada = `Fe. Referencia: $(D,${fecha.slice(0,4)}-${fecha.slice(4,6)}-${fecha.slice(6,8)})`;\n    return fechaFormateada\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function get_List_Campo_Equipo(context) {\n    const pageProxy = context.getPageProxy();\n    let equipos = context.evaluateTargetPath('#Page:Lista_Ordenes_Campo/#Control:filtro_equipos/#Value');\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Campo').getClientData();\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n\n    if (equipos.length < 1) {\n        clientData.lista_campo = []\n        return list_component.redraw()\n    }\n\n    let filtro = '$filter='\n\n    equipos.forEach(e => {\n        filtro += `equipo eq '${e.BindingObject.equipo}' or `      \n    });\n\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'Ordenes', [], filtro.slice(0, -4)+\"&$orderby=fecha_creacion desc\").then(async (results) => {\n        if (results && results.length > 0) {\n            clientData.lista_campo = results\n            list_component.redraw()\n        }else{\n            clientData.lista_campo = []\n            list_component.redraw()\n        }\n    })\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function get_SolicitudesOrdenesAbiertas(context) {\n\n    let proxy = context.getPageProxy()\n    //alert(proxy.getCaption())\n\n    let data = context.evaluateTargetPath('#Page:Filtro_Campo/#Control:almacen_campo/#Value')[0].BindingObject\n    let clientDataUser = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Campo').getClientData();\n    clientData.centro = data.centro\n    clientData.almacen = data.almacen\n    clientData.sociedad = data.sociedad\n    clientData.lista_sol_campo = []\n\n    let filtro = `$filter=alm_sociedad eq '${data.sociedad}' and alm_almacen eq '${data.almacen}' and alm_centro eq '${data.centro}' and tipo eq 'CAMPO' &$orderby=fecha_creacion desc`\n\n    let isTecnico = clientDataUser.info_user.rol === 'Técnico'\n    if (isTecnico) {\n        let correo = clientDataUser.info_user.correo\n        //filtro += ` and correo_creacion eq ${correo}`\n        filtro = `$filter=alm_sociedad eq '${data.sociedad}' and alm_almacen eq '${data.almacen}' and alm_centro eq '${data.centro}' and tipo eq 'CAMPO' and correo_creacion eq '${correo}' &$orderby=fecha_creacion desc`\n    }\n\n    //+\"&$orderby=fecha_creacion desc\"\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'VerSolicitudesAbiertas', [], filtro).then(async (results) => {\n        if (results && results.length > 0) {\n            clientData.lista_sol_campo = results\n\n        } else {\n            clientData.lista_campo = []\n        }\n\n        proxy.redraw()\n\n    }).catch((error) => {\n\n        alert(`Error ${error.message}`)\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function get_tag_Material_Revisar(context) {\n\n    let mat_nuevo = context.binding.mat_nuevo\n    let material = context.binding.material_material\n\n    if(mat_nuevo){\n        return 'Nuevo'\n    }\n\n    if(material){\n        return 'Registrado'\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function isVisible_Btn_CrearSolicitudes(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData.info_user\n\n    return info.rol === 'Técnico';\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function onChange_MaterialesRevision(context) {\n    const pageProxy = context.getPageProxy();\n    var cantSolicitada = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell2\")\n    var btn_aprobar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\")\n\n    cantSolicitada.setVisible(false)\n    btn_aprobar.setVisible(true)\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function setVisible_CantAprobadaRevision(context) {\n    const pageProxy = context.getPageProxy();\n    var cantSolicitada = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell2\")\n    var label = cantSolicitada.getControl(\"FormCellLabel1\")\n    var cant_field = cantSolicitada.getControl(\"cantidad_revision\")\n    var btn_aprobar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\")\n\n    let material = context.evaluateTargetPath('#Page:Revision_Solicitud_Campo/#Control:materiales_solicitud/#Value');\n\n    if (material.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes seleccionar un material para continuar`\n            }\n        });\n    }\n   \n    cantSolicitada.setVisible(true);\n\n    setTimeout(() => {\n        var cantSol = material[0].BindingObject.cantidad_tomada;\n        label.setText(`Cantidad Solicitada: ${cantSol}`);\n        cant_field.setValue(cantSol);\n        btn_aprobar.setVisible(false);\n    }, 200); // 200ms suele ser suficiente\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function setVisible_ConModificaciones(context) {\n\n    const pageProxy = context.getPageProxy();\n    var observaciones = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\")\n    var operacion = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell3\")\n    var materiales = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell1\")\n    var btn_materiales = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\")\n    var botones = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable1\")\n    var lista = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n    //var mensajes = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell3\")\n\n    //mensajes.setVisible(false)\n    botones.setVisible(false)\n    operacion.setVisible(false)\n    //observaciones.setVisible(true)\n    materiales.setVisible(true)\n    btn_materiales.setVisible(true)\n    lista.setVisible(true)\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function get_Aprobado_Solicitud(context) {\n    try {\n        var object = context.binding\n        var aprobado = object.aprobado\n       \n        if(aprobado == \"Aprobado\"){\n            return \"Green\"\n        }\n        if(aprobado == \"Rechazado\"){\n            return \"Red\"\n        }\n    } catch (error) {\n        console.error(\"Ocurrió un error al obtener el valor:\", error);\n        alert(\"No se pudo obtener el valor: \" + error.message);\n    }\n    \n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Agregar_Material_Revision_Ingenio(context) {\n    const pageProxy = context.getPageProxy();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitudes_Ingenio').getClientData();\n    //clientData.lista_mat_solicitud_ing\n    let operacion = context.evaluateTargetPath('#Page:Revision_Solicitud_Ingenio/#Control:operacion_item/#Value')\n\n    let material = context.evaluateTargetPath('#Page:Revision_Solicitud_Ingenio/#Control:FormCellListPicker_Materiales/#Value');\n    let cant = context.evaluateTargetPath('#Page:Revision_Solicitud_Ingenio/#Control:FormCellSimpleProperty_Cantidad/#Value');\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\");\n\n    let data = material[0].BindingObject\n    let cantSolicitada = data.cantidad_tomada\n    let stock = data.stock_disponible\n\n    if (!cant || cant < 0) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Material no Agregado\",\n                \"Message\": `Debes ingresar una cantidad válida para continuar`\n            }\n        });\n    }\n\n    if (operacion.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Operación no seleccionada\",\n                \"Message\": \"Debes seleccionar una operación. Este campo es obligatorio.\",\n                \"OKCaption\": \"Aceptar\"\n            }\n        })\n    }\n    \n    if (cant > cantSolicitada) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Material no Agregado\",\n                \"Message\": `La cantidad a aprobar (${cant}) es mayor a la cantidad solicitada (${cantSolicitada}).`\n            }\n        });\n    }\n\n   const duplicado = clientData.lista_mat_solicitud_ing.filter(m => m.mat_nuevo === data.mat_nuevo && m.almacen_almacen === data.almacen_almacen).length > 0\n\n    if (duplicado) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Material no Agregado\",\n                \"Message\": `El material ya fue ingresado anteriormente`\n            }\n        });\n    }\n\n    data.cant = cant\n    data.aprobado = 'Aprobado'\n    data.operacion = operacion[0].ReturnValue\n    clientData.lista_mat_solicitud_ing.push(data);\n\n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Material Aprobado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    });\n    \n    \n\n    \n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Agregar_Materiales_Solicitud(context) {\n    const pageProxy = context.getPageProxy();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Orden_Ingenio').getClientData();\n\n    let material = context.evaluateTargetPath('#Page:Agregar_Solicitud_Ingenio/#Control:material/#Value');\n    let cant = context.evaluateTargetPath('#Page:Agregar_Solicitud_Ingenio/#Control:cantidad/#Value');\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n\n    if (material.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes seleccionar un material para continuar`\n            }\n        });\n    }\n\n    let data = material[0].BindingObject\n    let stock = data.stock_disponible\n\n    //TODO DESCOMENTAR CUANDO HAYA INVENTARIO\n    /*if(stock == 0){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `No hay stock disponible para este material`\n            }\n        });\n    }*/\n\n\n    if (!cant || cant < 0) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes ingresar una cantidad válida para continuar`\n            }\n        });\n    }\n\n    //TODO DESCOMENTAR CUANDO HAYA INVENTARIO\n    /*if(cant > stock){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes ingresar una cantidad menor para continuar. La cantidad disponible es de ${stock} und`\n            }\n        });\n    }*/\n\n\n\n    /*var nuevo = {\n        id: data.almacen.almacen_desc+\"-\"+data.material,\n        material: data.material,\n        material_desc: data.material_desc,\n        almacen: data.almacen.almacen , \n        almacen_desc: data.almacen.almacen_desc,\n        centro: data.centro,\n        cant : cant,\n        stock_disponible: data.stock_disponible,\n        stock_reservado: data.stock_reservado\n    }*/\n\n    const duplicado = clientData.lista_materiales.filter(m => m.Matnr === data.Matnr && m.Lgort === data.Lgort).length > 0\n\n    if (duplicado) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `El material ya fue ingresado anteriormente`\n            }\n        });\n    }\n\n    data.cant = cant\n    clientData.lista_materiales.push(data)\n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Nuevo material agregado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Borrar_Material_Lista(context) {\n    var data = context.binding\n    const pageProxy = context.getPageProxy();\n\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Orden_Ingenio').getClientData();\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n\n\n    const index = clientData.lista_materiales.findIndex(item => item.material === data.material && item.almacen.almacen === data.almacen.almacen);\n\n\n    if (index !== -1) {\n        clientData.lista_materiales.splice(index, 1); // Elimina el elemento en esa posición\n\n    }\n\n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Material '${data.material_desc}' del ${data.almacen.almacen_desc} eliminado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    })\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Borrar_Materiales_Revision_Ingenio(context) {\n    var data = context.binding\n    const pageProxy = context.getPageProxy();\n\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitudes_Ingenio').getClientData();\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n\n\n    const index = clientData.lista_mat_solicitud_ing.findIndex(item => item.mat_nuevo === data.mat_nuevo && item.almacen_almacen === data.almacen_almacen);\n\n\n    if (index !== -1) {\n        clientData.lista_mat_solicitud_ing.splice(index, 1); // Elimina el elemento en esa posición\n\n    }\n\n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Material '${data.mat_nuevo_desc}' del ${data.almacen_almacen} eliminado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    })\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function ConfirmarMateriales_Abast(context) {\n    const pageProxy = context.getPageProxy();\n    var table = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n    var items = table.getSelectedItems()\n    var cant = table.getSelectedItemsCount()\n\n    //alert(JSON.stringify(items[0]))\n    if(cant == 0){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"No hay materiales seleccionados\",\n                \"Message\": \"Selecciona al menos un material para poder confirmar.\",\n                \"OKCaption\": \"Aceptar\"\n            }\n        });\n    }\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n        \"Properties\": {\n            \"Message\": \"¿Estas seguro que deseas confirmar la recepción de los materiales seleccionados?\",\n            \"Title\": \"Confirmar recepción\",\n            \"OKCaption\": \"Aceptar\",\n            \"OnOK\": \"/appconsumos_qa_mb/Actions/oData/Update_SolicitudesApp_Recepcion_Abast.action\",\n            \"CancelCaption\": \"Cancelar\"\n        }\n    });\n\n\n    /*hacer el update de la tabla de items a confimrar la recepcion y el estado de la solicitud cambiarlo a tramitado*/\n\n    //items[0].binding\n    //alert(JSON.stringify(items))\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Confirmar_Revision_Ingenio(context) {\n    const pageProxy = context.getPageProxy();\n    var materiales = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell1\")\n    let operacion = context.evaluateTargetPath('#Page:Revision_Solicitud_Ingenio/#Control:operacion_item/#Value')\n\n    let id_solicitud = context.binding.id;\n    //let filtro = `$expand=almacen&$filter=solicitud_id eq ${id_solicitud}`;\n    let filtro = `$filter=solicitud_id eq ${id_solicitud}`;\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitudes_Ingenio').getClientData();\n    let listaDeAgregados = clientData.lista_mat_solicitud_ing;\n\n\n    if (materiales.getVisible()) {\n        //validar que si se hayan agregado todos los materiales a la solicitud\n        return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ComponentesSolicitud', [], filtro).then(async (results) => {\n            if (results && results.length > 0) {\n                let totalComponentes = results.length;\n\n                if (listaDeAgregados.length == totalComponentes) {\n                    // Validaciones sobre el campo 'aprobado'\n                    let todosRechazados = listaDeAgregados.every(m => m.aprobado === 'Rechazado');\n                    let alMenosUnoAprobado = listaDeAgregados.some(m => m.aprobado === 'Aprobado');\n\n                    if (todosRechazados) {\n                        return context.executeAction({\n                            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                            \"Properties\": {\n                                \"Title\": \"Solicitud No Aprobada\",\n                                \"Message\": \"No se puede aprobar la solicitud porque todos los materiales fueron rechazados.\"\n                            }\n                        });\n                    }\n\n                    if (alMenosUnoAprobado) {\n                        return context.executeAction({\n                            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                            \"Properties\": {\n                                \"Title\": \"Confirmación\",\n                                \"Message\": \"¿Estás seguro de que deseas confirmar la solicitud aprobada por ítems?\",\n                                \"OKCaption\": \"Aceptar\",\n                                \"OnOK\": \"/appconsumos_qa_mb/Actions/oData/Update_SolicitudesApp_Confirmar_Ingenio.action\",\n                                \"CancelCaption\": \"Cancelar\"\n                            }\n                        })\n                    }\n\n                } else if (listaDeAgregados.length < totalComponentes) {\n                    return context.executeAction({\n                        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                        \"Properties\": {\n                            \"Title\": \"Solicitud No Confirmada\",\n                            \"Message\": \"No puedes confirmar la solicitud hasta que se hayan agregado todos los materiales.\"\n                        }\n                    })\n                }\n\n\n            } else {\n                return context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Error\",\n                        \"Message\": \"Error al tratar de traer los componentes de la solicitud\"\n                    }\n                })\n            }\n\n\n        }).catch((error) => {\n            alert(`Error ${error.message}`);\n        });\n\n    } else {\n        if (operacion.length < 1) {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Operación no seleccionada\",\n                    \"Message\": \"Debes seleccionar una operación antes de confirmar. Este campo es obligatorio.\",\n                    \"OKCaption\": \"Aceptar\"\n                }\n            })\n        }\n\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Confirmación\",\n                \"Message\": \"¿Estás seguro de que deseas confirmar la solicitud con las cantidades originales solicitadas y la operación seleccionada?\",\n                \"OKCaption\": \"Aceptar\",\n                \"OnOK\": \"/appconsumos_qa_mb/Actions/oData/Update_SolicitudesApp_Confirmar_Ingenio.action\",\n                \"CancelCaption\": \"Cancelar\"\n            }\n        })\n\n    }\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Confirmar_Revision_Original_Ingenio(context) {\n    let id_solicitud = context.binding.id;\n    let filtro = `$expand=almacen&$filter=solicitud_id eq ${id_solicitud}`;\n    let materialesAprobados = [];\n    let exitosos = [];\n    let errores = [];\n\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ComponentesSolicitud', [], filtro).then(async (results) => {\n        if (results && results.length > 0) {\n            for (let i = 0; i < results.length; i++) {\n                let item = results.getItem(i);\n                materialesAprobados.push({\n                    material: item.mat_nuevo,\n                    cantidad_aprobada : item.cantidad_tomada,\n                    id_componente: item.id,\n                    readLink: item[\"@odata.readLink\"]\n                });\n            }\n        } else {\n            alert(\"No hay datos\");\n            return;\n        }\n\n        let promises = materialesAprobados.map(material => {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/oData/Update_ComponentesSolicitudApp.action\",\n                \"Properties\": {\n                    \"Target\": {\n                        \"ReadLink\": material.readLink\n                    },\n                    \"Properties\": {\n                        \"id\": material.id_componente,\n                        \"cantidad_aprobada\": material.cantidad_aprobada,\n                        \"aprobado\": true\n                    }\n                }\n            }).then(() => {\n                exitosos.push(`${material.material} - ${material.descripcion}`);\n            }).catch((error) => {\n                alert(`Error updating material ${material.material}:`, error);\n                errores.push(`${material.material} - ${material.descripcion}`);\n            });\n        });\n\n        // Procesar los resultados\n        return Promise.allSettled(promises).then(() => {\n            let mensaje = '';\n\n            if (errores.length === 0) {\n                mensaje = 'Solicitud Rechazada correctamente. Todos los materiales de la solicitud fueron rechazados exitosamente.';\n            } else if (exitosos.length === 0) {\n                mensaje = `Solicitud rechazada. Falló el rechazo de todos los materiales:\\n${errores.join('\\n')}`;\n            } else {\n                mensaje = `Solicitud rechazada parcialmente. Algunos materiales fueron rechazados con éxito.\\n\\nErrores:\\n${errores.join('\\n')}`;\n            }\n\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Resultado\",\n                    \"Message\": mensaje\n                }\n            }).then(() => {\n                return context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/CloseModalPage_Complete.action\",\n                    \"NavigateBackToPage\": \"/appconsumos_qa_mb/Pages/Ingenio/Detalle_Solicitudes_Ingenio.page\"\n                });\n            });\n        });\n\n    }).catch((error) => {\n        alert(`Error ${error.message}`);\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default async function Confirmar_Solicitud_Revision_Items_Ingenio(context) {\n    const pageProxy = context.getPageProxy();\n    var materiales = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell1\")\n    let materialesRechazados = [];\n    let materialesAprobados = [];\n    let exitosos = [];\n    let errores = [];\n    let id_solicitud = context.binding.id;\n    let operacion = context.evaluateTargetPath('#Page:Revision_Solicitud_Ingenio/#Control:operacion/#Value')\n \n\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitudes_Ingenio').getClientData();\n    let filtro = `$expand=material,almacen&$filter=solicitud_id eq ${id_solicitud}`;\n\n    //let listaDeAgregados = clientData.lista_mat_solicitud_ing;\n\n    if (materiales.getVisible()) {\n        //cuando los materiales fueron aprobados por item\n\n        let listaDeAgregados = clientData.lista_mat_solicitud_ing;\n\n        listaDeAgregados.forEach(item => {\n            const materialData = {\n                descripcion: item.mat_nuevo_desc,\n                material: item.mat_nuevo,\n                almacen_centro: item.almacen.centro,\n                almacen_sociedad: item.almacen.sociedad,\n                almacen_almacen: item.almacen_almacen,\n                id_componente: item.id,\n                readLink: item[\"@odata.readLink\"]\n            };\n\n            if (item.aprobado === 'Aprobado') {\n                materialData.cantidad_aprobada = item.cant;\n                materialData.operacion = item.operacion;\n                materialesAprobados.push(materialData);\n            } else {\n               \n                //rechazado\n                materialData.cantidad_aprobada = 0;\n                materialesRechazados.push(materialData);\n            }\n        });\n\n    } else {\n        //cuando se aprueban todos los materiales por defecto\n        await context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ComponentesSolicitud', [], filtro).then(async (results) => {\n            if (results && results.length > 0) {\n                for (let i = 0; i < results.length; i++) {\n                    let item = results.getItem(i);\n                    materialesAprobados.push({\n                        descripcion: item.mat_nuevo_desc,\n                        material: item.mat_nuevo,\n                        almacen_centro: item.almacen.centro,\n                        almacen_sociedad: item.almacen.sociedad,\n                        almacen_almacen: item.almacen.almacen,\n                        id_componente: item.id,\n                        operacion: operacion[0].ReturnValue,\n                        cantidad_aprobada: item.cantidad_tomada,\n                        readLink: item[\"@odata.readLink\"]\n                    });\n                }\n            } else {\n                return context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Error\",\n                        \"Message\": \"Error al tratar de traer los componentes de la solicitud (Aprobar componentes)\"\n                    }\n                })\n            }\n        }).catch((error) => {\n            alert(`Error ${error.message}`);\n        });\n\n\n    }\n\n    let promisesAprobados = materialesAprobados.map(material => {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/oData/Update_ComponentesSolicitudApp.action\",\n            \"Properties\": {\n                \"Target\": {\n                    \"ReadLink\": material.readLink\n                },\n                \"Properties\": {\n                    \"id\": material.id_componente,\n                    \"cantidad_aprobada\": material.cantidad_aprobada,\n                    \"aprobado\": true,\n                    \"op_number\" : material.operacion\n                }\n            }\n        }).then(() => {\n            exitosos.push(`${material.material} - ${material.descripcion}`);\n        }).catch((error) => {\n            alert(`Error actualizando material ${material.material}:`, error);\n            errores.push(`${material.material} - ${material.descripcion}`);\n        });\n    });\n\n    let promisesRechazados = materialesRechazados.map(material => {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/oData/Update_ComponentesSolicitudApp.action\",\n            \"Properties\": {\n                \"Target\": {\n                    \"ReadLink\": material.readLink\n                },\n                \"Properties\": {\n                    \"id\": material.id_componente,\n                    \"cantidad_aprobada\": 0,\n                    \"aprobado\": false,\n                    \"confirmacion_tec\": false,\n                    \"op_number\" : null\n                }\n            }\n        }).then(() => {\n            exitosos.push(`${material.material} - ${material.descripcion}`);\n        }).catch((error) => {\n            alert(`Error actualizando material ${material.material}:`, error);\n            errores.push(`${material.material} - ${material.descripcion}`);\n        });\n    });\n\n    // Procesar los resultados\n    return Promise.allSettled([...promisesAprobados, ...promisesRechazados]).then(() => {\n        let mensaje = '';\n\n        if (errores.length === 0) {\n            mensaje = 'Solicitud gestionada correctamente. Todos los materiales de la solicitud fueron gestionados exitosamente.';\n        } else if (exitosos.length === 0) {\n            mensaje = `Solicitud no gestionada. Falló la gestión de todos los materiales:\\n${errores.join('\\n')}`;\n        } else {\n            mensaje = `Solicitud no gestionada parcialmente. Algunos materiales fueron gestionados con éxito.\\n\\nErrores:\\n${errores.join('\\n')}`;\n        }\n\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Resultado\",\n                \"Message\": mensaje\n            }\n        }).then(() => {\n        \n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/CloseModalPage_Complete.action\",\n                \"NavigateBackToPage\": \"/appconsumos_qa_mb/Pages/Ingenio/Detalle_Solicitudes_Ingenio.page\"\n            })\n        });\n    });\n}\n","import guid from '../guid'\n/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Create_Componentes_Solicitud_Ingenio(context) {\n\n    let actionResult = context.getActionResult(\"Create_Solicitud_Ingenio\")\n    let data = JSON.parse(actionResult.data)\n    let idSolicitud = data.id\n\n \n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Orden_Ingenio').getClientData();\n    let lista_materiales = clientData.lista_materiales;\n\n    // Obtener datos del almacén desde ClientData\n    let dataAlmacen = context.evaluateTargetPath('#Page:Filtro_Ingenio/#Control:FormCellListPicker_Almacen_O/#Value')[0].BindingObject \n \n    let exitosos = [];\n    let errores = [];\n\n    // Create de la solicitud\n        let promises = lista_materiales.map(material => {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/oData/Create_ComponentesSolicitudApp.action\",\n                \"Properties\": {\n                    \"Properties\": {\n                        \"id\": guid(context),\n                        \"mat_nuevo\": material.Matnr,\n                        \"mat_nuevo_desc\": material.Txtmd,\n                        \"mat_nuevo_und\": material.Meins,\n                        \"almacen_sociedad\": dataAlmacen.sociedad,\n                        \"almacen_almacen\": material.Lgort,\n                        \"almacen_centro\": material.Werks,\n                        \"solicitud_id\": idSolicitud,\n                        \"cantidad_tomada\": material.cant\n                    }\n                }\n            }).then(() => {\n                exitosos.push(`${material.Lgort} - ${material.Txtmd}`);\n            }).catch(() => {\n                errores.push(`${material.Lgort} - ${material.Txtmd}`);\n            });\n        });\n\n\n        // Procesar los resultados\n    return Promise.allSettled(promises).then(() => {\n        let mensaje = '';\n \n        if (errores.length === 0) {\n            mensaje = 'Solicitud creada. Todos los materiales fueron agregados exitosamente a la solicitud.';\n        } else if (exitosos.length === 0) {\n            mensaje = `Solicitud creada. Falló la creación de todos los materiales:\\n${errores.join('\\n')}`;\n        } else {\n            mensaje = `Solicitud creada. Algunos materiales fueron agregados con éxito.\\n\\nErrores:\\n${errores.join('\\n')}`;\n        }\n \n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Resultado\",\n                \"Message\": mensaje\n            }\n        }).then(() => {\n            // Finalmente cerrar el modal\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/CloseModalPage_Complete.action\",\n                \"NavigateBackToPage\": \"/appconsumos_qa_mb/Pages/Ingenio/Detalle_Orden_Ingenio.page\"\n            });\n        });\n    });\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Filter_Materiales_Almacenes_Ingenio(context) {\n    let clientDataFiltro = context.evaluateTargetPathForAPI('#Page:Filtro_Ingenio').getClientData();\n \n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'AlmacenesApp', [], `$filter=tipo eq 'INGENIO'`).then(async (results) => {\n       \n        if (results && results.length > 0) {\n            let filtro = `$filter=Werks eq '${clientDataFiltro.centro_ingenio}' and Spras eq 'ES' and contains(Txtmd, 'BORRADO') eq false and contains(Txtmd, 'BORRAR') eq false and contains(Txtmd, 'BORRAD_') eq false and (`\n \n            results.forEach(e => {\n                filtro += `Lgort eq '${e.almacen}' or `      \n            });\n \n            clientDataFiltro.filtroMaterial = filtro.slice(0, -4)+\")&$orderby=Matnr\"\n            //alert(clientDataFiltro.filtroMaterial)\n            //el centro esta indefinido\n            return clientDataFiltro.filtroMaterial;\n            \n \n        }\n        return null;\n    }).catch((error) => {\n       \n        alert(`Error al obtener los almacenes ${error.message}`)\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function NavTo_Agregar_Solicitud_Ingenio(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Orden_Ingenio').getClientData();\n    clientData.lista_materiales = []\n    \n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n        \"Properties\": {\n            \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Ingenio/Agregar_Solicitud_Ingenio.page\",\n            \"ModalPage\": true,\n            \"ModalPageFullscreen\": true\n        }\n    });\n\n}\n","/**\n * Describe this function...\n * @param {xontext} clientAPI\n */\nexport default function NavTo_Ingenio(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData.info_user\n\n    if(!clientData.info_user){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n            \"Properties\": {\n                \"Message\": `Sincronizando datos, por favor espera un momento...`,\n                \"Duration\": 1\n            }\n        });\n    }\n\n    if (info.estado == 'Activo') {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n            \"Properties\": {\n                \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Ingenio/Filtro_Ingenio.page\"\n            }\n        });\n    }\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n        \"Properties\": {\n            \"Title\": \"Alerta\",\n            \"Message\": `No tienes permisos para ingresar a este módulo`\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function NavTo_List_Historico_Sol_Ingenio(context) {\n    let data = context.evaluateTargetPath('#Page:Filtro_Ingenio/#Control:FormCellListPicker_Almacen_O/#Value')[0].BindingObject\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Ingenio').getClientData();\n    clientData.centroH = data.centro\n    clientData.almacenH = data.almacen\n    clientData.sociedadH = data.sociedad\n    clientData.lista_sol_historico_ing = []\n    \n    let filtro = `$expand=almacen,operario,aprobador,autorizador,equipo,orden&$filter=almacen_sociedad eq '${data.sociedad}' and almacen_almacen eq '${data.almacen}' and almacen_centro eq '${data.centro}' and tipo eq 'INGENIO' &$orderby=fecha_creacion desc`\n    clientData.filtroHistorico = filtro;\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n        \"Properties\": {\n            \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Ingenio/Lista_Historico_Ingenio.page\"\n        }\n    });\n\n    \n}\n","/**\n * Describe this function...\n * @param {context} clientAPI\n */\nexport default function NavTo_List_Ingenio(context) {\n    let centro = context.evaluateTargetPath('#Page:Filtro_Ingenio/#Control:FormCellListPicker_Almacen_O/#Value')[0].BindingObject.centro\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Ingenio').getClientData();\n    clientData.centro_ingenio = centro\n    clientData.lista_ingenio = []\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n        \"Properties\": {\n            \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Ingenio/Lista_Ordenes_Ingenio.page\"\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function NavTo_List_Sol_Ingenio(context) {\n    let data = context.evaluateTargetPath('#Page:Filtro_Ingenio/#Control:FormCellListPicker_Almacen_O/#Value')[0].BindingObject\n    let clientDataUser = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    \n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Ingenio').getClientData();\n    clientData.centro = data.centro\n    clientData.almacen = data.almacen\n    clientData.sociedad = data.sociedad\n    clientData.lista_sol_ingenio = []\n\n    let filtro = `$filter=alm_sociedad eq '${data.sociedad}' and alm_almacen eq '${data.almacen}' and alm_centro eq '${data.centro}' and tipo eq 'INGENIO' &$orderby=fecha_creacion desc`\n\n    let isTecnico = clientDataUser.info_user.rol === 'Técnico'\n    if(isTecnico){\n        let correo = clientDataUser.info_user.correo\n        //filtro += ` and correo_creacion eq ${correo}`\n        filtro = `$filter=alm_sociedad eq '${data.sociedad}' and alm_almacen eq '${data.almacen}' and alm_centro eq '${data.centro}' and tipo eq 'INGENIO' and correo_creacion eq '${correo}' &$orderby=fecha_creacion desc`\n    }\n\n    //+\"&$orderby=fecha_creacion desc\"\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'VerSolicitudesAbiertas', [], filtro).then(async (results) => {\n        if (results && results.length > 0) {\n            clientData.lista_sol_ingenio = results\n           \n        }else{\n            clientData.lista_sol_ingenio = []\n        }\n\n        context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n            \"Properties\": {\n                \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Ingenio/Lista_Solicitudes_Ingenio.page\"\n            }\n        });\n    }).catch((error) => {\n        \n        alert(`Error ${error.message}`)\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function NavTo_Revision_Solicitud_Ingenio(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitudes_Ingenio').getClientData();\n    clientData.lista_mat_solicitud_ing = []\n    clientData.id_de_solicitud = context.binding.id;\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n        \"Properties\": {\n            \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Ingenio/Revision_Solicitud_Ingenio.page\",\n            \"ModalPage\": true,\n            \"ModalPageFullscreen\": true\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Query_Detalle_Componentes_Ingenio(context) {\n    let id_solicitud = context.binding.id\n\n    let filtro = `$expand=almacen,material&$filter=solicitud_id eq ${id_solicitud}`\n\n    return filtro\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Query_Materiales_Solicitud_Ingenio(context) {\n    let id_solicitud = context.binding.id\n\n    let filtro = `$expand=material,almacen&$filter=solicitud_id eq ${id_solicitud}`\n\n    return filtro\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Rechazar_Material_Revision_Ingenio(context) {\n    const pageProxy = context.getPageProxy();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitudes_Ingenio').getClientData();\n    //clientData.lista_mat_solicitud_ing\n\n    let material = context.evaluateTargetPath('#Page:Revision_Solicitud_Ingenio/#Control:FormCellListPicker_Materiales/#Value');\n\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\");\n\n    let data = material[0].BindingObject\n\n    if (material.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Material no Agregado\",\n                \"Message\": `Debes seleccionar un material para continuar`\n            }\n        });\n    }\n\n    const duplicado = clientData.lista_mat_solicitud_ing.filter(m => m.mat_nuevo === data.mat_nuevo && m.almacen_almacen === data.almacen_almacen).length > 0\n\n    if (duplicado) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Material no Agregado\",\n                \"Message\": `El material ya fue agregado anteriormente`\n            }\n        });\n    }\n\n    data.cant = 0\n    data.aprobado = 'Rechazado'\n    clientData.lista_mat_solicitud_ing.push(data);\n\n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Material Rechazado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    });\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Rechazar_Solicitud_Revision_Ingenio(context) {\n    let id_solicitud = context.binding.id;\n    let filtro = `$expand=almacen&$filter=solicitud_id eq ${id_solicitud}`;\n    let materialesRechazados = [];\n    let exitosos = [];\n    let errores = [];\n\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ComponentesSolicitud', [], filtro).then(async (results) => {\n        if (results && results.length > 0) {\n            for (let i = 0; i < results.length; i++) {\n                let item = results.getItem(i);\n                materialesRechazados.push({\n                    descripcion: item.mat_nuevo_desc,\n                    material: item.mat_nuevo,\n                    almacen_centro: item.almacen.centro,\n                    almacen_sociedad: item.almacen.sociedad,\n                    almacen_almacen: item.almacen.almacen,\n                    id_componente: item.id,\n                    readLink: item[\"@odata.readLink\"]\n                });\n            }\n        } else {\n            alert(\"No hay datos\");\n            return;\n        }\n\n        let promises = materialesRechazados.map(material => {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/oData/Update_ComponentesSolicitudApp.action\",\n                \"Properties\": {\n                    \"Target\": {\n                        \"ReadLink\": material.readLink\n                    },\n                    \"Properties\": {\n                        \"id\": material.id_componente,\n                        \"cantidad_aprobada\": 0,\n                        \"aprobado\": false,\n                        \"confirmacion_tec\": false\n                    }\n                }\n            }).then(() => {\n                exitosos.push(`${material.material} - ${material.descripcion}`);\n            }).catch((error) => {\n                alert(`Error updating material ${material.material}:`, error);\n                errores.push(`${material.material} - ${material.descripcion}`);\n            });\n        });\n\n        // Procesar los resultados\n        return Promise.allSettled(promises).then(() => {\n            let mensaje = '';\n\n            if (errores.length === 0) {\n                mensaje = 'Solicitud Rechazada correctamente. Todos los materiales de la solicitud fueron rechazados exitosamente.';\n            } else if (exitosos.length === 0) {\n                mensaje = `Solicitud rechazada. Falló el rechazo de todos los materiales:\\n${errores.join('\\n')}`;\n            } else {\n                mensaje = `Solicitud rechazada parcialmente. Algunos materiales fueron rechazados con éxito.\\n\\nErrores:\\n${errores.join('\\n')}`;\n            }\n\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Resultado\",\n                    \"Message\": mensaje\n                }\n            }).then(() => {\n                return context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/CloseModalPage_Complete.action\",\n                    \"NavigateBackToPage\": \"/appconsumos_qa_mb/Pages/Ingenio/Detalle_Solicitudes_Ingenio.page\"\n                });\n            });\n        });\n\n    }).catch((error) => {\n        alert(`Error ${error.message}`);\n    });\n}","/**\n * Describe this function...\n * @param {context} clientAPI\n */\nexport default function Select_Almacen_Ingenio(context) {\n    let almacen_ingenio = context.evaluateTargetPath('#Page:Filtro_Ingenio/#Control:FormCellListPicker_Almacen_O/#Value');\n    const pageProxy = context.getPageProxy();\n    var btn_orden = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\").getControl(\"FormCellButton_Buscar\")\n    var btn_solicitud = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\").getControl(\"FormCellButton1\")\n    var btn_historico = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\").getControl(\"FormCellButton2\")\n    \n    if (almacen_ingenio.length > 0) {\n        btn_orden.setEnabled(true)\n        btn_solicitud.setEnabled(true)\n        btn_historico.setEnabled(true)\n    }else{\n        btn_orden.setEnabled(false)\n        btn_solicitud.setEnabled(false)\n        btn_historico.setEnabled(false)\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function SyncRevisarIngenio(context) {\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/ClosePage.action\",\n        \"Properties\": {\n            \"NavigateBackToPage\": \"Lista_Solicitudes_Ingenio\"\n        }\n    }).then(() => {\n        return context.executeAction(\"/appconsumos_qa_mb/Actions/app_consumos_qa/Service/OnlySyncStartedMessage.action\")\n\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Target_Lista_Historico_Ingenio(context) {\n    let target = context.evaluateTargetPath(\"#Page:Filtro_Ingenio/#ClientData/#Property:filtroHistorico\");\n    let search = context.searchString;\n    let queryBuilder = context.dataQueryBuilder();\n    \n \n    if (!search) {\n        return target;\n    } else {\n        search = search.toLowerCase();\n \n        // Crea condiciones para distintos campos\n        let filtrosSearch = [\n            `substringof(tolower('${search}'), tolower(orden_orden))`,\n            `substringof(tolower('${search}'), tolower(orden/orden_desc))`,\n            `substringof(tolower('${search}'), tolower(equipo_equipo))`,\n            `substringof(tolower('${search}'), tolower(almacen_almacen))`,\n            `substringof(tolower('${search}'), tolower(fecha_creacion))`,\n            `substringof(tolower('${search}'), tolower(reserva))`,\n            `substringof(tolower('${search}'), tolower(almacen_sociedad))`,\n            `substringof(tolower('${search}'), tolower(estado))`,\n            `substringof(tolower('${search}'), tolower(equipo/equipo_desc))`\n        ];\n \n        // Extrae el filtro original del target\n        let match = target.match(/\\$filter=(.*?)(&|$)/);\n        let filtroBase = match ? match[1] : \"\";\n \n        // Combina filtros\n        let filtroCombinado = filtroBase ? `(${filtroBase}) and (${filtrosSearch.join(' or ')})` : filtrosSearch.join(' or ');\n \n        // Aplica el filtro combinado\n        queryBuilder.filter(filtroCombinado);\n \n        // Preserva $expand y $orderby del target\n        let expandMatch = target.match(/\\$expand=([^&]*)/);\n        if (expandMatch) queryBuilder.expand(expandMatch[1]);\n \n        let orderMatch = target.match(/\\$orderby=([^&]*)/);\n        if (orderMatch) queryBuilder.orderBy(orderMatch[1]);\n \n        return queryBuilder;\n    }\n\n    \n    /*\n    \n    let searchString = context.searchString;\n\n    if (searchString) {\n        let lowerSearch = searchString.toLowerCase();\n\n        let searchResult = target.filter(prod => {\n            return (prod.orden.orden || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.orden.orden_desc || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.orden.centro_plan || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.orden.grupo_plan || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.equipo_equipo || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.equipo.equipo_desc || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.reserva || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.almacen_sociedad || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.estado || \"\").toLowerCase().includes(lowerSearch);\n        });\n\n        target = searchResult;\n    }\n\n    return target;\n    */\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Target_Lista_Ingenio(context) {\n    let target = context.evaluateTargetPath(\"#Page:Filtro_Ingenio/#ClientData/#Property:lista_ingenio\");\n    let searchString = context.searchString;\n\n    if (searchString) {\n        let lowerSearch = searchString.toLowerCase();\n\n        let searchResult = target.filter(prod => {\n            return (prod.orden || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.orden_desc || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.centro_plan || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.grupo_plan || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.equipo || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.equipo_desc || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.reserva || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.sociedad || \"\").toLowerCase().includes(lowerSearch);\n        });\n\n        target = searchResult;\n    }\n\n    return target;\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Target_Lista_Materiales(context) {\n    let target = context.evaluateTargetPath(\"#Page:Detalle_Orden_Ingenio/#ClientData/#Property:lista_materiales\");\n    let searchString = context.searchString;\n\n    if (searchString) {\n        let lowerSearch = searchString.toLowerCase();\n\n        let searchResult = target.filter(prod => {\n            return (prod.Matnr || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.Txtmd || \"\").toLowerCase().includes(lowerSearch);\n        });\n\n        target = searchResult;\n    }\n\n    return target;\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Target_Lista_Solicitudes_Ingenio(context) {\n    let target = context.evaluateTargetPath(\"#Page:Filtro_Ingenio/#ClientData/#Property:lista_sol_ingenio\");\n    let searchString = context.searchString;\n\n    if (searchString) {\n        let lowerSearch = searchString.toLowerCase();\n\n        let searchResult = target.filter(prod => {\n            return (prod.orden || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.or_desc || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.or_centro_plan || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.or_grupo_plan || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.equipo_solicitud || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.eq_desc_solicitud || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.reserva || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.alm_sociedad || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.estado || \"\").toLowerCase().includes(lowerSearch);\n        });\n\n        target = searchResult;\n    }\n\n    return target;\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Target_Materiales_Revision_Ingenio(context) {\n    let target = context.evaluateTargetPath(\"#Page:Detalle_Solicitudes_Ingenio/#ClientData/#Property:lista_mat_solicitud_ing\");\n    let searchString = context.searchString;\n\n    if (searchString) {\n        let lowerSearch = searchString.toLowerCase();\n\n        let searchResult = target.filter(prod => {\n            return (prod.mat_nuevo || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.mat_nuevo_desc || \"\").toLowerCase().includes(lowerSearch);\n        });\n\n        target = searchResult;\n    }\n\n    return target;\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Validate_Req_Create_Solicitud_Ingenio(context) {\n    let clientDataDetalle = context.evaluateTargetPathForAPI('#Page:Detalle_Orden_Ingenio').getClientData();\n    clientDataDetalle.lista_materiales\n    let ficha = context.evaluateTargetPath('#Page:Agregar_Solicitud_Ingenio/#Control:ficha/#Value');\n    if(ficha){\n        return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'EmpleadosApp', [], `$filter=ficha eq '${ficha}'`).then(async (results) => {\n            if (results && results.length > 0) {\n                \n                if(clientDataDetalle.lista_materiales && clientDataDetalle.lista_materiales.length > 0 ){\n                    return context.executeAction({\n                        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                        \"Properties\": {\n                            \"Title\": \"Confirmación\",\n                            \"Message\": `¿Estás seguro que quieres crear la solicitud?`,\n                            \"OKCaption\": \"Aceptar\",\n                            \"OnOK\": \"/appconsumos_qa_mb/Actions/oData/Create_Solicitud_Ingenio.action\",\n\t                        \"CancelCaption\": \"Cancelar\"\n                        }\n                    });\n                    //return context.executeAction(\"/appconsumos_qa_mb/Actions/oData/Create_Solicitud_Ingenio.action\");\n                }\n\n                return context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Alerta\",\n                        \"Message\": `Debes ingresar al menos un material a la solicitud para continuar`\n                    }\n                });\n            }\n\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Alerta\",\n                    \"Message\": `Número de ficha no encontrada. Debes ingresar un número de ficha válido para continuar`\n                }\n            });\n\n        }).catch((error) => {\n            \n            alert(`Error al encontrar la ficha ${error.message}`)\n        });\n\n    }\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n        \"Properties\": {\n            \"Title\": \"Alerta\",\n            \"Message\": `Debes ingresar el número de ficha para continuar`\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function get_Date_creacion(context) {\n    var object = context.binding\n    var fecha = object.fecha_creacion\n    let fechaFormateada = `Fe. Creación: $(D,${fecha.slice(0,4)}-${fecha.slice(4,6)}-${fecha.slice(6,8)})`;\n    return fechaFormateada\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function get_Date_ref(context) {\n    var object = context.binding\n    var fecha = object.fecha_referencia\n    let fechaFormateada = `Fe. Referencia: $(D,${fecha.slice(0,4)}-${fecha.slice(4,6)}-${fecha.slice(6,8)})`;\n    return fechaFormateada\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function get_List_Ingenio_Equipo(context) {\n    const pageProxy = context.getPageProxy();\n    let equipos = context.evaluateTargetPath('#Page:Lista_Ordenes_Ingenio/#Control:FormCellListPicker_Equipos_Ord/#Value');\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Ingenio').getClientData();\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n\n    if (equipos.length < 1) {\n        clientData.lista_ingenio = []\n        return list_component.redraw()\n    }\n\n    let filtro = '$filter='\n\n    equipos.forEach(e => {\n        filtro += `equipo eq '${e.BindingObject.equipo}' or `      \n    });\n\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'Ordenes', [], filtro.slice(0, -4)+\"&$orderby=fecha_creacion desc\").then(async (results) => {\n        if (results && results.length > 0) {\n            clientData.lista_ingenio = results\n            list_component.redraw()\n        }else{\n            clientData.lista_ingenio = []\n            list_component.redraw()\n        }\n    })\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function get_SolicitudesOrdenesAbiertasIngenio(context) {\n    let proxy = context.getPageProxy()\n    //alert(proxy.getCaption())\n \n    let data = context.evaluateTargetPath('#Page:Filtro_Ingenio/#Control:FormCellListPicker_Almacen_O/#Value')[0].BindingObject\n    let clientDataUser = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n \n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Ingenio').getClientData();\n    clientData.lista_sol_ingenio = []\n \n    let filtro = `$filter=alm_sociedad eq '${data.sociedad}' and alm_almacen eq '${data.almacen}' and alm_centro eq '${data.centro}' and tipo eq 'INGENIO' &$orderby=fecha_creacion desc`\n \n    let isTecnico = clientDataUser.info_user.rol === 'Técnico'\n    if (isTecnico) {\n        let correo = clientDataUser.info_user.correo\n        //filtro += ` and correo_creacion eq ${correo}`\n        filtro = `$filter=alm_sociedad eq '${data.sociedad}' and alm_almacen eq '${data.almacen}' and alm_centro eq '${data.centro}' and tipo eq 'INGENIO' and correo_creacion eq '${correo}' &$orderby=fecha_creacion desc`\n    }\n \n    //+\"&$orderby=fecha_creacion desc\"\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'VerSolicitudesAbiertas', [], filtro).then(async (results) => {\n        if (results && results.length > 0) {\n            clientData.lista_sol_ingenio = results\n \n        } else {\n            clientData.lista_sol_ingenio = []\n        }\n \n        proxy.redraw()\n \n    }).catch((error) => {\n \n        alert(`Error ${error.message}`)\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function isVisible_Btn_CrearSolicitudes(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData.info_user\n\n    return info.rol === 'Técnico';\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function isVisible_Btn_HistoricoSolicitudes(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData.info_user\n\n    return info.rol === 'Auxiliar' || info.rol === 'Autorizador';\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function onChange_Materiales_Revision_Ing(context) {\n    const pageProxy = context.getPageProxy();\n    var cantSolicitada = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell2\")\n    var btn_aprobar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\")\n \n    cantSolicitada.setVisible(false)\n    btn_aprobar.setVisible(true)\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function setVisible_CantAprobadaRevision_Ingenio(context) {\n    const pageProxy = context.getPageProxy();\n    var cantSolicitada = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell2\")\n    var label = cantSolicitada.getControl(\"FormCellLabel1\")\n    var cant_field = cantSolicitada.getControl(\"FormCellSimpleProperty_Cantidad\")\n    var btn_aprobar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\")\n \n    let material = context.evaluateTargetPath('#Page:Revision_Solicitud_Ingenio/#Control:FormCellListPicker_Materiales/#Value');\n \n    if (material.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes seleccionar un material para continuar`\n            }\n        });\n    }\n   \n    cantSolicitada.setVisible(true);\n \n    setTimeout(() => {\n        var cantSol = material[0].BindingObject.cantidad_tomada;\n        label.setText(`Cantidad Solicitada: ${cantSol}`);\n        cant_field.setValue(cantSol);\n        btn_aprobar.setVisible(false);\n    }, 200);\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function setVisible_ConModificaciones_Ingenio(context) {\n    const pageProxy = context.getPageProxy();\n    var materiales = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell1\")\n    var btn_materiales = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\")\n    var operacion = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell3\")\n    var botones = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable1\")\n    var lista = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n   \n    botones.setVisible(false)\n    materiales.setVisible(true)\n    btn_materiales.setVisible(true)\n    lista.setVisible(true)\n    operacion.setVisible(false)\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Agregar_Materiales_Nuevos_Reabas(context) {\n    const pageProxy = context.getPageProxy();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Lista_Solicitudes_Reabastecimiento').getClientData();\n\n    let material = context.evaluateTargetPath('#Page:Agregar_Solicitud_Reabastecimiento/#Control:FormCellListPicker_Materiales_Nuevo/#Value');\n    let cant = context.evaluateTargetPath('#Page:Agregar_Solicitud_Reabastecimiento/#Control:FormCellSimpleProperty_Cantidad_Nuevo/#Value');\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n    if (material.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes seleccionar un material para continuar`\n            }\n        });\n    }\n   \n\n    let data = material[0]    \n \n    if (!cant || cant < 0) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes ingresar una cantidad valida para continuar`\n            }\n        });\n    }\n  \n    var nuevo = {\n        material: data.ReturnValue,\n        material_desc: data.DisplayValue.Subhead,\n        cant : cant,\n        und: data.DisplayValue.StatusText,\n        stock_disponible: null,\n        stock_reservado: null,\n        tipo: \"Nuevo\"\n    }\n   \n    const duplicado = clientData.lista_materiales.filter(m => m.material === nuevo.material).length > 0\n   \n    if (duplicado) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `El material ya fue ingresado anteriormente`\n            }\n        });\n    }\n \n    clientData.lista_materiales.push(nuevo)\n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Nuevo material agregado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Agregar_Materiales_Solicitud_Reabas(context) {\n\n    const pageProxy = context.getPageProxy();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Lista_Solicitudes_Reabastecimiento').getClientData();\n\n    let material = context.evaluateTargetPath('#Page:Agregar_Solicitud_Reabastecimiento/#Control:FormCellListPicker_Materiales/#Value');\n    let cant = context.evaluateTargetPath('#Page:Agregar_Solicitud_Reabastecimiento/#Control:FormCellSimpleProperty_Cantidad/#Value');\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n    if (material.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes seleccionar un material para continuar`\n            }\n        });\n    }\n   \n    let data = material[0].BindingObject\n    let stock = data.stock_disponible\n \n    //TODO DESCOMENTAR CUANDO HAYA INVENTARIO\n    /*if(stock == 0){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `No hay stock disponible para este material`\n            }\n        });\n    }*/\n \n    if (!cant || cant < 0) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes ingresar una cantidad valida para continuar`\n            }\n        });\n    }\n \n    //TODO DESCOMENTAR CUANDO HAYA INVENTARIO\n    /*if(cant > stock){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes ingresar una cantidad menor para continuar. La cantidad disponible es de ${stock} und`\n            }\n        });\n    }*/\n \n   \n \n    var nuevo = {\n        material: data.material,\n        material_desc: data.material_desc,\n        cant : cant,\n        und: data.und,\n        stock_disponible: data.stock_disponible,\n        stock_reservado: data.stock_reservado,\n        tipo: \"Registrado\"\n    }\n \n   \n    const duplicado = clientData.lista_materiales.filter(m => m.material === data.material).length > 0\n   \n    if (duplicado) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `El material ya fue ingresado anteriormente`\n            }\n        });\n    }\n \n    clientData.lista_materiales.push(nuevo)\n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Nuevo material agregado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    });\n\n\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Aprobar_Material_Revision_Abast(context) {\n    const pageProxy = context.getPageProxy();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitud_Reabastecimieto').getClientData();\n    let clientDataMaterial = context.evaluateTargetPathForAPI('#Page:Revision_Solicitud_Reabastecimiento').getClientData();\n    let data = clientDataMaterial.infoMaterial\n\n    //   var cantidad = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell1\").getControl(\"FormCellSimpleProperty_Cantidad\");\n    var cant = context.evaluateTargetPath('#Page:Revision_Sol_Almacenes_Abast/#Control:FormCellSimpleProperty_Cantidad/#Value');\n    var almacen = context.evaluateTargetPath('#Page:Revision_Sol_Almacenes_Abast/#Control:almacen/#Value');\n    \n    if (almacen.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes seleccionar un almacen para continuar`\n            }\n        });\n    }\n\n    let dataAlm = almacen[0].BindingObject\n    let stock = dataAlm.Labst\n\n    if (!cant || cant < 0) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes ingresar una cantidad válida para continuar`\n            }\n        });\n    }\n\n    if(cant > stock){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes ingresar una cantidad menor para continuar. La cantidad disponible es de ${stock} und y la solicitada es de ${data.cantidad_tomada}`\n            }\n        });\n    }\n\n    if(cant > data.cantidad_tomada){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes ingresar una cantidad menor para continuar. La cantidad disponible es de ${stock} und y la solicitada es de ${data.cantidad_tomada}`\n            }\n        });\n    }\n    //var material = data.mat_nuevo || data.material_material || '';\n\n    let material = [data.mat_nuevo, data.material_material].find(v => typeof v === 'string' && v.trim() !== '');\n\n    let material_desc = [data.mat_nuevo_desc, data.material?.material_desc]\n        .find(v => typeof v === 'string' && v.trim() !== '');\n\n    let tipo = data.mat_nuevo ? 'Nuevo' : 'Registrado';\n\n    let mat_nuevo = data.mat_nuevo\n    let material_data = data.material_material\n    let und = \"\"\n\n    if(mat_nuevo){\n       und = data.mat_nuevo_und\n    }\n\n    if(material_data){\n        und = data.material.und\n    }\n\n    var nuevo = {\n        id: data.id,\n        material: material,\n        material_desc: material_desc,\n        cant_sol: data.cantidad_tomada,\n        und: und,\n        cant_apro: cant,\n        almacen: dataAlm.Lgort,\n        aprobado: 'Aprobado',\n        tipo: tipo\n    }\n    nuevo[\"@odata.readLink\"] = data[\"@odata.readLink\"]\n    const duplicado = clientData.lista_mat_solicitud_abast.filter(m => m.material === nuevo.material).length > 0\n\n    //const duplicado = clientData.lista_mat_solicitud_abast.filter(m => m.mat_nuevo === data.mat_nuevo && m.almacen_almacen === data.almacen_almacen).length > 0\n    if (duplicado) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Material no Agregado\",\n                \"Message\": `El material ya fue agregado anteriormente`\n            }\n        }).then(() => {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/ClosePage.action\",\n                \"NavigateBackToPage\": \"/appconsumos_qa_mb/Pages/Inventario/Revision_Solicitud_Reabastecimiento.page\"\n            });\n        });\n    }\n\n\n    clientData.lista_mat_solicitud_abast.push(nuevo);\n\n    //list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Material Aprobado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    }).then(() => {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/ClosePage.action\",\n            \"NavigateBackToPage\": \"/appconsumos_qa_mb/Pages/Inventario/Revision_Solicitud_Reabastecimiento.page\"\n        });\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Autorizar_Solicitud_Abast(context) {\n\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitud_Reabastecimieto').getClientData();\n    const signatureObject = context.evaluateTargetPath(\"#Page:Autorizar_Solicitud_Reabastecimiento/#Control:FormCellInlineSignatureCapture0/#Value\");\n    clientData.b64Data = \"\"\n    if (!signatureObject) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Pendiente por firmar\",\n                \"Message\": \"La firma es requerida antes de continuar\"\n            }\n        });\n    }\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n        \"Properties\": {\n            \"Message\": \"¿Estas seguro que deseas autorizar la solicitud de abastecimiento?\",\n            \"Title\": \"Autorizar Solicitud\",\n            \"OKCaption\": \"Aceptar\",\n            \"OnOK\": \"/appconsumos_qa_mb/Actions/oData/Update_SolicitudesApp_Autorizar_Abast.action\",\n            \"CancelCaption\": \"Cancelar\"\n        }\n    });\n\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Borrar_Material_Lista_Abaste(context) {\n    const pageProxy = context.getPageProxy();\n    var data = context.binding\n    let clientData = context.evaluateTargetPathForAPI('#Page:Lista_Solicitudes_Reabastecimiento').getClientData();\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n   \n    const index = clientData.lista_materiales.findIndex(item => item.material === data.material);\n    if (index !== -1) {\n        clientData.lista_materiales.splice(index, 1); // Elimina el elemento en esa posición\n    }\n \n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Material '${data.material_desc}' eliminado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    });\n \n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Borrar_Materiales_Revision_Abast(context) {\n    var data = context.binding\n    const pageProxy = context.getPageProxy();\n\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitud_Reabastecimieto').getClientData();\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n\n\n    const index = clientData.lista_mat_solicitud_abast.findIndex(item => item.material === data.material);\n\n\n    if (index !== -1) {\n        clientData.lista_mat_solicitud_abast.splice(index, 1); // Elimina el elemento en esa posición\n\n    }\n\n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Material '${data.material_desc}' eliminado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    })\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Color_Estado_Abast(context) {\n    try {\n        var object = context.binding\n        var estado = object.estado\n       \n        if(estado == \"Enviado\"){\n            return \"Grey\"\n        }\n        if(estado == \"Aprobado\"){\n            return \"Mango\"\n        }\n        if(estado == \"Rechazado\"){\n            return \"Red\"\n        }\n        if(estado == \"Autorizado\"){\n            return \"Green\"\n        }\n        if(estado == \"Tramitado\"){\n            return \"Teal\"\n        }\n    } catch (error) {\n        console.error(\"Ocurrió un error al obtener el valor:\", error);\n        alert(\"No se pudo obtener el valor: \" + error.message);\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Color_Tipo_ListaMaterial(context) {\n    try {\n        var object = context.binding\n        var tipo = object.tipo\n        \n        if(tipo == \"Registrado\"){\n            return \"Grey\"\n        }\n        if(tipo == \"Nuevo\"){\n            return \"Indigo\"\n        }\n    } catch (error) {\n        console.error(\"Ocurrió un error al obtener el color del tipo:\", error);\n        alert(\"No se pudo obtener el color del tipo: \" + error.message);\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Color_Tipo_Material_Revisar(context) {\n    let mat_nuevo = context.binding.mat_nuevo\n    let material = context.binding.material_material\n\n    if(mat_nuevo){\n        return \"Indigo\"\n    }\n\n    if(material){\n        return \"Grey\"\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function ConfirmarMaterialesItems_Abast(context) {\n    const pageProxy = context.getPageProxy();\n    var table = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n    var items = table.getSelectedItems()\n    var cant = table.getSelectedItemsCount()\n\n    let exitosos = [];\n    let errores = [];\n\n\n    let promisesConfirmados = items.map(e => {\n        let item = e.binding\n        let desc = \"\"\n        let idMaterial = \"\"\n        if(typeof item.mat_nuevo_desc === 'string'){\n            desc= item.mat_nuevo_desc\n            idMaterial=item.mat_nuevo\n        }\n        if(typeof item.material?.material_desc === 'string'){\n            desc= item.material.material_desc\n            idMaterial=item.material_material\n        }\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/oData/Update_ComponentesSolicitudApp.action\",\n            \"Properties\": {\n                \"Target\": {\n                    \"ReadLink\": item[\"@odata.readLink\"]\n                },\n                \"Properties\": {\n                    \"id\": item.id,\n                    \"confirmacion_tec\": true,\n                    \"aprobado\": true,\n                    \"cantidad_aprobada\":item.cantidad_aprobada\n                }\n            }\n        }).then(() => {\n            exitosos.push(`${idMaterial} - ${desc}`);\n        }).catch((error) => {\n            //alert(`Error actualizando material ${idMaterial}:`, error);\n            errores.push(`${idMaterial} - ${desc}`);\n        });\n    });\n    \n\n    // Procesar los resultados\n    return Promise.allSettled(promisesConfirmados).then(() => {\n        let mensaje = '';\n\n        if (errores.length === 0) {\n            mensaje = 'Solicitud gestionada correctamente. Los materiales fueron confirmados exitosamente.';\n        } else if (exitosos.length === 0) {\n            mensaje = `Solicitud no gestionada. Falló la confirmación de todos los materiales:\\n${errores.join('\\n')}`;\n        } else {\n            mensaje = `Solicitud no gestionada parcialmente. Algunos materiales fueron confirmados con éxito.\\n\\nErrores:\\n${errores.join('\\n')}`;\n        }\n\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Resultado\",\n                \"Message\": mensaje\n            }\n        }).then(() => {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/CloseModalPage_Complete.action\",\n                \"NavigateBackToPage\": \"/appconsumos_qa_mb/Pages/Inventario/Detalle_Solicitud_Reabastecimieto.page\"\n            });\n        });\n    });\n}\n","/**\n * Confirma la revisión de una solicitud de reabastecimiento.\n * @param {IClientAPI} context\n */\nexport default function Confirmar_Revision_Abast(context) {\n\n    let id_solicitud = context.binding.id;\n    let filtro = `$filter=solicitud_id eq ${id_solicitud}`;\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitud_Reabastecimieto').getClientData();\n    let listaDeAgregados = clientData.lista_mat_solicitud_abast || [];\n\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ComponentesSolicitud', [], filtro).then((results) => {\n        if (results && results.length > 0) {\n            let totalComponentes = results.length;\n\n            if (listaDeAgregados.length < totalComponentes) {\n                return context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Solicitud No Confirmada\",\n                        \"Message\": \"No puedes confirmar la solicitud hasta que se hayan agregado todos los materiales.\"\n                    }\n                });\n            }\n\n            // Validaciones sobre el campo 'aprobado'\n            let todosRechazados = listaDeAgregados.every(m => m.aprobado === 'Rechazado');\n            let alMenosUnoAprobado = listaDeAgregados.some(m => m.aprobado === 'Aprobado');\n\n            if (todosRechazados) {\n                return context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Solicitud No Aprobada\",\n                        \"Message\": \"No se puede aprobar la solicitud porque todos los materiales fueron rechazados.\"\n                    }\n                });\n            }\n\n            if (alMenosUnoAprobado) {\n                return context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Confirmación\",\n                        \"Message\": \"¿Estás seguro que deseas aprobar la solicitud?\",\n                        \"OKCaption\": \"Aceptar\",\n                        \"OnOK\": \"/appconsumos_qa_mb/Actions/oData/Update_SolicitudesApp_Confirmar_Abast.action\",\n                        \"CancelCaption\": \"Cancelar\"\n                    }\n                });\n            }\n\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Estado no definido\",\n                    \"Message\": \"Al menos un material debe estar aprobado para confirmar la solicitud.\"\n                }\n            });\n\n        } else {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Error\",\n                    \"Message\": \"Error al tratar de traer los componentes de la solicitud.\"\n                }\n            });\n        }\n\n    }).catch((error) => {\n        alert(`Error ${error.message}`);\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Confirmar_Sol_Abast_Revision_Items(context) {\n    //const pageProxy = context.getPageProxy();\n    //var materiales = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell1\")\n    let materialesRechazados = [];\n    let materialesAprobados = [];\n    let exitosos = [];\n    let errores = [];\n    //let id_solicitud = context.binding.id;\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitud_Reabastecimieto').getClientData();\n    let clientDataAlmacen = context.evaluateTargetPathForAPI('#Page:Filtro_Almacen_Solicitud_Abast').getClientData();\n    let dataAlmacen = clientDataAlmacen.almacen_abast;\n\n    //let filtro = `$expand=material,almacen&$filter=solicitud_id eq ${id_solicitud}`;\n    let listaDeAgregados = clientData.lista_mat_solicitud_abast;\n\n    \n    /*var nuevo = {\n        id: data.id,\n        material: material,\n        material_desc: material_desc,\n        cant_sol: data.cantidad_tomada,\n        cant_apro: 0,\n        almacen: null,\n        aprobado: 'Rechazado',\n        tipo: tipo\n    }\n    */\n\n    listaDeAgregados.forEach(item => {\n        const materialData = {\n            descripcion: item.material_desc,\n            material: item.material,\n            id_componente: item.id,\n            readLink: item[\"@odata.readLink\"]\n        };\n        \n\n        if (item.aprobado === 'Aprobado') {\n            materialData.cantidad_aprobada = item.cant_apro;\n            materialData.almacen_centro = dataAlmacen.centro,\n            materialData.almacen_sociedad= dataAlmacen.sociedad,\n            materialData.almacen_almacen =  item.almacen,\n            materialesAprobados.push(materialData);\n        } else {\n\n            //rechazado\n            materialData.cantidad_aprobada = 0;\n            materialesRechazados.push(materialData);\n        }\n    });\n\n    let promisesAprobados = materialesAprobados.map(material => {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/oData/Update_ComponentesSolicitudApp.action\",\n            \"Properties\": {\n                \"Target\": {\n                    \"ReadLink\": material.readLink\n                },\n                \"Properties\": {\n                    \"id\": material.id_componente,\n                    \"almacen_centro\": material.almacen_centro,\n                    \"almacen_sociedad\": material.almacen_sociedad,\n                    \"almacen_almacen\": material.almacen_almacen,\n                    \"cantidad_aprobada\": parseFloat(material.cantidad_aprobada) || 0,\n                    \"aprobado\": true\n                }\n            }\n        }).then(() => {\n            exitosos.push(`${material.material} - ${material.descripcion}`);\n        }).catch((error) => {\n            alert(`Error actualizando material ${material.material}:`, error);\n            errores.push(`${material.material} - ${material.descripcion}`);\n        });\n    });\n    let promisesRechazados = materialesRechazados.map(material => {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/oData/Update_ComponentesSolicitudApp.action\",\n            \"Properties\": {\n                \"Target\": {\n                    \"ReadLink\": material.readLink\n                },\n                \"Properties\": {\n                    \"id\": material.id_componente,\n                    \"cantidad_aprobada\": 0,\n                    \"aprobado\": false,\n                    \"confirmacion_tec\": false\n                }\n            }\n        }).then(() => {\n            exitosos.push(`${material.material} - ${material.descripcion}`);\n        }).catch((error) => {\n            alert(`Error actualizando material ${material.material}:`, error);\n            errores.push(`${material.material} - ${material.descripcion}`);\n        });\n    });\n\n    // Procesar los resultados\n    return Promise.allSettled([...promisesAprobados, ...promisesRechazados]).then(() => {\n        let mensaje = '';\n\n        if (errores.length === 0) {\n            mensaje = 'Solicitud gestionada correctamente. Todos los materiales de la solicitud fueron gestionados exitosamente.';\n        } else if (exitosos.length === 0) {\n            mensaje = `Solicitud no gestionada. Falló la gestión de todos los materiales:\\n${errores.join('\\n')}`;\n        } else {\n            mensaje = `Solicitud no gestionada parcialmente. Algunos materiales fueron gestionados con éxito.\\n\\nErrores:\\n${errores.join('\\n')}`;\n        }\n\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Resultado\",\n                \"Message\": mensaje\n            }\n        }).then(() => {\n\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/CloseModalPage_Complete.action\",\n                \"NavigateBackToPage\": \"/appconsumos_qa_mb/Pages/Inventario/Detalle_Solicitud_Reabastecimieto.page\"\n            });\n        });\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nimport guid from '../guid'\nexport default function Create_Solicitud_Abastecimiento(context) {\n\n    let actionResult = context.getActionResult(\"Create_SolicitudApp_Abastecimiento\");\n\n    let data = JSON.parse(actionResult.data)\n    let idSolicitud = data.id\n\n    let clientData = context.evaluateTargetPathForAPI('#Page:Lista_Solicitudes_Reabastecimiento').getClientData();\n    let lista_materiales = clientData.lista_materiales;\n\n    // Obtener datos del almacén desde ClientData\n    let clientDataAlmacen = context.evaluateTargetPathForAPI('#Page:Filtro_Almacen_Solicitud_Abast').getClientData();\n    let dataAlmacen = clientDataAlmacen.almacen_abast;\n\n\n    let exitosos = [];\n    let errores = [];\n\n    // Create de la solicitud\n    let promises = lista_materiales.map(material => {\n        let props = {\n            id: guid(context),\n            solicitud_id: idSolicitud,\n            cantidad_tomada: material.cant\n        };\n\n        if (material.tipo === \"Nuevo\") {\n            props.mat_nuevo = material.material;\n            props.mat_nuevo_desc = material.material_desc;\n            props.mat_nuevo_und = material.und;\n        } else if (material.tipo === \"Registrado\") {\n            Object.assign(props, {\n                material_material: material.material,\n                material_almacen: dataAlmacen.almacen,\n                material_centro: dataAlmacen.centro,\n                material_sociedad: dataAlmacen.sociedad,\n                //almacen_sociedad: dataAlmacen.sociedad,\n                //almacen_almacen: dataAlmacen.almacen,\n                //almacen_centro: dataAlmacen.centro\n            });\n        }\n\n        return context.executeAction({\n            Name: \"/appconsumos_qa_mb/Actions/oData/Create_ComponentesSolicitudApp.action\",\n            Properties: {\n                Properties: props\n            }\n        }).then(() => {\n            exitosos.push(`${material.material} (${material.material_desc})`);\n        }).catch(() => {\n            errores.push(`${material.material} (${material.material_desc})`);\n        });\n    });\n\n    // Procesar los resultados\n    return Promise.allSettled(promises).then(() => {\n        let mensaje = '';\n\n        if (errores.length === 0) {\n            mensaje = 'Todos los materiales fueron agregados exitosamente a la solicitud.';\n        } else if (exitosos.length === 0) {\n            mensaje = `Falló la creación de todos los materiales:\\n${errores.join('\\n')}`;\n        } else {\n            mensaje = `Algunos materiales fueron agregados con éxito.\\n\\nErrores:\\n${errores.join('\\n')}`;\n        }\n\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Resultado\",\n                \"Message\": mensaje\n            }\n        }).then(() => {\n            // Finalmente cerrar el modal\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/CloseModalPage_Complete.action\",\n                \"Properties\": {\n                    \"NavigateBackToPage\": \"/appconsumos_qa_mb/Pages/Inventario/Lista_Solicitudes_Reabastecimiento.page\",\n                }\n            }).then(() => {\n                // Finalmente cerrar el modal\n                return context.executeAction(\"/appconsumos_qa_mb/Actions/app_consumos_qa/Service/OnlySyncStartedMessage.action\");\n            });\n        });\n    });\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Filtro_Centro_Material_Inv(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info_sociedad = clientData.info_user.sociedad;\n    let centroFiltro = '';\n    \n    if (info_sociedad == \"AI01\") {\n        centroFiltro = \"centro ge '2000' and centro le '2199'\";\n    } else if (info_sociedad == \"AI08\") {\n        centroFiltro = \"centro ge '2200'\";\n    }\n    \n    let filtro = `$filter=${centroFiltro}&$orderby=almacen`;\n    \n    return filtro;\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Filtro_Material_Almacenes(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Almacen_Inventario').getClientData();\n    let almacenesSeleccionados = clientData.almacen_inventario;\n\n    if (almacenesSeleccionados && almacenesSeleccionados.length > 0) {\n        // Tomar el centro desde el primer almacén\n        let centro = almacenesSeleccionados[0].BindingObject.centro;\n\n        // Iniciar filtro\n        let filtro = `$filter=Werks eq '${centro}' and Spras eq 'ES' and contains(Txtmd, 'BORRADO') eq false and contains(Txtmd, 'BORRAR') eq false and contains(Txtmd, 'BORRAD_') eq false and (`;\n\n        // Agregar cada almacén con OR\n        almacenesSeleccionados.forEach(item => {\n            filtro += `Lgort eq '${item.BindingObject.almacen}' or `;\n        });\n\n        // Quitar el último \" or \" y cerrar\n        filtro = filtro.slice(0, -4) + `)&$orderby=Matnr`;\n\n        // Puedes guardar este filtro en ClientData si lo deseas\n        clientData.filtroMaterial = filtro;\n\n        //alert(filtro);\n        return filtro;\n        \n    } else {\n        alert(\"Error: No se seleccionaron almacenes.\");\n    }\n}\n","//import logo_pro from '../..Images/logo_pro.png';\nimport Rule_openDocumentoAnd from '../Rule_openDocumentoAnd.js';\nimport Rule_openDocumentoIOS from '../Rule_openDocumentoIOS.js';\nimport get_FechaHoraCol from '../get_FechaHoraCol.js';\n\n/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function FirmarSolicitud_Abast(context) {\n\n    let clientDataAutorizar = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitud_Reabastecimieto').getClientData();\n    //Logo\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info_user = clientData.info_user\n    let user = info_user.nombre\n    let ficha = info_user.ficha\n    let sociedad = info_user.sociedad\n    let BindingData = context.binding\n    let almacen = BindingData.almacen.almacen_desc\n    let logo;\n    if (sociedad == 'AI08') {\n        let logo_pro = context.getGlobalDefinition('/appconsumos_qa_mb/Globals/logo_pro.global');\n        logo = logo_pro.getValue()\n    }\n\n    if (sociedad == 'AI01') {\n        let logo_inc = context.getGlobalDefinition('/appconsumos_qa_mb/Globals/logo_inc.global');\n        logo = logo_inc.getValue()\n    }\n\n    //firma \n    //const pageProxy = context.getPageProxy();\n    const platform = context.nativescript.platformModule;\n    const signatureObject = context.evaluateTargetPath(\"#Page:Autorizar_Solicitud_Reabastecimiento/#Control:FormCellInlineSignatureCapture0/#Value\");\n    let signatureContent;\n\n    if (platform.isAndroid) {\n        signatureContent = android.util.Base64.encodeToString(signatureObject.content, android.util.Base64.DEFAULT);\n    } else if (platform.isIOS) {\n        signatureContent = signatureObject.content.base64Encoding();\n    }\n\n    function sendEmail(pdf) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/Call_Sendmail.action\",\n            \"Properties\": {\n                \"OnFailure\": \"\",\n                \"OnSuccess\": \"\",\n                \"Target\": {\n                    \"Service\": \"/appconsumos_qa_mb/Services/backend_REST.service\",\n                    \"Path\": \"/sendmail\",\n                    \"RequestProperties\": {\n                        \"Method\": \"POST\",\n                        \"Body\": {\n                            \"sender\": \"natalia.lopez@structum-co.com\",\n                            \"to\": \"nlopez8066@outlook.com\",\n                            \"subject\": \"CONTROL DE SALIDA DE REPUESTOS, HERRAMIENTAS Y EQUIPOS\",\n                            \"body\": `FYI`,\n                            \"nombre\": \"salidaCampo.pdf\",\n                            \"adj\": `${pdf}`\n                        },\n\n                    }\n                }\n            }\n        })/*.then((result) => {\n            if (result && result.data) {\n                //alert(JSON.stringify(result))\n                return;\n            }\n\n        }).catch((error) => {\n            //alert(\"Error al enviar correo1:\\n\" + (error.message || error));\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Error al enviar correo\",\n                    \"Message\": error.error.message,\n                    \"OKCaption\": \"Aceptar\"\n                }\n            });\n        });*/\n    }\n\n\n    const reqdata = {\n        fecha: get_FechaHoraCol(),\n        pEntrega: \"\",\n        pEntregaficha: \"\",\n        pAutoriza: user,\n        pAutorizaficha: ficha\n    }\n\n    //items de la solicitud\n    const datajson = []\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ComponentesSolicitud', [], `$expand=material,almacen&$filter=solicitud_id eq ${BindingData.id}`).then(async (results) => {\n        if (results && results.length > 0) {\n            results.forEach(e => {\n                let sap = \"\"\n                let desc = \"\"\n                if(typeof e.mat_nuevo_desc === 'string'){\n                    sap = e.mat_nuevo\n                    desc = e.mat_nuevo_desc\n                }\n                if(typeof e.material_material === 'string'){\n                    sap = e.material_material\n                    desc = e.material.material_desc\n                }\n                if (e.aprobado) {\n                    datajson.push({\n                        alce: almacen,\n                        sap: sap.replace(/^0+/, ''),\n                        desc: desc,\n                        cant: String(e.cantidad_aprobada),\n                        um: \"\"\n                    })\n                }\n            });\n\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/Call_generatePDF.action\",\n                \"Properties\": {\n                    \"OnFailure\": \"\",\n                    \"OnSuccess\": \"\",\n                    \"Target\": {\n                        \"Service\": \"/appconsumos_qa_mb/Services/backend_REST.service\",\n                        \"Path\": \"/generatePDF\",\n                        \"RequestProperties\": {\n                            \"Method\": \"POST\",\n                            \"Body\": {\n                                \"data\": reqdata,\n                                \"image\": `${signatureContent}`,\n                                \"items\": datajson,\n                                \"logo\": `${logo}`\n                            },\n\n                        }\n                    }\n                }\n            }).then((result) => {\n                if (result && result.data) {\n\n                    //context.b64Data = result.data.value\n                    clientDataAutorizar.b64Data = result.data.value\n                    return sendEmail(result.data.value)\n                        .catch((error) => {\n                            alert(`Error al enviar correo - ${error}`)\n                            /*return context.executeAction({\n                                \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n                                \"Properties\": {\n                                    \"Message\": `Error al enviar correo - ${error?.error?.message}`,\n                                    \"Duration\": 2\n                                }\n                            });*/\n                        })\n                        .then((result) => {\n\n                            context.executeAction({\n                                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                                \"Properties\": {\n                                    \"Title\": \"Correo enviado exitosamente\",\n                                    \"Message\": \"La orden de salida fue enviada correctamente al correo.\",\n                                    \"OKCaption\": \"Aceptar\"\n                                }\n                            });\n                            // Este bloque se ejecutará tanto si sendEmail fue exitoso como si falló\n                            if (platform.isAndroid) {\n                                return context.executeAction({\n                                    \"Name\": \"/appconsumos_qa_mb/Actions/CloseModalPage_Complete.action\",\n                                    \"Properties\": {\n                                        \"NavigateBackToPage\": \"Detalle_Solicitud_Reabastecimieto\",\n                                    }\n                                }).then(() => {\n                                    return new Promise((resolve) => setTimeout(resolve, 500));\n                                }).then(() => {\n                                    try {\n                                        return Rule_openDocumentoAnd(context);\n                                    } catch (errorOpen) {\n                                        alert(\"Error al abrir documento en Android:\\n\" + (errorOpen.message || errorOpen));\n                                    }\n                                }).catch((errorClose) => {\n                                    alert(\"Error al cerrar modal:\\n\" + (errorClose.message || errorClose));\n                                });\n                            } else if (platform.isIOS) {\n                                return context.executeAction({\n                                    \"Name\": \"/appconsumos_qa_mb/Actions/CloseModalPage_Complete.action\",\n                                    \"Properties\": {\n                                        \"NavigateBackToPage\": \"Detalle_Solicitud_Reabastecimieto\"\n                                    }\n                                }).then(() => {\n                                    setTimeout(() => {\n                                        try {\n                                            return Rule_openDocumentoIOS(context)\n                                        } catch (errorOpen) {\n                                            alert(\"Error al abrir documento en IOS:\\n\" + (errorOpen.message || errorOpen));\n                                        }\n                                    }, 500);\n                                }).catch((errorClose) => {\n                                    alert(\"Error al cerrar modal:\\n\" + (errorClose.message || errorClose));\n                                });\n                            }\n                        });\n                }\n\n            }).catch((error) => {\n                alert(error)\n            });\n        }\n    }).catch((error) => {\n\n        alert(`Error ${error.message}`)\n    });\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Get_FilterRead_ZBIW_MARDT(context) {\n    let clientDataFiltro = context.evaluateTargetPathForAPI('#Page:Filtro_Almacen_Solicitud_Abast').getClientData();\n    return clientDataFiltro.filtroMaterial\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Get_List_Materiales_Nuevos(context) {\n    let clientDataFiltro = context.evaluateTargetPathForAPI('#Page:Filtro_Almacen_Solicitud_Abast').getClientData();\n    let materiales = clientDataFiltro.materiales_nuevos\n    return materiales\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function NavTo_Agregar_Solicitud_Reabastecimiento(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Lista_Solicitudes_Reabastecimiento').getClientData();\n    let clientDataFiltro = context.evaluateTargetPathForAPI('#Page:Filtro_Almacen_Solicitud_Abast').getClientData();\n    //let materialesNuevos = clientDataFiltro.materiales_nuevos\n    clientData.lista_materiales = []\n\n    /*if(!materialesNuevos){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n            \"Properties\": {\n                \"Message\": `Cargando materiales, por favor espera un momento...`,\n                \"Duration\": 1\n            }\n        });\n    }*/\n \n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n        \"Properties\": {\n            \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Inventario/Agregar_Solicitud_Reabastecimiento.page\",\n            \"ModalPage\": true,\n            \"ModalPageFullscreen\": true\n        }\n    });\n \n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function NavTo_ConsultarInv_Almacen(context) {\n    let almacen = context.evaluateTargetPath('#Page:Filtro_Almacen_Inventario/#Control:FormCellListPicker_Almacen_Inv/#Value');\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Almacen_Inventario').getClientData();\n    clientData.almacen_inventario = almacen;\n    //alert(JSON.stringify(clientData.almacen_inventario[0]))\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n        \"Properties\": {\n            \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Inventario/Consultar_Inventario_Almacenes.page\",\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function NavTo_Filtro_Abast(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Inicio_Inventario').getClientData();\n    clientData.lista_abast = []\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n        \"Properties\": {\n            \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Inventario/Filtro_Almacen_Solicitud_Abast.page\"\n        }\n    });\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function NavTo_Inventario(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData.info_user\n\n    if(!clientData.info_user){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n            \"Properties\": {\n                \"Message\": `Sincronizando datos, por favor espera un momento...`,\n                \"Duration\": 1\n            }\n        });\n    }\n\n    if (info.estado == 'Activo') {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n            \"Properties\": {\n                \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Inventario/Inicio_Inventario.page\"\n            }\n        });\n    }\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n        \"Properties\": {\n            \"Title\": \"Alerta\",\n            \"Message\": `No tienes permisos para ingresar a este módulo`\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function NavTo_List_Abastecimiento(context) {\n    let almacen = context.evaluateTargetPath('#Page:Filtro_Almacen_Solicitud_Abast/#Control:FormCellListPicker_Almacen_Reabast/#Value')[0].BindingObject;\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Almacen_Solicitud_Abast').getClientData();\n    clientData.almacen_abast = almacen;\n    //alert(JSON.stringify(clientData.almacen_abast))\n    clientData.materiales_nuevos = []\n\n    let filtro = `$filter=Werks eq '${almacen.centro}' and Spras eq 'ES' and Lgort ne '${almacen.almacen}' and contains(Txtmd, 'BORRADO') eq false&$orderby=Lgort`\n\n    /*context.read('/appconsumos_qa_mb/Services/ZBODEGA_AGO_SRV.service', 'ZBIW_MARDTSet', [], filtro).then(async (results) => {\n\n        clientData.materiales_nuevos = []\n        context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n            \"Properties\": {\n                \"Message\": `Los materiales ya están disponibles. Puedes crear nuevas solicitudes.`,\n                \"Duration\": 1\n            }\n        });\n\n        if (results && results.length > 0) {\n            const materialesUnicos = results.filter(\n                (item, index, self) =>\n                    index === self.findIndex(m => m.Matnr === item.Matnr)\n            );\n\n            clientData.materiales_nuevos = materialesUnicos\n            \n        }\n    }).catch((error) => {\n\n        alert(`Error al obtener los materiales del ERP ${error.message}`)\n    });*/\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n        \"Properties\": {\n            \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Inventario/Lista_Solicitudes_Reabastecimiento.page\"\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function NavTo_RevisionAlmacenes(context) {\n\n    let clientData = context.evaluateTargetPathForAPI('#Page:Revision_Solicitud_Reabastecimiento').getClientData();\n    let materialLP = context.evaluateTargetPath('#Page:Revision_Solicitud_Reabastecimiento/#Control:materiales_revision_abast/#Value')\n    clientData.infoMaterial = materialLP[0].BindingObject\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n        \"Properties\": {\n            \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Inventario/Revision_Sol_Almacenes_Abast.page\",\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function NavTo_RevisionSolicitudAbast(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitud_Reabastecimieto').getClientData();\n    clientData.lista_mat_solicitud_abast = []\n    clientData.id_de_solicitud = context.binding.id;\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n        \"Properties\": {\n            \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Inventario/Revision_Solicitud_Reabastecimiento.page\",\n            \"ModalPage\": true,\n            \"ModalPageFullscreen\": true\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Query_Confirmar_Componentes_Abast(context) {\n    let id_solicitud = context.binding.id\n    let filtro = `$expand=material,almacen&$filter=solicitud_id eq ${id_solicitud} and aprobado eq true`\n\n    return filtro\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Query_Detalle_Componentes_Abast(context) {\n    let id_solicitud = context.binding.id\n\n    let filtro = `$expand=material,material/und,almacen&$filter=solicitud_id eq ${id_solicitud} and material_material ne null`\n\n    return filtro\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Query_Detalle_Componentes_Abast_Nuevo(context) {\n    let id_solicitud = context.binding.id\n\n    let filtro = `$expand=almacen&$filter=solicitud_id eq ${id_solicitud} and mat_nuevo ne null`\n\n    return filtro\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Query_Lista_Abast(context) {\n    //let clientData = context.evaluateTargetPathForAPI('#Page:Inicio_Inventario').getClientData();\n    let clientDataUser = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let clientDataAlmacen = context.evaluateTargetPathForAPI('#Page:Filtro_Almacen_Solicitud_Abast').getClientData();\n\n    let dataAlmacen = clientDataAlmacen.almacen_abast;\n\n\n    let filtro = `$filter=almacen_sociedad eq '${dataAlmacen.sociedad}' and almacen_almacen eq '${dataAlmacen.almacen}' and almacen_centro eq '${dataAlmacen.centro}' and tipo eq 'ABASTECIMIENTO' &$orderby=fecha_creacion desc &$expand=operario,aprobador,autorizador,almacen`\n    let isTecnico = clientDataUser.info_user.rol === 'Técnico'\n    if (isTecnico) {\n        let correo = clientDataUser.info_user.correo\n        filtro = `$filter=almacen_sociedad eq '${dataAlmacen.sociedad}' and almacen_almacen eq '${dataAlmacen.almacen}' and almacen_centro eq '${dataAlmacen.centro}' and tipo eq 'ABASTECIMIENTO' and correo_creacion eq '${correo}' &$orderby=fecha_creacion desc &$expand=operario,aprobador,autorizador,almacen`\n    }\n    return filtro;\n\n    //lista_abast\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Query_Revisar_Abast(context) {\n    let id_solicitud = context.binding.id\n\n    let filtro = `$expand=material,almacen&$filter=solicitud_id eq ${id_solicitud}`\n\n    return filtro\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Rechazar_Material_Revision_Abast(context) {\n\n    const pageProxy = context.getPageProxy();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitud_Reabastecimieto').getClientData();\n    //clientData.lista_mat_solicitud_abast\n\n    //let material = context.evaluateTargetPath('#Page:Revision_Solicitud_Ingenio/#Control:FormCellListPicker_Materiales/#Value');\n\n    let clientDataMaterial = context.evaluateTargetPathForAPI('#Page:Revision_Solicitud_Reabastecimiento').getClientData();\n    let data = clientDataMaterial.infoMaterial\n\n    //var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\");\n\n    //let data = material[0].BindingObject\n\n    /*\n    if (material.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Material no Agregado\",\n                \"Message\": `Debes seleccionar un material para continuar`\n            }\n        });\n    }*/\n\n\n    //var material = data.mat_nuevo || data.material_material || '';\n    \n    let material = [data.mat_nuevo, data.material_material].find(v => typeof v === 'string' && v.trim() !== '');\n\n    let material_desc = [data.mat_nuevo_desc, data.material?.material_desc]\n        .find(v => typeof v === 'string' && v.trim() !== '');\n\n    let tipo = data.mat_nuevo ? 'Nuevo' : 'Registrado';\n    \n    var nuevo = {\n        id: data.id,\n        material: material,\n        material_desc: material_desc,\n        cant_sol: data.cantidad_tomada,\n        cant_apro: 0,\n        almacen: null,\n        aprobado: 'Rechazado',\n        tipo: tipo\n    }\n    nuevo[\"@odata.readLink\"] = data[\"@odata.readLink\"]\n    const duplicado = clientData.lista_mat_solicitud_abast.filter(m => m.material === nuevo.material).length > 0\n\n    //const duplicado = clientData.lista_mat_solicitud_abast.filter(m => m.mat_nuevo === data.mat_nuevo && m.almacen_almacen === data.almacen_almacen).length > 0\n    if (duplicado) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Material no Agregado\",\n                \"Message\": `El material ya fue agregado anteriormente`\n            }\n        });\n    }\n\n\n    clientData.lista_mat_solicitud_abast.push(nuevo);\n\n    //list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Material Rechazado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    }).then(() => {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/ClosePage.action\",\n            \"NavigateBackToPage\": \"/appconsumos_qa_mb/Pages/Inventario/Revision_Solicitud_Reabastecimiento.page\"\n        });\n    });;\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Rechazar_Solicitud_Abast(context) {\n    let id_solicitud = context.binding.id;\n    let filtro = `$expand=almacen,material&$filter=solicitud_id eq ${id_solicitud}`;\n    let materialesRechazados = [];\n    let exitosos = [];\n    let errores = [];\n\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ComponentesSolicitud', [], filtro).then(async (results) => {\n        if (results && results.length > 0) {\n            for (let i = 0; i < results.length; i++) {\n                let item = results.getItem(i);\n\n                let descripcion, material;\n\n                if (!item.mat_nuevo) {\n                    // Si mat_nuevo es null, undefined o ''\n                    material = item.material?.material || '';\n                    descripcion = item.material?.material_desc || '';\n                } else {\n                    material = item.mat_nuevo;\n                    descripcion = item.mat_nuevo_desc;\n                }\n\n                materialesRechazados.push({\n                    descripcion: descripcion,\n                    material: material,\n                    //almacen_centro: item.almacen.centro,\n                    //almacen_sociedad: item.almacen.sociedad,\n                    //almacen_almacen: item.almacen.almacen,\n                    id_componente: item.id,\n                    readLink: item[\"@odata.readLink\"]\n                });\n            }\n        } else {\n            alert(\"No hay datos\");\n            return;\n        }\n\n        let promises = materialesRechazados.map(material => {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/oData/Update_ComponentesSolicitudApp.action\",\n                \"Properties\": {\n                    \"Target\": {\n                        \"ReadLink\": material.readLink\n                    },\n                    \"Properties\": {\n                        \"id\": material.id_componente,\n                        \"cantidad_aprobada\": 0,\n                        \"aprobado\": false,\n                        \"confirmacion_tec\": false\n                    }\n                }\n            }).then(() => {\n                exitosos.push(`${material.material} - ${material.descripcion}`);\n            }).catch((error) => {\n                alert(`Error updating material ${material.material}:`, error);\n                errores.push(`${material.material} - ${material.descripcion}`);\n            });\n        });\n\n        // Procesar los resultados\n        return Promise.allSettled(promises).then(() => {\n            let mensaje = '';\n\n            if (errores.length === 0) {\n                mensaje = 'Solicitud Rechazada correctamente. Todos los materiales de la solicitud fueron rechazados exitosamente.';\n            } else if (exitosos.length === 0) {\n                mensaje = `Solicitud rechazada. Falló el rechazo de todos los materiales:\\n${errores.join('\\n')}`;\n            } else {\n                mensaje = `Solicitud rechazada parcialmente. Algunos materiales fueron rechazados con éxito.\\n\\nErrores:\\n${errores.join('\\n')}`;\n            }\n\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Resultado\",\n                    \"Message\": mensaje\n                }\n            }).then(() => {\n                return context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/CloseModalPage_Complete.action\",\n                    \"NavigateBackToPage\": \"/appconsumos_qa_mb/Pages/Inventario/Detalle_Solicitud_Reabastecimieto.page\"\n                });\n            });\n        });\n\n    }).catch((error) => {\n        alert(`Error ${error.message}`);\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Redraw_List_Revisar(context) {\n\n    const pageProxy = context.getPageProxy();\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\");\n    list_component.redraw()\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Select_Almacen_Filtro_Inventario(context) {\n    let almacenLPInv = context.evaluateTargetPath('#Page:Filtro_Almacen_Inventario/#Control:FormCellListPicker_Almacen_Inv/#Value')\n    const pageProxy = context.getPageProxy();\n    var btn_inventario = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\").getControl(\"btn_inventario\")\n\n    if (almacenLPInv.length > 0) {\n        btn_inventario.setEnabled(true)\n    }else{\n        btn_inventario.setEnabled(false)\n    }\n}\n","/**\n * Describe this function...\n * @param {context} clientAPI\n */\nexport default function Select_Almacen_Sol_Abast(context) {\n    let almacenLP = context.evaluateTargetPath('#Page:Filtro_Almacen_Solicitud_Abast/#Control:FormCellListPicker_Almacen_Reabast/#Value')\n    const pageProxy = context.getPageProxy();\n    var btn_crearSolicitud = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\").getControl(\"FormCellButton_Solicitudes\")\n\n    if (almacenLP.length > 0) {\n        btn_crearSolicitud.setEnabled(true)\n    }else{\n        btn_crearSolicitud.setEnabled(false)\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Select_Material_Revisar_Abast(context) {\n    let materialLP = context.evaluateTargetPath('#Page:Revision_Solicitud_Reabastecimiento/#Control:materiales_revision_abast/#Value')\n    const pageProxy = context.getPageProxy();\n    var btn_almacenes = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\").getControl(\"btn_almacenes\")\n\n    if (materialLP.length > 0) {\n        btn_almacenes.setEnabled(true)\n    }else{\n        btn_almacenes.setEnabled(false)\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Target_Lista_Materiales_Agregados(context) {\n    let target = context.evaluateTargetPath('#Page:Lista_Solicitudes_Reabastecimiento/#ClientData/#Property:lista_materiales');\n    let searchString = context.searchString;\n\n    if (searchString) {\n        let lowerSearch = searchString.toLowerCase();\n\n        let searchResult = target.filter(prod => {\n            return (prod.material || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.material_desc || \"\").toLowerCase().includes(lowerSearch);\n        });\n\n        target = searchResult;\n    }\n\n    return target;\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Target_Materiales_Revision_Abast(context) {\n\n    let target = context.evaluateTargetPath(\"#Page:Detalle_Solicitud_Reabastecimieto/#ClientData/#Property:lista_mat_solicitud_abast\");\n    let searchString = context.searchString;\n\n    if (searchString) {\n        let lowerSearch = searchString.toLowerCase();\n\n        let searchResult = target.filter(prod => {\n            return (prod.mat_nuevo || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.mat_nuevo_desc || \"\").toLowerCase().includes(lowerSearch);\n        });\n\n        target = searchResult;\n    }\n\n    return target;\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Target_Revisar_Almacenes_Abast(context) {\n\n    let clientData = context.evaluateTargetPathForAPI('#Page:Revision_Solicitud_Reabastecimiento').getClientData();\n\n    return clientData.infoMaterial\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Validate_Create_Solicitud_Abast(context) {\n    let clientDataDetalle = context.evaluateTargetPathForAPI('#Page:Lista_Solicitudes_Reabastecimiento').getClientData();\n    clientDataDetalle.lista_materiales\n    let ficha = context.evaluateTargetPath('#Page:Agregar_Solicitud_Reabastecimiento/#Control:FormCellSimpleProperty_Ficha/#Value');\n    if(ficha){\n        return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'EmpleadosApp', [], `$filter=ficha eq '${ficha}'`).then(async (results) => {\n            if (results && results.length > 0) {\n                if(clientDataDetalle.lista_materiales && clientDataDetalle.lista_materiales.length > 0 ){\n                    return context.executeAction({\n                        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                        \"Properties\": {\n                            \"Title\": \"Confirmación\",\n                            \"Message\": `¿Estás seguro que quieres crear la solicitud?`,\n                            \"OKCaption\": \"Aceptar\",\n                            \"OnOK\": \"/appconsumos_qa_mb/Actions/oData/Create_SolicitudApp_Abastecimiento.action\",\n                            \"CancelCaption\": \"Cancelar\"\n                        }\n                    });\n                    //return context.executeAction(\"/appconsumos_qa_mb/Actions/oData/Create_Solicitud_Campo.action\");\n                }\n \n                return context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Alerta\",\n                        \"Message\": `Debes ingresar al menos un material a la solicitud para continuar`\n                    }\n                });\n            }\n \n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Alerta\",\n                    \"Message\": `Número de ficha no encontrada. Debes ingresar un número de ficha válido para continuar`\n                }\n            });\n \n        }).catch((error) => {\n           \n            alert(`Error al encontrar la ficha ${error.message}`)\n        });\n \n    }\n \n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n        \"Properties\": {\n            \"Title\": \"Alerta\",\n            \"Message\": `Debes ingresar el número de ficha para continuar`\n        }\n    });\n    \n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function filter_Read_ZBIW_MARDT(context) {\n    let clientDataFiltro = context.evaluateTargetPathForAPI('#Page:Filtro_Almacen_Solicitud_Abast').getClientData();\n\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'AlmacenesApp', [], `$filter=sociedad eq '${clientDataFiltro.almacen_abast.sociedad}' and almacen ne '${clientDataFiltro.almacen_abast.almacen}'`).then(async (results) => {\n        \n        if (results && results.length > 0) {\n            let filtro = `$filter=Werks eq '${clientDataFiltro.almacen_abast.centro}' and Spras eq 'ES' and contains(Txtmd, 'BORRADO') eq false and contains(Txtmd, 'BORRAR') eq false and contains(Txtmd, 'BORRAD_') eq false and (`\n\n            results.forEach(e => {\n                filtro += `Lgort eq '${e.almacen}' or `      \n            });\n\n            clientDataFiltro.filtroMaterial = filtro.slice(0, -4)+\")&$orderby=Matnr\"\n            return context.executeAction(\"/appconsumos_qa_mb/Actions/oData/Read_ZBIW_MARDTSet.action\");\n\n        } \n    }).catch((error) => {\n        \n        alert(`Error al obtener los almacenes ${error.message}`)\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function getMaterialDesc_Confirmar_Abast(context) {\n    var binding = context.binding\n\n    if(typeof binding.mat_nuevo_desc === 'string'){\n        return binding.mat_nuevo_desc\n    }\n    if(typeof binding.material.material_desc === 'string'){\n        return binding.material.material_desc\n    }\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function getTipoColorMaterial_Confirmar_Abast(context) {\n    var binding = context.binding\n\n    if(typeof binding.mat_nuevo_desc === 'string'){\n        return \"Indigo\"\n    }\n    if(typeof binding.material.material_desc === 'string'){\n        return \"Grey\"\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function getTipoMaterial_Confirmar_Abast(context) {\n    var binding = context.binding\n\n\n    if(typeof binding.mat_nuevo_desc === 'string'){\n        return \"Nuevo\"\n    }\n    if(typeof binding.material.material_desc === 'string'){\n        return \"Registrado\"\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function get_Matnr_QueryRevisionAlmacenes(context) {\n\n    let clientData = context.evaluateTargetPathForAPI('#Page:Revision_Solicitud_Reabastecimiento').getClientData();\n    let clientDataAlm = context.evaluateTargetPathForAPI('#Page:Filtro_Almacen_Solicitud_Abast').getClientData();\n    \n\n    let mat_nuevo = clientData.infoMaterial.mat_nuevo\n    let material = clientData.infoMaterial.material_material\n    let value = ''\n\n    if(mat_nuevo){\n        value =  clientData.infoMaterial.mat_nuevo\n    }\n\n    if(material){\n        value = clientData.infoMaterial.material_material.replace(/^0+/, '')\n    }\n\n    //let clientDataFiltro = context.evaluateTargetPathForAPI('#Page:Filtro_Ingenio').getClientData();\n \n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'AlmacenesApp', [], `$filter=tipo eq 'INGENIO'`).then(async (results) => {\n       \n        if (results && results.length > 0) {\n            let filtro = `$filter=Matnr eq '${value}' and Werks eq '${clientDataAlm.almacen_abast.centro}' and Spras eq 'ES' and contains(Txtmd, 'BORRADO') eq false and contains(Txtmd, 'BORRAR') eq false and contains(Txtmd, 'BORRAD_') eq false and (`\n \n            results.forEach(e => {\n                filtro += `Lgort eq '${e.almacen}' or `      \n            });\n \n            //clientDataFiltro.filtroMaterial = filtro.slice(0, -4)+\")&$orderby=Matnr\"\n            //alert(clientDataFiltro.filtroMaterial)\n            //el centro esta indefinido\n            return filtro.slice(0, -4)+\")&$orderby=Lgort\"\n            \n \n        }\n        return null;\n    }).catch((error) => {\n       \n        alert(`Error al obtener los almacenes ${error.message}`)\n    });\n\n    //return `$filter=Matnr eq '${value}' and Spras eq 'ES' and contains(Txtmd, 'BORRADO') eq false and contains(Txtmd, 'BORRAR') eq false and contains(Txtmd, 'BORRAD_') eq false and Werks eq '${clientDataAlm.almacen_abast.centro}'&$orderby=Lgort`\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function get_desc_Material_Revisar(context) {\n    let mat_nuevo = context.binding.mat_nuevo\n    let material = context.binding.material_material\n\n    if(mat_nuevo){\n        return context.binding.mat_nuevo_desc\n    }\n\n    if(material){\n        return context.binding.material.material_desc\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function get_unidad_Revisar(context) {\n    let mat_nuevo = context.binding.mat_nuevo\n    let material = context.binding.material_material\n    let cantidad_tomada = context.binding.cantidad_tomada\n\n    //Cant. Solicitada: {cantidad_tomada}\n\n    if(mat_nuevo){\n        return `Cant.Solicitada ${cantidad_tomada} ${context.binding.mat_nuevo_und}`\n    }\n\n    if(material){\n        return `Cant.Solicitada ${cantidad_tomada} ${context.binding.material.und}`\n    }\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function onChange_Materiales_Revision_Abast(context) {\n\n    const pageProxy = context.getPageProxy();\n    var cantSolicitada = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell1\")\n    var btn_aprobar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\")\n \n    cantSolicitada.setVisible(false)\n    btn_aprobar.setVisible(true)\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function setVisible_CantAprobadaRevision_Abast(context) {\n\n    const pageProxy = context.getPageProxy();\n    var cantSolicitada = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell1\")\n    var cant_field = cantSolicitada.getControl(\"FormCellSimpleProperty_Cantidad\")\n    var btn_aprobar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\")\n    let clientData = context.evaluateTargetPathForAPI('#Page:Revision_Solicitud_Reabastecimiento').getClientData();\n\n \n    let almacen = context.evaluateTargetPath('#Page:Revision_Sol_Almacenes_Abast/#Control:almacen/#Value')\n \n    if (almacen.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Almacén no seleccionado\",\n                \"Message\": `Debes seleccionar un almacen para continuar`\n            }\n        });\n    }\n\n    var data = almacen[0].BindingObject\n\n    if (data.Labst < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Almacén sin stock\",\n                \"Message\": `El almacén seleccionado no tiene stock disponible para este material.`\n            }\n        });\n    }\n\n   \n    cantSolicitada.setVisible(true);\n \n    setTimeout(() => {\n        var cantSol = clientData.infoMaterial.cantidad_tomada\n        cant_field.setValue(cantSol);\n        btn_aprobar.setVisible(false);\n    }, 200);\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function setVisible_CrearSolicitudAbast(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData.info_user;\n\n    return info.rol === 'Técnico';\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function set_VisibleAgregarMaterialExistente(context) {\n    const pageProxy = context.getPageProxy();\n    var agregarMaterialExistente = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell1\")\n    var agregarMaterialNuevo = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell2\")\n    agregarMaterialExistente.setVisible(true)\n    agregarMaterialNuevo.setVisible(false)\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function set_VisibleAgregarMaterialNuevo(context) {\n\n    let clientDataFiltro = context.evaluateTargetPathForAPI('#Page:Filtro_Almacen_Solicitud_Abast').getClientData();\n    const pageProxy = context.getPageProxy();\n    var agregarMaterialExistente = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell1\")\n    var agregarMaterialNuevo = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell2\")\n\n    agregarMaterialExistente.setVisible(false)\n    agregarMaterialNuevo.setVisible(true)\n    agregarMaterialNuevo.redraw(true)\n\n    let actionResult = context.getActionResult(\"Read_ZBIW_MARDTSet\");\n    let string = JSON.stringify(actionResult.data)\n    //alert(JSON.stringify(JSON.parse(string)[0]))\n\n    let lista = JSON.parse(string)\n\n    const resultadoListPicker = [];\n    const vistos = new Set();\n\n    for (const item of lista) {\n        if (!vistos.has(item.Matnr)) {\n            vistos.add(item.Matnr);\n            resultadoListPicker.push({\n                ObjectCell: {\n                    Title: item.Matnr,\n                    Subhead: item.Txtmd,\n                    StatusText: item.Meins,\n                    PreserveIconStackSpacing: false,\n                    Visible: true\n                },\n                ReturnValue: item.Matnr\n            });\n        }\n    }\n\n    clientDataFiltro.materiales_nuevos = resultadoListPicker\n\n}\n","export default function LogLevels(clientAPI) {\n    var levels = [];\n    levels.push({\n        'DisplayValue': 'Error',\n        'ReturnValue': 'Error',\n    });\n    levels.push({\n        'DisplayValue': 'Warning',\n        'ReturnValue': 'Warn',\n    });\n    levels.push({\n        'DisplayValue': 'Info',\n        'ReturnValue': 'Info',\n    });\n    levels.push({\n        'DisplayValue': 'Debug',\n        'ReturnValue': 'Debug',\n    });\n    levels.push({\n        'DisplayValue': 'Trace',\n        'ReturnValue': 'Trace',\n    });\n    return levels;\n}","export default function SetTraceCategories(clientAPI) {\n    var logger = clientAPI.getLogger();\n    const sectionedTable = clientAPI.getPageProxy().getControl('SectionedTable');\n    const fcsection = sectionedTable.getSection('FormCellSection0');\n    const traceCategory = fcsection.getControl('TracingCategoriesListPicker');\n    const odataTrace = fcsection.getControl('odataTrace');\n\n    try {\n        if (traceCategory.getValue()) {\n            var values = traceCategory.getValue();\n            var categories = [];\n\n            if (values && values.length) {\n                categories = values.map((value) => {\n                    return 'mdk.trace.' + value.ReturnValue;\n                });\n            }\n            clientAPI.setDebugSettings(odataTrace.getValue(), true, categories);\n        }\n    } catch (exception) {\n        logger.log(String(exception), 'Error');\n        return undefined;\n    }\n}","export default function SetUserLogLevel(clientAPI) {\n    try {\n        if (clientAPI.getValue() && clientAPI.getValue()[0]) {\n            var logger = clientAPI.getLogger();\n            var listPickerValue = clientAPI.getValue()[0].ReturnValue;\n            if (listPickerValue) {\n                switch (listPickerValue) {\n                    case 'Debug':\n                        logger.setLevel('Debug');\n                        ShowTraceOptions(clientAPI, false);\n                        break;\n                    case 'Error':\n                        logger.setLevel('Error');\n                        ShowTraceOptions(clientAPI, false);\n                        break;\n                    case 'Warn':\n                        logger.setLevel('Warn');\n                        ShowTraceOptions(clientAPI, false);\n                        break;\n                    case 'Info':\n                        logger.setLevel('Info');\n                        ShowTraceOptions(clientAPI, false);\n                        break;\n                    case 'Trace':\n                        logger.setLevel('Trace');\n                        ShowTraceOptions(clientAPI, true);\n                        break;\n                    default:\n                        // eslint-disable-next-line no-console\n                        console.log(`unrecognized key ${listPickerValue}`);\n                }\n                return listPickerValue;\n            }\n        }\n    } catch (exception) {\n        logger.log(String(exception), 'Error');\n        return undefined;\n    }\n}\n\nfunction ShowTraceOptions(clientAPI, tracingEnabled) {\n    let categories = clientAPI.getPageProxy().getControl('SectionedTable').getControl('TracingCategoriesListPicker');\n    let odataTrace = clientAPI.getPageProxy().getControl('SectionedTable').getControl('odataTrace');\n\n    categories.setVisible(tracingEnabled);\n    odataTrace.setVisible(tracingEnabled);\n}","export default function ToggleLogging(clientAPI) {\n    try {\n        var logger = clientAPI.getLogger();\n        const sectionedTable = clientAPI.getPageProxy().getControl('SectionedTable');\n        const fcsection = sectionedTable.getSection('FormCellSection0');\n        const enableLogSwitch = fcsection.getControl('EnableLogSwitch');\n        const logLevelListPicker = fcsection.getControl('LogLevelListPicker');\n        let switchValue = enableLogSwitch.getValue();\n        if (switchValue) {\n            logger.on();\n            logLevelListPicker.setVisible(true);\n            logLevelListPicker.setEditable(true);\n            logLevelListPicker.redraw();\n        } else {\n            logger.off();\n            logLevelListPicker.setEditable(false);\n            logLevelListPicker.setVisible(false);\n            logLevelListPicker.redraw();\n        }\n        return switchValue;\n    } catch (exception) {\n        logger.log(String(exception), 'Error');\n        return undefined;\n    }\n}","export default function TraceCategories(clientAPI) {\n    var categories = ['action', 'api', 'app', 'binding', 'branding',\n        'core', 'i18n', 'lcms', 'logging', 'odata', 'onboarding', 'profiling', 'push',\n        'restservice', 'settings', 'targetpath', 'ui'\n    ];\n\n    var values = [];\n    categories.forEach((category) => {\n        values.push({\n            'DisplayValue': category,\n            'ReturnValue': category,\n        });\n    });\n\n    return values;\n}","export default function UserLogSetting(clientAPI) {\n\n    try {\n        var logger = clientAPI.getLogger();\n\n        const sectionedTable = clientAPI.getControl('SectionedTable');\n        const fcsection = sectionedTable.getSection('FormCellSection0');\n        const enableLogSwitch = fcsection.getControl('EnableLogSwitch');\n        const logLevelListPicker = fcsection.getControl('LogLevelListPicker');\n        const traceCategory = fcsection.getControl('TracingCategoriesListPicker');\n        const odataTrace = fcsection.getControl('odataTrace');\n\n\n        //Persist the user logging preferences\n        if (logger) {\n            console.log(\"in logger state\");\n            if (logger.isTurnedOn()) {\n                if (enableLogSwitch) {\n                    enableLogSwitch.setValue(true);\n                }\n                if (logLevelListPicker) {\n                    logLevelListPicker.setEditable(true);\n                }\n            } else {\n                if (enableLogSwitch) {\n                    enableLogSwitch.setValue(false);\n                }\n                if (logLevelListPicker) {\n                    logLevelListPicker.setEditable(false);\n                }\n            }\n            var logLevel = logger.getLevel();\n            if (logLevel) {\n                if (logLevelListPicker) {\n                    logLevelListPicker.setValue([logLevel]);\n                }\n            }\n            if (logLevel === 'Trace') {\n                traceCategory.setVisible(true);\n                odataTrace.setVisible(true);\n            }\n\n            //Upon selecting a value in the List picker and clicking the back button \n            //will enable the onload page rule. This will set the selected value\n            //in the control\n            if (logLevelListPicker.getValue()[0]) {\n                var returnValue = logLevelListPicker.getValue()[0].ReturnValue;\n                if (returnValue) {\n                    logLevelListPicker.setValue([returnValue]);\n                    logger.setLevel(returnValue);\n                }\n            }\n        }\n    } catch (exception) {\n        // eslint-disable-next-line no-console\n        console.log(String(exception), 'Error User Logger could not be set');\n    }\n}","//import * as fs from '@nativescript/core/file-system';\n//import { isAndroid } from \"@nativescript/core/platform\";\n\nexport default function Rule_openDocumentoAnd(context) {\n\n    let clientDataAutorizar = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitud_Reabastecimieto').getClientData();\n    const fs = context.nativescript.fileSystemModule;\n    //const platform = context.nativescript.platformModule;  \n    //let actionResult = context.getActionResult(\"GetArchivo\");\n    //let b64Data = actionResult.data.Archivo;\n    //let formato = actionResult.data.FormatoArc.toLowerCase();\n    let b64Data = clientDataAutorizar.b64Data\n    let formato = \"pdf\"\n\n    //Para generar un nombre aleatorio al documento\n    function generateRandomWithSpecialChars() {\n        const specialChars = ['!', '@', '#', '$', '%', '^', '&', '*', '(', ')', '_', '+', '=', '{', '}', '[', ']', '|', '\\\\', ':', ';', '\"', '<', '>', '?', '/', '.', ',', '`', '~'];\n        const randomIndex1 = Math.floor(Math.random() * specialChars.length);\n        const randomIndex2 = Math.floor(Math.random() * specialChars.length);\n\n        const randomNumber = Math.floor(Math.random() * 1001);  // Genera un número entre 0 y 1000\n\n        return specialChars[randomIndex1] + randomNumber + specialChars[randomIndex2];\n    }\n\n    //Para convertir un data buffer a native byte array\n    let _Cover = function (byteArray) {\n        let array = android.util.Base64.decode(byteArray, android.util.Base64.DEFAULT);\n\n        /*if (platform.isAndroid) {\n            array = android.util.Base64.decode(byteArray, android.util.Base64.DEFAULT);\n        } else if(platform.isIOS){\n            alert(\"entro\");\n            array = NSData.dataWithBytesLength(byteArray, byteArray.byteLength);\n        }*/\n        return array;\n    }\n\n    let mimeType=\"\";\n\n    switch(formato){\n        case \"pdf\":\n            mimeType = \"application/pdf\"\n        break;\n        case \"png\":\n            mimeType = \"image/png\"\n        break;\n        case \"jpg\":\n            mimeType = \"image/jpeg\"\n        default:\n            mimeType = \"text/plain\"\n    };\n\n    let docConver = _Cover(b64Data);\n    \n\n    let filename = `${generateRandomWithSpecialChars()}.${formato}`;\n    var tempDir = fs.knownFolders.documents();\n    var folder = \"Files\";\n\n    if (!fs.Folder.exists(fs.path.join(tempDir.path, folder))) {\n        fs.Folder.fromPath(fs.path.join(tempDir.path, folder));\n    }\n\n    var filePath = fs.path.join(tempDir.path, folder, filename);\n    var productFile = fs.File.fromPath(filePath);\n    //alert(\"Saving the file at: \" + filePath);\n\n    try {\n        productFile.writeSync(docConver);\n    } catch (err) {\n        productFile.remove();\n        alert(\"WRITE SYNC FAILED: \" + err);\n    }\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/openDocument.action\",\n        \"Properties\":{\n            \"Path\": filePath,\n            \"MimeType\": mimeType,\n            \"OnSuccess\":\"\"\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default async function Rule_openDocumentoIOS(context) {\n\n    let clientDataAutorizar = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitud_Reabastecimieto').getClientData();\n    const fs = context.nativescript.fileSystemModule;\n\n    //let actionResult = context.getActionResult(\"GetArchivo\");\n    //let b64Data = actionResult.data.Archivo;\n    //let formato = actionResult.data.FormatoArc.toLowerCase();\n    let b64Data = clientDataAutorizar.b64Data\n    let formato = \"pdf\"\n\n    \n    function generateRandomWithSpecialChars() {\n        const specialChars = ['!', '@', '#', '$', '%', '^', '&', '*', '(', ')', '_', '+', '=', '{', '}', '[', ']', '|', '\\\\', ':', ';', '\"', '<', '>', '?', '/', '.', ',', '`', '~'];\n        const randomIndex1 = Math.floor(Math.random() * specialChars.length);\n        const randomIndex2 = Math.floor(Math.random() * specialChars.length);\n\n        const randomNumber = Math.floor(Math.random() * 1001);  // Genera un número entre 0 y 1000\n\n        return specialChars[randomIndex1] + randomNumber + specialChars[randomIndex2];\n    }\n\n    function Cover(byteArray){\n        var array = NSData.dataWithBytesLength(byteArray.bytes, byteArray.length);\n        return array;\n    }\n\n    let mimeType = \"\";\n\n    switch (formato) {\n        case \"pdf\":\n            mimeType = \"application/pdf\"\n            break;\n        case \"png\":\n            mimeType = \"image/png\"\n            break;\n        case \"jpg\":\n            mimeType = \"image/jpeg\"\n        default:\n            mimeType = \"text/plain\"\n    };\n\n    let docConver = null;\n    //let imageData = `data:${mimeType};base64,${b64Data}`;\n\n    await context.base64StringToBinary(b64Data).then((result) => {\n        docConver = Cover(result);\n    }).catch((error) => {\n        alert(\"Error: \" + error.message);\n        throw error;\n    });\n\n    let filename = `${generateRandomWithSpecialChars()}.${formato}`;\n    var tempDir = fs.knownFolders.documents();\n    var folder = \"Files\";\n\n    if (!fs.Folder.exists(fs.path.join(tempDir.path, folder))) {\n        fs.Folder.fromPath(fs.path.join(tempDir.path, folder));\n    }\n\n    var filePath = fs.path.join(tempDir.path, folder, filename);\n    var productFile = fs.File.fromPath(filePath);\n    //alert(\"Saving the file at: \" + filePath);\n\n    if(docConver != null){\n        \n        try {\n            productFile.writeSync(docConver);\n        } catch (err) {\n            productFile.remove();\n            alert(\"WRITE SYNC FAILED: \" + err);\n        }\n\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/openDocument.action\",\n            \"Properties\":{\n                \"Path\": filePath,\n                \"MimeType\": mimeType\n            }\n        });\n\n    }else{\n        alert(\"No OK\");  \n    }\n\n}\n","export default function Initialize(context) {\n\n    // Perform pre data initialization task\n\n    // Initialize all your Data sources\n    let _app_consumos_qa = context.executeAction('/appconsumos_qa_mb/Actions/app_consumos_qa/Service/InitializeOffline.action');\n    let _app_consumos_qa_v2 = context.executeAction('/appconsumos_qa_mb/Actions/backend_REST/Service/InitializeOffline.action');\n    let ZBODEGA_AGO_SRV = context.executeAction('/appconsumos_qa_mb/Actions/ZBODEGA_AGO_SRV/Service/InitializeOffline.action');\n    let ZAMANAGE_LOGISTIC = context.executeAction('/appconsumos_qa_mb/Actions/ZAMANAGE_LOGISTIC/Service/InitializeOffline.action');\n\n    //You can add more service initialize actions here\n\n    return Promise.all([_app_consumos_qa, ZBODEGA_AGO_SRV, _app_consumos_qa_v2, ZAMANAGE_LOGISTIC]).then(() => {\n        // After Initializing the DB connections\n\n        // Display successful initialization  message to the user\n        return context.executeAction({\n\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n            \"Properties\": {\n                \"Message\": \"Servicios de la aplicación inicializados\",\n                \"Animated\": true,\n                \"Duration\": 1,\n                \"IsIconHidden\": true,\n                \"NumberOfLines\": 1,\n                \"OnSuccess\": \"/appconsumos_qa_mb/Actions/app_consumos_qa/Service/UploadOffline.action\",\n            }\n        });\n    }).catch(() => {\n        return false;\n    });\n}","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function CheckForSyncError(context) {\n    context.count('/appconsumos_qa_mb/Actions/ZBODEGA_AGO_SRV/.service', 'ErrorArchive', '').then(errorCount => {\n        if (errorCount > 0) {\n            return context.getPageProxy().executeAction('/appconsumos_qa_mb/Actions/ErrorArchive/ErrorArchive_SyncFailure.action').then(function() {\n                return Promise.reject(false);\n            });\n        }\n    });\n}\n ","import get_Info_Usuario from '../get_Info_Usuario';\n/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function CheckForSyncError(context) {\n        context.count('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ErrorArchive', '').then(errorCount => {\n        if (errorCount > 0) {\n            return context.getPageProxy().executeAction('/appconsumos_qa_mb/Actions/ErrorArchive/ErrorArchive_SyncFailure.action').then(function() {\n                return Promise.reject(false);\n            });\n        }else {\n            return get_Info_Usuario(context)\n        }\n    });\n}","import get_SolicitudesOrdenesAbiertas from '../Campo/get_SolicitudesOrdenesAbiertas';\nimport get_SolicitudesOrdenesAbiertasIngenio from '../Ingenio/get_SolicitudesOrdenesAbiertasIngenio';\n\n/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function OnlyCheckForSyncError(context) {\n    let proxy = context.getPageProxy()\n    let caption = proxy.getName()\n    //Lista_Solicitudes_Campo\n    \n    context.count('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ErrorArchive', '').then(errorCount => {\n        if (errorCount > 0) {\n            return context.getPageProxy().executeAction('/appconsumos_qa_mb/Actions/ErrorArchive/ErrorArchive_SyncFailure.action').then(function () {\n                return Promise.reject(false);\n            });\n        } else {\n            if(caption == \"Lista_Solicitudes_Campo\"){\n                return get_SolicitudesOrdenesAbiertas(context)  \n            }      \n            \n            if(caption == \"Lista_Solicitudes_Ingenio\"){\n                return get_SolicitudesOrdenesAbiertasIngenio(context)\n                \n            }\n\n            if(caption == \"Lista_Solicitudes_Reabastecimiento\"){\n                //No es necesario redibujar la lista\n            }\n\n        }\n    });\n}","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function filter_Estado(context) {\n    var object = context.binding\n    alert(JSON.stringify(object))\n    return [\"estado eq Enviado\", \"estado eq Autorizado\"]\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function formatMaterialId(context) {\n\n    let valor = [context.binding.material, context.binding.material_material, context.binding.mat_nuevo]\n        .find(v => typeof v === 'string' && v.trim() !== '');\n\n    let limpio = valor ? valor.replace(/^0+/, '') : '';\n\n    return limpio;\n\n\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function formatOrdenId(context) {\n    let page = context.getPageProxy();\n    let titulo = page.getName();\n    if (titulo == \"Agregar_Solicitud_Campo\" || titulo == \"Detalle_Solicitudes_Campo\" || titulo == \"Agregar_Solicitud_Ingenio\" || titulo == \"Detalle_Solicitudes_Ingenio\") {\n        let valor = context.binding.orden;\n        let limpio = valor.replace(/^0+/, '');\n\n        return `Orden: ${limpio}`;\n    }\n\n    \n    if (titulo == \"Detalle_Orden_Campo\" || titulo == \"Lista_Ordenes_Campo\" || titulo == \"Lista_Solicitudes_Campo\" || titulo == \"Detalle_Orden_Ingenio\" || titulo == \"Lista_Ordenes_Ingenio\" || titulo == \"Lista_Solicitudes_Ingenio\") {\n        let valor = context.binding.orden;\n        let limpio = valor.replace(/^0+/, '');\n\n        return limpio;\n\n    }\n\n    if ( titulo ==\"Lista_Historico_Ingenio\" || titulo ==\"Detalle_Historico_Ingenio\" || titulo ==\"Lista_Historico_Campo\"|| titulo ==\"Detalle_Historico_Campo\") {\n        let valor = context.binding.orden_orden;\n        let limpio = valor.replace(/^0+/, '');\n        return limpio;\n\n    }\n\n    if (titulo == \"Revisar_Planilla_Aceite_Motor\" ) {\n        let valor = context.binding.orden_orden;\n        let limpio = valor? valor.replace(/^0+/, '') : \"\";\n        return  `Orden: ${limpio}`;\n\n    }\n\n\n\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function get_ConfirmacionTec(context) {\n    var object = context.binding\n    var confirmacion_tec = object.confirmacion_tec\n    if(!confirmacion_tec || confirmacion_tec === false){\n        return 'Entregado: No'\n    }\n\n    return 'Entregado: Si';\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function get_FechaHoraCol(context) {\n\n    let fechaUTC = new Date();\n\n    // Ajustar a hora de Colombia (UTC-5)\n    let offsetColombia = -5 * 60; // en minutos\n    fechaUTC.setMinutes(fechaUTC.getMinutes() + offsetColombia + fechaUTC.getTimezoneOffset());\n\n    let dia = fechaUTC.getDate().toString().padStart(2, '0');\n    let mes = (fechaUTC.getMonth() + 1).toString().padStart(2, '0');\n    let anio = fechaUTC.getFullYear();\n\n    let horas = fechaUTC.getHours();\n    let minutos = fechaUTC.getMinutes().toString().padStart(2, '0');\n    let segundos = fechaUTC.getSeconds().toString().padStart(2, '0');\n\n    let ampm = horas >= 12 ? 'p. m.' : 'a. m.';\n    horas = horas % 12;\n    horas = horas === 0 ? 12 : horas; // el 0 en formato 12h es 12\n\n    let horaFormateada = `${horas.toString().padStart(2, '0')}:${minutos}:${segundos} ${ampm}`;\n    let fechaFormateada = `${dia}-${mes}-${anio} ${horaFormateada}`;\n\n    return fechaFormateada;\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function get_Info_Usuario(context) {\n    let email = context.evaluateTargetPath('#Application/#AppData/UserId').toUpperCase();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    clientData.info_user = {}\n\n    //Syncroniza el servicio de datos del ERP\n    context.executeAction( \"/appconsumos_qa_mb/Actions/ZBODEGA_AGO_SRV/Service/UploadOffline.action\");\n\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'EmpleadosApp', [], `$filter=correo eq '${email}'`).then(async (results) => {\n        if (results && results.length > 0) {\n            clientData.info_user = results.getItem(0)\n        } \n    }).catch((error) => {\n        \n        alert(`Error ${error.message}`)\n    });\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function get_Now_DateTime_Col(context) {\n\n    let fecha = new Date();\n\n    let dia = fecha.getDate().toString().padStart(2, '0');\n    let mes = (fecha.getMonth() + 1).toString().padStart(2, '0');\n    let anio = fecha.getFullYear();\n\n    //let fechaFormateada = `${dia}-${mes}-${anio}`;\n    let fechaFormateada = `${anio}-${mes}-${dia}`;\n\n    return fechaFormateada;\n}\n\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function get_Now_Datetime(context) {\n    //para esta opcion el campo debe ser un String(100)\n    //let fechaColombia = new Date().toLocaleString(\"es-CO\", { timeZone: \"America/Bogota\" });\n    let fecha = new Date().toISOString();\n    return fecha\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function guid(context) {\n    function s4() {\n        return Math.floor((1 + Math.random()) * 0x10000).toString(16).substring(1);\n    }\n\n    function generarGUID() {\n        return s4() + s4() + '-' + s4() + '-' + s4() + '-' +\n               s4() + '-' + s4() + s4() + s4();\n    }\n\n    return generarGUID();\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function set_VisibleBtnAprobar(context) {\n    var object = context.binding\n    var estado = object.estado\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData.info_user;\n\n    return estado === 'Aprobado' && info.rol === 'Autorizador';\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function set_VisibleBtnConfirmar(context) {\n    var object = context.binding\n    var estado = object.estado\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData.info_user;\n\n    return estado === 'Autorizado' && info.rol === 'Técnico';\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function set_VisibleBtnNetear(context) {\n    //Esta regla se usa en el boton de Salida en abastecimiento, en Netear en Ingenio, y en liquidar en Campo\n    var object = context.binding\n    var estado = object.estado\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData.info_user;\n\n    //return estado === 'Autorizado' && info.rol === 'Auxiliar';\n    return false\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function set_VisibleBtnRevisar(context) {\n    var object = context.binding\n    var estado = object.estado\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData.info_user;\n    /* \n      if (estado === 'Enviado' && info.rol === 'Auxiliar') {\n        return true;\n    } else{\n        return false;\n    }\n    */\n\n    return estado === 'Enviado' && info.rol === 'Auxiliar';\n\n}\n","// Imports\nvar ___CSS_LOADER_API_SOURCEMAP_IMPORT___ = require(\"../../../../../../../css-loader/dist/runtime/sourceMaps.js\");\nvar ___CSS_LOADER_API_IMPORT___ = require(\"../../../../../../../css-loader/dist/runtime/api.js\");\nvar ___CSS_LOADER_EXPORT___ = ___CSS_LOADER_API_IMPORT___(___CSS_LOADER_API_SOURCEMAP_IMPORT___);\n// Module\n___CSS_LOADER_EXPORT___.push([module.id, `/* The LESS stylesheet provides the ability to define styling styles that can be used to style the UI in the MDK app.\n\nExamples:\n\n@mdkYellow1: #ffbb33;\n@mdkRed1: #ff0000;\n\n//// By-Type style: All Pages in the application will now have a yellow background\nPage\n\n{ background-color: @mdkYellow1; }\n//// By-Name style: All Buttons with _Name == \"BlueButton\" will now have this style\n#BlueButton\n\n{ color: @mdkYellow1; background-color: #0000FF; }\n//// By-Class style: These style classes can be referenced from rules and set using ClientAPI setStyle function\n\n.MyButton\n\n{ color: @mdkYellow1; background-color: @mdkRed1; }\n*/\nActionBar {\n  color: white ;\n  background-color: #72BE44;\n}\n.HeaderAdmin {\n  color: white;\n  backgroun